//! The core document model: a stack of same-sized RGBA layers.
//!
//! Layer 0 is the bottom of the stack; the last layer is the top. Every layer
//! owns a document-sized, non-premultiplied RGBA8 buffer, which keeps the
//! compositor free of per-layer bounds arithmetic. Source images smaller than
//! the document are pasted at the origin and padded with transparency; larger
//! ones are clipped.

use std::sync::Arc;

use serde::{Deserialize, Serialize};

use crate::blend::BlendMode;
use crate::composite::{to_byte, to_unit, Rect};

pub type LayerId = u64;

/// Bytes per pixel in every buffer this module produces or accepts.
pub const CHANNELS: usize = 4;

#[derive(Debug, Clone)]
pub struct Layer {
    pub id: LayerId,
    pub name: String,
    pub visible: bool,
    /// `0.0..=1.0`, multiplied into the layer's own alpha at composite time.
    pub opacity: f32,
    pub blend_mode: BlendMode,
    /// Blocks paint/erase strokes onto this layer's pixels — Photoshop's
    /// "Lock image pixels", the one lock sub-mode that actually protects
    /// against the edits this app can make. Compositing (visibility,
    /// opacity, blend mode, stacking order) is untouched by it: those
    /// aren't edits to the layer's own pixel data.
    pub locked: bool,
    /// Layer > Link Layers: linked layers move together under the Move
    /// tool — one link set for the whole document, as in Photoshop's
    /// original linking.
    pub linked: bool,
    /// Layer > Create Clipping Mask: this layer shows only where the
    /// nearest unclipped layer below it (its base) has pixels, its alpha
    /// scaled by the base's transparency; a hidden base hides it too.
    pub clipped: bool,
    /// Layer > Layer Mask: a document-sized 8-bit mask multiplied into the
    /// layer's alpha at composite time (`255` shows, `0` hides), or `None`
    /// for an unmasked layer.
    pub mask: Option<Vec<u8>>,
    /// An adjustment layer: instead of its own pixels, this adjustment is
    /// applied live to everything composited beneath it, at the layer's
    /// opacity, through its mask and clipping like any other layer.
    pub adjustment: Option<Adjustment>,
    /// A fill layer: the recipe its pixels were rendered from, so
    /// [`Document::set_fill`] can re-render them. The pixels are ordinary
    /// otherwise — paintable, movable, filterable like any other layer's.
    pub fill: Option<Fill>,
    /// A text layer: the type its pixels were set from, so
    /// [`Document::set_text`] can set it again.
    pub text: Option<TextLayer>,
    /// A shape layer: the shape its pixels were drawn from, so
    /// [`Document::set_shape`] can draw it again.
    pub shape: Option<ShapeLayer>,
    /// A smart object: the pixels it embeds and the transform they are
    /// shown through, so [`Document::set_smart_transform`] can show them
    /// through another without loss.
    pub smart: Option<SmartObject>,
    /// Document-sized, non-premultiplied RGBA8.
    pub pixels: Vec<u8>,
}

/// The subset of a layer the UI needs — everything except the pixels.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
#[serde(rename_all = "camelCase")]
pub struct LayerView {
    pub id: LayerId,
    pub name: String,
    pub visible: bool,
    pub opacity: f32,
    pub blend_mode: BlendMode,
    pub locked: bool,
    pub linked: bool,
    pub clipped: bool,
    /// Whether the layer carries a layer mask.
    pub has_mask: bool,
    /// The live adjustment of an adjustment layer; `None` for a pixel layer.
    pub adjustment: Option<Adjustment>,
    /// The recipe of a fill layer; `None` for any other layer.
    pub fill: Option<Fill>,
    /// The type of a text layer; `None` for any other layer.
    pub text: Option<TextLayer>,
    /// The shape of a shape layer; `None` for any other layer.
    pub shape: Option<ShapeLayer>,
    /// A smart object's current transform; `None` for any other layer.
    pub smart: Option<FreeTransform>,
}

impl Layer {
    pub fn view(&self) -> LayerView {
        LayerView {
            id: self.id,
            name: self.name.clone(),
            visible: self.visible,
            opacity: self.opacity,
            blend_mode: self.blend_mode,
            locked: self.locked,
            linked: self.linked,
            clipped: self.clipped,
            has_mask: self.mask.is_some(),
            adjustment: self.adjustment,
            fill: self.fill,
            text: self.text.clone(),
            shape: self.shape.clone(),
            smart: self.smart.as_ref().map(|s| s.transform),
        }
    }

    /// Whether this layer can affect the composite at all.
    pub fn contributes(&self) -> bool {
        self.visible && self.opacity > 0.0
    }
}

#[derive(Debug, Clone)]
pub struct Document {
    width: u32,
    height: u32,
    /// Bottom-to-top.
    layers: Vec<Layer>,
    next_id: LayerId,
    /// `None` means no active selection — the same as Photoshop's "Select
    /// All" state: every command that respects a selection treats a `None`
    /// document as unrestricted.
    selection: Option<Selection>,
    /// The selection `deselect` most recently cleared, kept around for
    /// `reselect` (Select > Reselect) to restore. Not touched by making a
    /// new selection while one is already active — only by `deselect`.
    last_selection: Option<Selection>,
    /// The most recent non-neutral transform (`rotate`, `scale`, `skew`,
    /// or `free_transform`), kept for `transform_again` (Edit > Transform
    /// > Again) to repeat. Travels with the document through undo/redo.
    last_transform: Option<FreeTransform>,
    /// The pattern most recently captured by `define_pattern` (Edit >
    /// Define Pattern), for pattern fills to tile. Photoshop keeps patterns
    /// as application-wide presets; here the one defined pattern lives on
    /// the document, so it travels through undo/redo like everything else.
    pattern: Option<Pattern>,
    /// The brush tip Edit > Define Brush Preset captured, if any.
    brush_tip: Option<BrushTip>,
    /// The Pen tool family's current work path — see [`Path`].
    current_path: Option<Path>,
    /// Edit > Pattern Presets: patterns saved by name, in the order first
    /// saved — Photoshop keeps these as application-wide presets too;
    /// here they live on the document, like the one current pattern does.
    pattern_presets: Vec<(String, Pattern)>,
    /// Edit > Gradient Presets, in the order first saved.
    gradient_presets: Vec<GradientPreset>,
    /// Edit > Adjustment Presets, in the order first saved.
    adjustment_presets: Vec<AdjustmentPreset>,
    /// The Custom Shape tool's picker, in the order first saved.
    custom_shape_presets: Vec<CustomShapePreset>,
    /// Select > Save Selection's named selections, in the order first
    /// saved — Photoshop stores these as alpha channels; here they are the
    /// selections themselves (a mask's bitmap shared through its `Arc`),
    /// travelling through undo/redo with the document. Cleared, like the
    /// active selection, when the canvas changes size.
    saved_selections: Vec<(String, Selection)>,
    /// Image > Mode — see [`ColorMode`].
    mode: ColorMode,
    /// Indexed Color's colour table, empty in every other mode.
    color_table: Vec<[u8; 3]>,
    /// Duotone's inks, empty in every other mode.
    duotone: Vec<Ink>,
    /// Alpha channels made by Image > Calculations, in creation order —
    /// a byte per pixel each, discarded like every other position-bound
    /// thing when the canvas changes size.
    channels: Vec<AlphaChannel>,
    /// Spot colour channels, in overprinting order (the panel's order).
    spots: Vec<SpotChannel>,
    /// The Count tool's numbered marks, in placement order — document
    /// data in Photoshop too (they save with the file and undo), and
    /// discarded, like every position-bound thing here, when the canvas
    /// changes size.
    count_marks: Vec<(u32, u32)>,
    /// The Note tool's annotations, in placement order — document data,
    /// undoable, and discarded when the canvas changes size.
    notes: Vec<Note>,
    /// Layer Comps: named snapshots of every layer's visibility, opacity,
    /// and blend mode, in the order first saved. Keyed by layer id, so
    /// they survive reordering; layers deleted since are skipped on apply
    /// and layers added since are left alone.
    layer_comps: Vec<LayerComp>,
    /// View > New Guide's guides, in placement order, deduplicated.
    guides: Vec<Guide>,
    /// Layer > Group Layers' groups, in creation order.
    groups: Vec<LayerGroup>,
    /// The Artboard Tool's named regions, in creation order.
    artboards: Vec<Artboard>,
}

/// One layer's recorded state inside a [`LayerComp`].
#[derive(Debug, Clone, PartialEq)]
pub struct LayerCompState {
    pub id: LayerId,
    pub visible: bool,
    pub opacity: f32,
    pub blend_mode: BlendMode,
}

/// A Layer Comp: a named snapshot of the stack's visibility and appearance.
#[derive(Debug, Clone, PartialEq)]
pub struct LayerComp {
    pub name: String,
    pub states: Vec<LayerCompState>,
}

/// Layer > Group Layers: a named set of layer ids. Groups are metadata
/// over the flat layer stack — visibility, locking, linking, and moving
/// can be applied to every member at once — rather than a nested layer
/// tree; a group composites exactly as its members do (Photoshop's
/// Pass Through), and a layer belongs to at most one group.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct LayerGroup {
    pub name: String,
    /// Bottom to top, in stack order.
    pub members: Vec<LayerId>,
}

/// The Artboard Tool's named region: this app's canvas is a single fixed
/// size, so an artboard is a labelled rectangle of it — a stand-in for
/// Photoshop's own independently-sized canvases within one file — kept
/// only for [`Document::export_artboard`] to crop out on its own. Errors
/// on a crop or rotation the same way [`Path`] and the guides do: a
/// canvas-size change clears every artboard, a documented scope cut
/// short of recomputing their rectangles through it.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct Artboard {
    pub name: String,
    pub rect: Rect,
}

/// What Layer > Layer Mask starts a new mask from.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub enum MaskSource {
    /// A white mask: everything shows.
    RevealAll,
    /// A black mask: everything is hidden.
    HideAll,
    /// White inside the selection, black outside.
    RevealSelection,
    /// Black inside the selection, white outside.
    HideSelection,
}

/// What an adjustment layer does to everything beneath it — the four
/// Image > Adjustments this project can express as a pure per-pixel
/// function, kept live on the layer instead of baked into pixels.
#[derive(Debug, Clone, Copy, PartialEq, Serialize, Deserialize)]
#[serde(tag = "kind", rename_all = "camelCase")]
pub enum Adjustment {
    Invert,
    BrightnessContrast { brightness: i32, contrast: i32 },
    Threshold { level: u8 },
    Posterize { levels: u8 },
}

impl Adjustment {
    /// Photoshop's dialog bounds: a threshold level of `1..=255`, at least
    /// two posterize levels.
    pub fn validate(self) -> Result<(), String> {
        match self {
            Adjustment::Threshold { level: 0 } => {
                Err("Threshold level must be between 1 and 255.".to_string())
            }
            Adjustment::Posterize { levels } if levels < 2 => {
                Err("Posterize levels must be at least 2.".to_string())
            }
            _ => Ok(()),
        }
    }
}

/// One colour sampled for Select > Color Range, with the pixel it was
/// sampled from when it came off the image — what Localized Color
/// Clusters measures distance from.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct ColorSample {
    pub color: [u8; 3],
    pub position: Option<(u32, u32)>,
}

/// Select > Color Range's Select list: sampled colours with Fuzziness and
/// optional Localized Color Clusters (a Range in percent of the canvas
/// diagonal), or one of Photoshop's preset ranges — six hue sectors, three
/// tone bands, and skin tones.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(tag = "kind", rename_all = "camelCase")]
pub enum ColorRange {
    Sampled {
        samples: Vec<ColorSample>,
        fuzziness: u8,
        localized: Option<u8>,
    },
    Reds,
    Yellows,
    Greens,
    Cyans,
    Blues,
    Magentas,
    Highlights,
    Midtones,
    Shadows,
    SkinTones,
}

/// Apply Image's Channel list for an RGB source: the composite, one
/// colour channel applied as a grey, or the source's transparency — its
/// alpha as an opaque grey covering the whole canvas, as Photoshop's
/// Transparency channel does.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub enum ApplyChannel {
    Rgb,
    Red,
    Green,
    Blue,
    Transparency,
}

impl ApplyChannel {
    /// One byte of the pixel through this channel: a colour channel's own
    /// byte, Transparency the alpha, and RGB the BT.601 luma rounded —
    /// Photoshop's Gray, what a mask or a Calculations source reads.
    pub fn value(self, [r, g, b, a]: [u8; 4]) -> u8 {
        match self {
            ApplyChannel::Rgb => {
                (0.299 * r as f32 + 0.587 * g as f32 + 0.114 * b as f32).round() as u8
            }
            ApplyChannel::Red => r,
            ApplyChannel::Green => g,
            ApplyChannel::Blue => b,
            ApplyChannel::Transparency => a,
        }
    }

    /// The source pixel as Apply Image sees it through this channel:
    /// unchanged for RGB; `[v, v, v, a]` for one colour channel `v`, the
    /// source's own alpha kept; `[a, a, a, 255]` for Transparency.
    pub fn view(self, [r, g, b, a]: [u8; 4]) -> [u8; 4] {
        match self {
            ApplyChannel::Rgb => [r, g, b, a],
            ApplyChannel::Red => [r, r, r, a],
            ApplyChannel::Green => [g, g, g, a],
            ApplyChannel::Blue => [b, b, b, a],
            ApplyChannel::Transparency => [a, a, a, 255],
        }
    }
}

/// Apply Image's Mask group: a mask image — a layer, or with `None` the
/// merged composite — read through one channel and optionally inverted,
/// scaling the source's effective opacity pixel by pixel. Through RGB the
/// mask is the pixel's BT.601 luma (Photoshop's Gray), through a colour
/// channel that channel, through Transparency the alpha.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct ApplyMask {
    pub source: Option<LayerId>,
    pub channel: ApplyChannel,
    pub invert: bool,
}

impl ApplyMask {
    /// The mask's weight at one pixel, `0..=1`: the channel's byte
    /// ([`ApplyChannel::value`]), inverted if asked, over 255.
    pub fn weight(self, pixel: [u8; 4]) -> f32 {
        let value = self.channel.value(pixel);
        to_unit(if self.invert { 255 - value } else { value })
    }
}

/// Image > Calculations: one of its two sources — a layer (`None` for the
/// merged composite) read through one channel, optionally inverted.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct CalcSource {
    pub layer: Option<LayerId>,
    pub channel: ApplyChannel,
    pub invert: bool,
}

/// Where Image > Calculations sends its grey result.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub enum CalcResult {
    NewDocument,
    NewChannel,
    Selection,
}

/// What [`Document::calculations`] produced for its [`CalcResult`].
#[derive(Debug, Clone)]
pub enum CalcOutcome {
    /// A new grey document the size of this one.
    Document(Box<Document>),
    /// The name of the alpha channel added to this document.
    Channel(String),
    /// The selection was replaced.
    Selection,
}

/// Image > Mode: the document's colour mode. Pixels are always stored as
/// RGBA8; the mode is what a conversion made of them and what colours new
/// paint is constrained to — grey in Grayscale, black or white in Bitmap.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, Default)]
#[serde(rename_all = "camelCase")]
pub enum ColorMode {
    #[default]
    Rgb,
    Grayscale,
    Bitmap,
    /// Every pixel one of at most 256 colours in the document's colour
    /// table — see [`Palette`].
    Indexed,
    /// A grey image printed with one to four inks — see [`Ink`].
    Duotone,
    /// Pixels kept as RGB; the Channels panel shows the naive CMYK split
    /// of each pixel ([`cmyk_of`]).
    Cmyk,
    /// Pixels kept as RGB; the Channels panel shows L*, a*, b* of each
    /// pixel ([`lab_of`]).
    Lab,
    /// The composite split into Cyan, Magenta, and Yellow alpha channels.
    Multichannel,
}

/// A 3D colour lookup table — Image > Adjustments > Color Lookup's `.cube`
/// file: `size³` RGB triples in `0.0..=1.0`, red index running fastest,
/// sampled by trilinear interpolation.
#[derive(Debug, Clone, PartialEq)]
pub struct Lut3d {
    pub size: usize,
    pub table: Vec<[f32; 3]>,
    /// The input range the grid spans (`DOMAIN_MIN` / `DOMAIN_MAX`).
    pub domain: ([f32; 3], [f32; 3]),
}

impl Lut3d {
    /// The table's output for `rgb` (each `0.0..=1.0`, clamped): trilinear
    /// interpolation between the eight surrounding grid points.
    pub fn sample(&self, rgb: [f32; 3]) -> [f32; 3] {
        let n = self.size;
        let (lo, hi) = self.domain;
        let mut index = [0usize; 3];
        let mut frac = [0f32; 3];
        for c in 0..3 {
            let span = hi[c] - lo[c];
            let v = if span > 0.0 {
                ((rgb[c] - lo[c]) / span).clamp(0.0, 1.0)
            } else {
                0.0
            };
            let p = v * (n - 1) as f32;
            let i = (p.floor() as usize).min(n - 2);
            index[c] = i;
            frac[c] = p - i as f32;
        }
        let at = |r: usize, g: usize, b: usize| self.table[r + g * n + b * n * n];
        let lerp3 = |a: [f32; 3], b: [f32; 3], t: f32| {
            [
                a[0] + (b[0] - a[0]) * t,
                a[1] + (b[1] - a[1]) * t,
                a[2] + (b[2] - a[2]) * t,
            ]
        };
        let [r, g, b] = index;
        let [tr, tg, tb] = frac;
        let c00 = lerp3(at(r, g, b), at(r + 1, g, b), tr);
        let c10 = lerp3(at(r, g + 1, b), at(r + 1, g + 1, b), tr);
        let c01 = lerp3(at(r, g, b + 1), at(r + 1, g, b + 1), tr);
        let c11 = lerp3(at(r, g + 1, b + 1), at(r + 1, g + 1, b + 1), tr);
        let c0 = lerp3(c00, c10, tg);
        let c1 = lerp3(c01, c11, tg);
        lerp3(c0, c1, tb)
    }
}

/// Parses an Adobe/IRIDAS `.cube` file: `LUT_3D_SIZE n` (2 or more),
/// optional `TITLE`, `DOMAIN_MIN`, and `DOMAIN_MAX` lines, `#` comments,
/// and exactly `n³` lines of three numbers. 1D cubes (`LUT_1D_SIZE`) are a
/// documented scope cut.
pub fn parse_cube(text: &str) -> Result<Lut3d, String> {
    let mut size: Option<usize> = None;
    let mut domain = ([0.0f32; 3], [1.0f32; 3]);
    let mut table: Vec<[f32; 3]> = Vec::new();
    let triple = |line: &str, what: &str| -> Result<[f32; 3], String> {
        let values: Vec<f32> = line
            .split_whitespace()
            .map(|v| v.parse::<f32>())
            .collect::<Result<_, _>>()
            .map_err(|_| format!("Bad {what} line in the .cube file: \"{line}\"."))?;
        if values.len() != 3 || values.iter().any(|v| !v.is_finite()) {
            return Err(format!("Bad {what} line in the .cube file: \"{line}\"."));
        }
        Ok([values[0], values[1], values[2]])
    };
    for raw in text.lines() {
        let line = raw.trim();
        if line.is_empty() || line.starts_with('#') || line.starts_with("TITLE") {
            continue;
        }
        if let Some(rest) = line.strip_prefix("LUT_3D_SIZE") {
            let n: usize = rest
                .trim()
                .parse()
                .map_err(|_| "Bad LUT_3D_SIZE in the .cube file.".to_string())?;
            if n < 2 {
                return Err("LUT_3D_SIZE must be at least 2.".to_string());
            }
            size = Some(n);
        } else if let Some(rest) = line.strip_prefix("DOMAIN_MIN") {
            domain.0 = triple(rest, "DOMAIN_MIN")?;
        } else if let Some(rest) = line.strip_prefix("DOMAIN_MAX") {
            domain.1 = triple(rest, "DOMAIN_MAX")?;
        } else if line.starts_with("LUT_1D_SIZE") {
            return Err("1D .cube files are not supported; use a 3D LUT.".to_string());
        } else {
            table.push(triple(line, "table")?);
        }
    }
    let size = size.ok_or_else(|| "The .cube file has no LUT_3D_SIZE.".to_string())?;
    if table.len() != size * size * size {
        return Err(format!(
            "The .cube file should have {} entries for size {size}, not {}.",
            size * size * size,
            table.len()
        ));
    }
    Ok(Lut3d {
        size,
        table,
        domain,
    })
}

/// View > Proof Setup: the two dichromacies Photoshop's Color Blindness
/// proof simulates, or a Custom proof's Simulate Paper Color and
/// Simulate Black Ink, given as the paper white and ink black an
/// output device would actually reach — a documented stand-in for
/// Photoshop's own ICC-profile-driven white/black point compensation,
/// which this app's colour management (a scope cut) does not model.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub enum Proof {
    Protanopia,
    Deuteranopia,
    PaperInk { paper: [u8; 3], ink: [u8; 3] },
}

/// An sRGB pixel as a protanope or deuteranope would see it: linearised,
/// put through the Viénot–Brettel–Mollon (1999) reduction matrix for that
/// dichromacy, and re-encoded. Rows sum to one, so neutrals survive.
pub fn simulate_color_blindness([r, g, b]: [u8; 3], proof: Proof) -> [u8; 3] {
    let linear = |v: u8| {
        let c = to_unit(v);
        if c <= 0.04045 {
            c / 12.92
        } else {
            ((c + 0.055) / 1.055).powf(2.4)
        }
    };
    let encode = |c: f32| {
        let c = c.clamp(0.0, 1.0);
        let v = if c <= 0.0031308 {
            12.92 * c
        } else {
            1.055 * c.powf(1.0 / 2.4) - 0.055
        };
        to_byte(v)
    };
    let matrix: [[f32; 3]; 3] = match proof {
        Proof::Protanopia => [
            [0.56667, 0.43333, 0.0],
            [0.55833, 0.44167, 0.0],
            [0.0, 0.24167, 0.75833],
        ],
        Proof::Deuteranopia => [[0.625, 0.375, 0.0], [0.7, 0.3, 0.0], [0.0, 0.3, 0.7]],
        Proof::PaperInk { .. } => {
            unreachable!("simulate_color_blindness is only called for a dichromacy proof")
        }
    };
    let l = [linear(r), linear(g), linear(b)];
    let mut out = [0u8; 3];
    for (slot, row) in out.iter_mut().zip(matrix.iter()) {
        *slot = encode(row[0] * l[0] + row[1] * l[1] + row[2] * l[2]);
    }
    out
}

/// View > Proof Setup > Custom's Simulate Paper Color and Simulate
/// Black Ink: each channel linearly rescaled from the full `0..=255`
/// input range onto `ink[channel]..=paper[channel]` — the same
/// white/black point compensation Photoshop's own soft proof applies
/// for a device whose paper is not perfectly white and whose ink is not
/// perfectly black, standing in here for the full ICC-profile-driven
/// version this app's colour management does not model.
pub fn simulate_paper_ink([r, g, b]: [u8; 3], paper: [u8; 3], ink: [u8; 3]) -> [u8; 3] {
    let mix = |value: u8, paper: u8, ink: u8| {
        to_byte(to_unit(ink) + to_unit(value) * (to_unit(paper) - to_unit(ink)))
    };
    [
        mix(r, paper[0], ink[0]),
        mix(g, paper[1], ink[1]),
        mix(b, paper[2], ink[2]),
    ]
}

/// Edit > Transform > Warp's mesh: the sixteen control points of a
/// bicubic Bézier surface laid over the layer's opaque bounds, row-major
/// (`points[row * 4 + column]`, row 0 the top), each in pixel-index
/// coordinates. The identity mesh is the bounds' pixel-index rectangle
/// divided in thirds — see [`Document::warp_mesh`] and [`Document::warp`].
#[derive(Debug, Clone, Copy, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct WarpMesh {
    pub points: [[f32; 2]; 16],
}

/// Warp's Warp Style presets, each a placement of the sixteen control
