/// Whether an RGB pixel passes the classic skin-tone rule (R > 95, G > 40,
/// B > 20, spread > 15, R − G > 15, R > G, R > B) — Color Range's Skin
/// Tones and Content-Aware Scale's Protect Skin Tones.
pub fn is_skin_tone([r, g, b]: [u8; 3]) -> bool {
    let max = r.max(g).max(b);
    let min = r.min(g).min(b);
    r > 95 && g > 40 && b > 20 && max - min > 15 && r > g && r - g > 15 && r > b
}

/// A working image for seam carving: RGBA pixels with a protection
/// penalty per pixel, carved together.
#[derive(Clone)]
struct SeamImage {
    width: usize,
    height: usize,
    pixels: Vec<[u8; 4]>,
    penalty: Vec<u32>,
}

impl SeamImage {
    /// The energy of every pixel: the absolute luma differences to its
    /// four clamped neighbours, plus its penalty.
    fn energies(&self) -> Vec<u32> {
        let (w, h) = (self.width, self.height);
        let luma: Vec<i32> = self
            .pixels
            .iter()
            .map(|&px| i32::from(ApplyChannel::Rgb.value(px)))
            .collect();
        let at = |x: usize, y: usize| luma[y * w + x];
        let mut out = Vec::with_capacity(w * h);
        for y in 0..h {
            for x in 0..w {
                let me = at(x, y);
                let left = at(x.saturating_sub(1), y);
                let right = at((x + 1).min(w - 1), y);
                let up = at(x, y.saturating_sub(1));
                let down = at(x, (y + 1).min(h - 1));
                let e = (me - left).unsigned_abs()
                    + (me - right).unsigned_abs()
                    + (me - up).unsigned_abs()
                    + (me - down).unsigned_abs();
                out.push(e + self.penalty[y * w + x]);
            }
        }
        out
    }

    /// The cheapest top-to-bottom 8-connected seam, one column per row,
    /// ties broken toward the left at every step.
    fn vertical_seam(&self) -> Vec<usize> {
        let (w, h) = (self.width, self.height);
        let energy = self.energies();
        let mut cost = vec![0u64; w * h];
        cost[..w]
            .iter_mut()
            .zip(&energy[..w])
            .for_each(|(c, &e)| *c = u64::from(e));
        for y in 1..h {
            for x in 0..w {
                let lo = x.saturating_sub(1);
                let hi = (x + 1).min(w - 1);
                let best = (lo..=hi)
                    .map(|px| cost[(y - 1) * w + px])
                    .min()
                    .unwrap_or(0);
                cost[y * w + x] = best + u64::from(energy[y * w + x]);
            }
        }
        let mut seam = vec![0usize; h];
        let last = (h - 1) * w;
        let mut x = (0..w).min_by_key(|&px| (cost[last + px], px)).unwrap_or(0);
        seam[h - 1] = x;
        for y in (0..h - 1).rev() {
            let lo = x.saturating_sub(1);
            let hi = (x + 1).min(w - 1);
            x = (lo..=hi)
                .min_by_key(|&px| (cost[y * w + px], px))
                .unwrap_or(x);
            seam[y] = x;
        }
        seam
    }

    fn remove_seam(&mut self, seam: &[usize]) {
        let w = self.width;
        let mut pixels = Vec::with_capacity((w - 1) * self.height);
        let mut penalty = Vec::with_capacity((w - 1) * self.height);
        for (y, &sx) in seam.iter().enumerate() {
            for x in 0..w {
                if x != sx {
                    pixels.push(self.pixels[y * w + x]);
                    penalty.push(self.penalty[y * w + x]);
                }
            }
        }
        self.pixels = pixels;
        self.penalty = penalty;
        self.width -= 1;
    }

    /// Widens by `count` columns: the `count` cheapest seams found by
    /// carving a copy, mapped back to these columns, each duplicated as
    /// the average of itself and its right neighbour.
    fn insert_seams(&mut self, count: usize) {
        let (w, h) = (self.width, self.height);
        let mut probe = self.clone();
        let mut index: Vec<Vec<usize>> = (0..h).map(|_| (0..w).collect()).collect();
        let mut inserts: Vec<Vec<usize>> = vec![Vec::new(); h];
        for _ in 0..count {
            if probe.width < 2 {
                break;
            }
            let seam = probe.vertical_seam();
            for (y, &sx) in seam.iter().enumerate() {
                inserts[y].push(index[y][sx]);
                index[y].remove(sx);
            }
            probe.remove_seam(&seam);
        }
        let added = inserts[0].len();
        let mut pixels = Vec::with_capacity((w + added) * h);
        let mut penalty = Vec::with_capacity((w + added) * h);
        for (y, row_marks) in inserts.iter().enumerate() {
            let mut marks = row_marks.clone();
            marks.sort_unstable();
            for x in 0..w {
                let px = self.pixels[y * w + x];
                pixels.push(px);
                penalty.push(self.penalty[y * w + x]);
                for _ in marks.iter().filter(|&&m| m == x) {
                    let right = self.pixels[y * w + (x + 1).min(w - 1)];
                    let mut avg = [0u8; 4];
                    for c in 0..4 {
                        avg[c] = ((u16::from(px[c]) + u16::from(right[c])) / 2) as u8;
                    }
                    pixels.push(avg);
                    penalty.push(self.penalty[y * w + x]);
                }
            }
        }
        self.pixels = pixels;
        self.penalty = penalty;
        self.width = w + added;
    }

    fn transpose(&self) -> SeamImage {
        let (w, h) = (self.width, self.height);
        let mut pixels = Vec::with_capacity(w * h);
        let mut penalty = Vec::with_capacity(w * h);
        for x in 0..w {
            for y in 0..h {
                pixels.push(self.pixels[y * w + x]);
                penalty.push(self.penalty[y * w + x]);
            }
        }
        SeamImage {
            width: h,
            height: w,
            pixels,
            penalty,
        }
    }

    /// Nearest-neighbour resampling to `new_width × new_height`, each
    /// output pixel reading source `floor((i + 0.5) · old / new)`.
    fn resample(&self, new_width: usize, new_height: usize) -> SeamImage {
        let (w, h) = (self.width, self.height);
        let mut pixels = Vec::with_capacity(new_width * new_height);
        let mut penalty = Vec::with_capacity(new_width * new_height);
        for y in 0..new_height {
            let sy =
                (((y as f32 + 0.5) * h as f32 / new_height as f32).floor() as usize).min(h - 1);
            for x in 0..new_width {
                let sx =
                    (((x as f32 + 0.5) * w as f32 / new_width as f32).floor() as usize).min(w - 1);
                pixels.push(self.pixels[sy * w + sx]);
                penalty.push(self.penalty[sy * w + sx]);
            }
        }
        SeamImage {
            width: new_width,
            height: new_height,
            pixels,
            penalty,
        }
    }

    /// Carves or inserts vertical seams toward `target` width by `amount`
    /// percent of the difference, then resamples the rest.
    fn scale_width(&mut self, target: usize, amount: u8) {
        if target == self.width {
            return;
        }
        let difference = target.abs_diff(self.width);
        let carved = (difference as f32 * f32::from(amount) / 100.0).round() as usize;
        if target < self.width {
            for _ in 0..carved {
                if self.width < 2 {
                    break;
                }
                let seam = self.vertical_seam();
                self.remove_seam(&seam);
            }
        } else {
            self.insert_seams(carved);
        }
        if self.width != target {
            *self = self.resample(target, self.height);
        }
    }
}

/// The naive, profile-free CMYK split of an RGB pixel as ink coverages
/// `0..=255`: `K = 1 − max(r, g, b)` and each ink `(1 − channel − K) /
/// (1 − K)`, zero for black. Photoshop's own conversion goes through an
/// ICC press profile — a documented scope cut.
pub fn cmyk_of([r, g, b]: [u8; 3]) -> [u8; 4] {
    let (r, g, b) = (to_unit(r), to_unit(g), to_unit(b));
    let k = 1.0 - r.max(g).max(b);
    if k >= 1.0 {
        return [0, 0, 0, 255];
    }
    let d = 1.0 - k;
    let ink = |channel: f32| to_byte(((1.0 - channel) - k) / d);
    [ink(r), ink(g), ink(b), to_byte(k)]
}

/// An sRGB pixel as CIE L*a*b* bytes under D65 — `L` scaled `0..=100 →
/// 0..=255`, `a` and `b` rounded and offset by `128` — through the
/// standard sRGB linearisation, the D65 XYZ matrix, and the Lab cube-root
/// function with its linear toe.
pub fn lab_of([r, g, b]: [u8; 3]) -> [u8; 3] {
    let linear = |v: u8| {
        let c = to_unit(v);
        if c <= 0.04045 {
            c / 12.92
        } else {
            ((c + 0.055) / 1.055).powf(2.4)
        }
    };
    let (r, g, b) = (linear(r), linear(g), linear(b));
    let x = 0.4124 * r + 0.3576 * g + 0.1805 * b;
    let y = 0.2126 * r + 0.7152 * g + 0.0722 * b;
    let z = 0.0193 * r + 0.1192 * g + 0.9505 * b;
    let f = |t: f32| {
        if t > 0.008856 {
            t.cbrt()
        } else {
            7.787 * t + 16.0 / 116.0
        }
    };
    let (fx, fy, fz) = (f(x / 0.95047), f(y), f(z / 1.08883));
    let l = 116.0 * fy - 16.0;
    let a = 500.0 * (fx - fy);
    let bb = 200.0 * (fy - fz);
    let offset = |v: f32| (v.round().clamp(-128.0, 127.0) + 128.0) as u8;
    [
        (l * 2.55).round().clamp(0.0, 255.0) as u8,
        offset(a),
        offset(bb),
    ]
}

/// One of Image > Mode > Duotone's inks: its colour and its curve, the
/// Curves-style points (input darkness `0..=255` → coverage `0..=255`)
/// through which a pixel's darkness becomes this ink's coverage; an
/// empty curve is the straight line, full ink at black and none at white.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct Ink {
    pub color: [u8; 3],
    pub curve: Vec<(u8, u8)>,
}

/// Image > Mode > Indexed Color's Palette: Exact keeps the image's own
/// colours when there are at most 256; Uniform is the 6×6×6 web cube;
/// Adaptive keeps the `colors` most frequent colours (2..=256) and snaps
/// everything else to the nearest of them.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(tag = "kind", rename_all = "camelCase")]
pub enum Palette {
    Exact,
    Uniform,
    Adaptive { colors: u16 },
}

/// Image > Mode > Bitmap's Method: 50% Threshold, Pattern Dither (a 4×4
/// Bayer matrix), or Diffusion Dither (Floyd–Steinberg).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, Default)]
#[serde(rename_all = "camelCase")]
pub enum BitmapMethod {
    #[default]
    Threshold,
    PatternDither,
    DiffusionDither,
}

/// The 4×4 Bayer ordered-dither matrix.
const BAYER: [[u8; 4]; 4] = [[0, 8, 2, 10], [12, 4, 14, 6], [3, 11, 1, 9], [15, 7, 13, 5]];

/// What the canvas shows — Photoshop's Channels panel selection: the
/// composite, one colour channel of it as a grey, or an alpha channel.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(tag = "kind", rename_all = "camelCase")]
pub enum ChannelView {
    Composite,
    Red,
    Green,
    Blue,
    /// CMYK mode's ink channels, shown light where there is little ink.
    Cyan,
    Magenta,
    Yellow,
    Black,
    /// Lab mode's channels.
    Lightness,
    AStar,
    BStar,
    Alpha {
        name: String,
    },
    /// A spot colour channel, shown as its ink density: black where the
    /// ink is full.
    Spot {
        name: String,
    },
}

/// A spot colour channel — Photoshop's Channels panel > New Spot
/// Channel: one ink, its screen colour, its Solidity, and an ink
/// density per document pixel (`255` full ink), overprinted on the
/// composite view in panel order — see [`Document::spot_preview`].
#[derive(Debug, Clone, PartialEq)]
pub struct SpotChannel {
    pub name: String,
    pub color: [u8; 3],
    /// Percent: `100` shows the ink opaque, `0` as a pure overprint
    /// (multiply), between as their mix.
    pub solidity: f32,
    pub pixels: Vec<u8>,
}

/// What the Channels panel shows of a spot channel — see
/// [`DocumentView::spots`].
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct SpotChannelView {
    pub name: String,
    pub color: [u8; 3],
    pub solidity: f32,
}

/// Color Libraries: twelve conventional ink names with approximate sRGB
/// screen colours, for the Spot Channel dialog's library list. No vendor
/// swatch books ship; these are the project's own approximations.
pub fn spot_library() -> Vec<(String, [u8; 3])> {
    [
        ("Process Cyan", [0, 174, 239]),
        ("Process Magenta", [236, 0, 140]),
        ("Process Yellow", [255, 241, 0]),
        ("Process Black", [35, 31, 32]),
        ("Warm Red", [249, 66, 58]),
        ("Rubine Red", [206, 0, 88]),
        ("Rhodamine Red", [225, 0, 152]),
        ("Bright Orange", [254, 80, 0]),
        ("Reflex Blue", [0, 20, 137]),
        ("Emerald Green", [0, 171, 132]),
        ("Violet", [187, 41, 187]),
        ("Gold Yellow", [255, 215, 0]),
    ]
    .into_iter()
    .map(|(name, color)| (name.to_string(), color))
    .collect()
}

/// Overprints one spot channel on `pixels` (document-sized RGBA8) — the
/// arithmetic behind [`Document::spot_preview`] and
/// [`Document::merge_spot_channel`]. Per pixel with ink density `d` and
/// solidity `s` (both `0..=1`): a transparent pixel is white paper; each
/// colour channel becomes the mix `multiply + (opaque − multiply) · s` of
/// the overprint `base · (1 − d · (1 − ink))` and the opaque ink `base +
/// (ink − base) · d`; alpha rises to at least the ink density.
fn apply_spot(spot: &SpotChannel, pixels: &mut [u8]) {
    let ink = spot.color.map(to_unit);
    let solidity = spot.solidity / 100.0;
    for (px, &density) in pixels.chunks_exact_mut(CHANNELS).zip(&spot.pixels) {
        if density == 0 {
            continue;
        }
        let d = to_unit(density);
        let transparent = px[3] == 0;
        for (channel, &ink) in ink.iter().enumerate() {
            let base = if transparent {
                1.0
            } else {
                to_unit(px[channel])
            };
            let multiply = base * (1.0 - d * (1.0 - ink));
            let opaque = base + (ink - base) * d;
            px[channel] = to_byte(multiply + (opaque - multiply) * solidity);
        }
        px[3] = px[3].max(density);
    }
}

/// An alpha channel: one byte per document pixel, row-major, as
/// Photoshop's Channels panel stores a saved grey — here made by
/// Calculations and loadable as a selection.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct AlphaChannel {
    pub name: String,
    pub pixels: Vec<u8>,
}

/// Apply Image's Blending list: any of the twelve layer blend modes, or
/// the two channel-arithmetic modes only Apply Image and Calculations
/// offer. Add and Subtract work in Photoshop's byte terms — `(target +
/// source) / scale + offset` and `(target − source) / scale + offset`,
/// clamped to `0..=255` — with `scale` in `1.0..=2.0` and `offset` in
/// `-255..=255`.
#[derive(Debug, Clone, Copy, PartialEq, Serialize, Deserialize)]
#[serde(tag = "kind", rename_all = "camelCase")]
pub enum ApplyBlend {
    Mode { mode: BlendMode },
    Add { scale: f32, offset: i32 },
    Subtract { scale: f32, offset: i32 },
}

impl ApplyBlend {
    /// Photoshop's dialog bounds for the arithmetic modes.
    pub fn validate(self) -> Result<(), String> {
        match self {
            ApplyBlend::Mode { .. } => Ok(()),
            ApplyBlend::Add { scale, offset } | ApplyBlend::Subtract { scale, offset } => {
                if !(1.0..=2.0).contains(&scale) {
                    return Err(format!("Scale must be between 1 and 2, not {scale}."));
                }
                if !(-255..=255).contains(&offset) {
                    return Err(format!(
                        "Offset must be between -255 and 255, not {offset}."
                    ));
                }
                Ok(())
            }
        }
    }

    /// The blended colour of one channel, backdrop `cb` (the target) and
    /// source `cs` both in `0..=1`: the layer blend mode's own formula, or
    /// the arithmetic in unit terms — `offset / 255` added after the
    /// scaled sum or difference, then clamped.
    pub fn blend(self, cb: f32, cs: f32) -> f32 {
        match self {
            ApplyBlend::Mode { mode } => mode.blend(cb, cs),
            ApplyBlend::Add { scale, offset } => {
                ((cb + cs) / scale + offset as f32 / 255.0).clamp(0.0, 1.0)
            }
            ApplyBlend::Subtract { scale, offset } => {
                ((cb - cs) / scale + offset as f32 / 255.0).clamp(0.0, 1.0)
            }
        }
    }
}

/// What a fill layer paints — Layer > New Fill Layer's three kinds, kept
/// on the layer so the fill can be re-tuned after the fact instead of
/// only baked once as [`Document::add_solid_color_layer`],
/// [`Document::add_gradient_layer`], and [`Document::add_pattern_layer`]
/// do.
#[derive(Debug, Clone, Copy, PartialEq, Serialize, Deserialize)]
#[serde(tag = "kind", rename_all = "camelCase")]
pub enum Fill {
    /// Every pixel `color`, alpha included.
    SolidColor { color: [u8; 4] },
    /// A linear gradient from `start_color` at the top-left corner to
    /// `end_color` at the bottom-right corner.
    Gradient {
        start_color: [u8; 4],
        end_color: [u8; 4],
    },
    /// The pattern Edit > Define Pattern captured, tiled from the top-left
    /// corner.
    Pattern,
}

/// One pixel's RGB through `adjustment` — byte for byte the formula the
/// destructive command of the same name applies, which now calls this
/// too: Invert is `255 − v`; Brightness/Contrast the legacy `factor ×
/// (v − 128) + 128 + brightness`, clamped; Threshold pure white where the
/// BT.601 luma rounds to at least `level`, else black; Posterize each
/// channel snapped to the nearest of `levels` steps across `0..=255`.
pub fn apply_adjustment(adjustment: Adjustment, [r, g, b]: [u8; 3]) -> [u8; 3] {
    match adjustment {
        Adjustment::Invert => [255 - r, 255 - g, 255 - b],
        Adjustment::BrightnessContrast {
            brightness,
            contrast,
        } => {
            let brightness = brightness.clamp(-255, 255) as f32;
            let contrast = contrast.clamp(-255, 255) as f32;
            let factor = 259.0 * (contrast + 255.0) / (255.0 * (259.0 - contrast));
            let apply = |v: u8| -> u8 {
                (factor * (v as f32 - 128.0) + 128.0 + brightness).clamp(0.0, 255.0) as u8
            };
            [apply(r), apply(g), apply(b)]
        }
        Adjustment::Threshold { level } => {
            let luma = 0.299 * r as f32 + 0.587 * g as f32 + 0.114 * b as f32;
            let value = if luma.round() >= level as f32 { 255 } else { 0 };
            [value, value, value]
        }
        Adjustment::Posterize { levels } => {
            let step = 255.0 / (levels as f32 - 1.0);
            let quantize = |v: u8| -> u8 { ((v as f32 / step).round() * step).round() as u8 };
            [quantize(r), quantize(g), quantize(b)]
        }
    }
}

