        let mut doc = Document::new(3, 3).unwrap();
        let id = doc
            .add_layer("base", &solid(3, 3, [4, 5, 6, 255]), 3, 3)
            .unwrap();
        doc.select_rectangle(1.0, 1.0, 3.0, 3.0).unwrap();

