    fn neon_glow_cliff_fixture() -> (Document, LayerId) {
        // Same shape as colored_pencil_cliff_fixture: 4x4, vertically
        // uniform, columns 0-1 solid (200,200,200,255), columns 2-3 solid
        // (50,50,50,255). Sobel magnitude comes out to [0, 255, 255, 0]
        // across every row: 255 (clamped) at the two boundary columns, 0
        // at the two outer columns whose clamped neighbourhoods are
        // entirely flat.
        let mut pixels = Vec::with_capacity(4 * 4 * 4);
        for _y in 0..4u32 {
            for x in 0..4u32 {
                if x < 2 {
                    pixels.extend_from_slice(&[200, 200, 200, 255]);
                } else {
                    pixels.extend_from_slice(&[50, 50, 50, 255]);
                }
            }
        }
        let mut doc = Document::new(4, 4).unwrap();
        let id = doc.add_layer("cliff", &pixels, 4, 4).unwrap();
        (doc, id)
    }

    #[test]
    fn neon_glow_pulls_edges_toward_the_glow_colour() {
        // Size 0 (no dilation), brightness 50 (strength factor 1.0),
        // green glow: at the two 255-magnitude boundary columns strength
        // is exactly 1.0, so both fully become the glow colour regardless
        // of their own original shade; the two flat columns (magnitude 0,
        // strength 0) are left exactly as they were.
        let idx = |x: usize, y: usize| (y * 4 + x) * 4;
        let (mut doc, id) = neon_glow_cliff_fixture();
        doc.neon_glow(id, 0, 50, [0, 255, 0]).unwrap();
        let p = &doc.layers()[0].pixels;
        assert_eq!(&p[idx(0, 0)..idx(0, 0) + 4], [200, 200, 200, 255]);
        assert_eq!(&p[idx(1, 0)..idx(1, 0) + 4], [0, 255, 0, 255]);
        assert_eq!(&p[idx(2, 0)..idx(2, 0) + 4], [0, 255, 0, 255]);
        assert_eq!(&p[idx(3, 0)..idx(3, 0) + 4], [50, 50, 50, 255]);
    }

    #[test]
    fn neon_glow_brightness_scales_a_partial_blend() {
        // Size 0, brightness 20 (strength factor 0.4) at the same
        // full-magnitude boundary columns: every channel arithmetic here
        // lands on an exact integer with no rounding at all. Column 1
        // (original 200): green is 200 + (255-200)*0.4 = 200+22 = 222;
        // red/blue are 200 + (0-200)*0.4 = 200-80 = 120. Column 2
        // (original 50): green is 50 + (255-50)*0.4 = 50+82 = 132;
        // red/blue are 50 + (0-50)*0.4 = 50-20 = 30.
        let idx = |x: usize, y: usize| (y * 4 + x) * 4;
        let (mut doc, id) = neon_glow_cliff_fixture();
        doc.neon_glow(id, 0, 20, [0, 255, 0]).unwrap();
        let p = &doc.layers()[0].pixels;
        assert_eq!(&p[idx(1, 0)..idx(1, 0) + 4], [120, 222, 120, 255]);
        assert_eq!(&p[idx(2, 0)..idx(2, 0) + 4], [30, 132, 30, 255]);
    }

    #[test]
    fn neon_glow_size_dilates_the_edge_map() {
        // Size 1 (radius 1) spreads both 255-magnitude boundary columns
        // across every column of this 4-wide fixture, the same reasoning
        // as colored_pencil_width_dilates_the_edge_map, so at full
        // brightness every pixel becomes the glow colour regardless of
        // its own original shade.
        let idx = |x: usize, y: usize| (y * 4 + x) * 4;
        let (mut doc, id) = neon_glow_cliff_fixture();
        doc.neon_glow(id, 1, 50, [0, 255, 0]).unwrap();
        let p = &doc.layers()[0].pixels;
        for x in 0..4 {
            assert_eq!(&p[idx(x, 0)..idx(x, 0) + 4], [0, 255, 0, 255]);
        }
    }

    #[test]
    fn neon_glow_is_confined_to_the_selection() {
        let idx = |x: usize, y: usize| (y * 4 + x) * 4;
        let (mut doc, id) = neon_glow_cliff_fixture();
        let before = doc.layers()[0].pixels.clone();
        doc.select_rectangle(1.0, 0.0, 2.0, 1.0).unwrap();
        let dirty = doc.neon_glow(id, 0, 50, [0, 255, 0]).unwrap();
        let after = &doc.layers()[0].pixels;
        assert_eq!(&after[idx(1, 0)..idx(1, 0) + 4], [0, 255, 0, 255]);
        assert_eq!(after[..idx(1, 0)], before[..idx(1, 0)]); // unselected, untouched
        assert_eq!(after[idx(1, 0) + 4..], before[idx(1, 0) + 4..]); // unselected, untouched
        assert_eq!(
            dirty,
            Some(Rect {
                x0: 1,
                y0: 0,
                x1: 2,
                y1: 1
            })
        );
    }

    #[test]
    fn neon_glow_propagates_errors() {
        let (mut doc, id) = doc_with_one_layer();
        assert!(doc.neon_glow(id, 25, 50, [0, 255, 0]).is_err());
        assert!(doc.neon_glow(id, 0, 51, [0, 255, 0]).is_err());
        doc.set_locked(id, true).unwrap();
        assert!(doc.neon_glow(id, 0, 50, [0, 255, 0]).is_err());
        assert_eq!(doc.layers()[0].pixels, solid(2, 2, [10, 20, 30, 255]));
        let mut empty = Document::new(2, 2).unwrap();
        assert!(empty.neon_glow(999, 0, 50, [0, 255, 0]).is_err());
    }

    #[test]
    fn poster_edges_posterizes_then_darkens_by_edge_strength() {
        // Same bright/dark split 4x4 fixture as colored_pencil/neon_glow's
        // own tests: columns 0-1 solid (200,200,200,255), columns 2-3
        // solid (50,50,50,255). At 6 posterization levels (step 51), 200
        // quantizes to 204 and 50 quantizes to 51 — cross-checked with an
        // independent Python script, along with everything below. The
        // posterized values' own Sobel magnitude map is [0, 255, 255, 0]
        // across every row, same shape as before just on the new
        // quantized colours. At thickness 0, intensity 10 (darken factor
        // 1.0): the flat columns (edge strength 0) are untouched by
        // posterize's own output (204, 51), while the two full-magnitude
        // edge columns go fully black. At intensity 6 (darken factor
        // 0.6): the same edge columns instead dim to 204*0.4=81.6 -> 82
        // and 51*0.4=20.4 -> 20, both comfortably clear of a .5 boundary.
        let idx = |x: usize, y: usize| (y * 4 + x) * 4;
        let mut pixels = Vec::with_capacity(4 * 4 * 4);
        for _y in 0..4u32 {
            for x in 0..4u32 {
                if x < 2 {
                    pixels.extend_from_slice(&[200, 200, 200, 255]);
                } else {
                    pixels.extend_from_slice(&[50, 50, 50, 255]);
                }
            }
        }
        let mut doc = Document::new(4, 4).unwrap();
        let id = doc.add_layer("cliff", &pixels, 4, 4).unwrap();
        doc.poster_edges(id, 0, 10, 6).unwrap();
        let p = &doc.layers()[0].pixels;
        assert_eq!(&p[idx(0, 0)..idx(0, 0) + 4], [204, 204, 204, 255]);
        assert_eq!(&p[idx(1, 0)..idx(1, 0) + 4], [0, 0, 0, 255]);
        assert_eq!(&p[idx(2, 0)..idx(2, 0) + 4], [0, 0, 0, 255]);
        assert_eq!(&p[idx(3, 0)..idx(3, 0) + 4], [51, 51, 51, 255]);

        let mut doc2 = Document::new(4, 4).unwrap();
        let id2 = doc2.add_layer("cliff", &pixels, 4, 4).unwrap();
        doc2.poster_edges(id2, 0, 6, 6).unwrap();
        let p2 = &doc2.layers()[0].pixels;
        assert_eq!(&p2[idx(1, 0)..idx(1, 0) + 4], [82, 82, 82, 255]);
        assert_eq!(&p2[idx(2, 0)..idx(2, 0) + 4], [20, 20, 20, 255]);
    }

    #[test]
    fn poster_edges_thickness_dilates_the_outline() {
        // Thickness 1 (radius 1) spreads both 255-magnitude boundary
        // columns across every column of this 4-wide fixture, so at
        // intensity 10 (full darken) every pixel goes black regardless of
        // its own posterized shade.
        let idx = |x: usize, y: usize| (y * 4 + x) * 4;
        let mut pixels = Vec::with_capacity(4 * 4 * 4);
        for _y in 0..4u32 {
            for x in 0..4u32 {
                if x < 2 {
                    pixels.extend_from_slice(&[200, 200, 200, 255]);
                } else {
                    pixels.extend_from_slice(&[50, 50, 50, 255]);
                }
            }
        }
        let mut doc = Document::new(4, 4).unwrap();
        let id = doc.add_layer("cliff", &pixels, 4, 4).unwrap();
        doc.poster_edges(id, 1, 10, 6).unwrap();
        let p = &doc.layers()[0].pixels;
        for x in 0..4 {
            assert_eq!(&p[idx(x, 0)..idx(x, 0) + 4], [0, 0, 0, 255]);
        }
    }

    #[test]
    fn poster_edges_is_confined_to_the_selection() {
        let idx = |x: usize, y: usize| (y * 4 + x) * 4;
        let mut pixels = Vec::with_capacity(4 * 4 * 4);
        for _y in 0..4u32 {
            for x in 0..4u32 {
                if x < 2 {
                    pixels.extend_from_slice(&[200, 200, 200, 255]);
                } else {
                    pixels.extend_from_slice(&[50, 50, 50, 255]);
                }
            }
        }
        let mut doc = Document::new(4, 4).unwrap();
        let id = doc.add_layer("cliff", &pixels, 4, 4).unwrap();
        // The whole of column 1 (all four rows), so the fixture stays
        // vertically uniform and the by-hand Sobel reasoning above still
        // applies unchanged.
        doc.select_rectangle(1.0, 0.0, 2.0, 4.0).unwrap();
        let dirty = doc.poster_edges(id, 0, 10, 6).unwrap();
        let after = &doc.layers()[0].pixels;
        // Both posterize and the darkening pass independently respect the
        // selection, so column 1 (selected) is posterized to 204 and then
        // fully darkened by its own full-magnitude edge (204 * 0 = 0),
        // while columns 0, 2, and 3 (unselected) are left at their raw,
        // unposterized original values — 200 for column 0, 50 for columns
        // 2 and 3.
        assert_eq!(&after[idx(1, 0)..idx(1, 0) + 4], [0, 0, 0, 255]);
        assert_eq!(&after[idx(0, 0)..idx(0, 0) + 4], [200, 200, 200, 255]);
        assert_eq!(&after[idx(2, 0)..idx(2, 0) + 4], [50, 50, 50, 255]);
        assert_eq!(
            dirty,
            Some(Rect {
                x0: 1,
                y0: 0,
                x1: 2,
                y1: 4
            })
        );
    }

