    fn crosshatch_spike_fixture() -> (Document, LayerId) {
        // 3x3, flat grey (50,50,50,255) everywhere except the
        // bottom-right corner (2,2), a bright spike (200,200,200,255).
        // Chosen specifically so the two crossing diagonals through the
        // centre (1,1) disagree: the "\" diagonal (0,0)-(1,1)-(2,2) runs
        // straight through the spike, while the "/" diagonal
        // (0,2)-(1,1)-(2,0) avoids it entirely, letting min-of-two
        // meaningfully pick the diagonal that misses the spike.
        let mut pixels = Vec::with_capacity(3 * 3 * 4);
        for y in 0..3u32 {
            for x in 0..3u32 {
                if x == 2 && y == 2 {
                    pixels.extend_from_slice(&[200, 200, 200, 255]);
                } else {
                    pixels.extend_from_slice(&[50, 50, 50, 255]);
                }
            }
        }
        let mut doc = Document::new(3, 3).unwrap();
        let id = doc.add_layer("spike", &pixels, 3, 3).unwrap();
        (doc, id)
    }

    #[test]
    fn crosshatch_takes_the_darker_of_two_crossing_diagonals() {
        // Stroke length 3 gives half-length 1. At the centre (1,1): the
        // "\" diagonal averages (0,0)=50, (1,1)=50, (2,2)=200 -> 300/3 =
        // 100; the "/" diagonal averages (0,2)=50, (1,1)=50, (2,0)=50 ->
        // 150/3 = 50 exactly. min(100, 50) = 50, so the centre is
        // unaffected by the spike. At the spike itself (2,2): "\" gives
        // (1,1)=50, (2,2)=200, (2,2) again (clamped) = 200 -> 450/3 =
        // 150; "/" gives (1,2)=50 (clamped from (1,3)), (2,2)=200,
        // (2,1)=50 (clamped from (3,1)) -> 300/3 = 100. min(150, 100) =
        // 100. Sharpness 0 means pure hatching, no original blended
        // back in. Cross-checked with an independent Python script.
        let idx = |x: usize, y: usize| (y * 3 + x) * 4;
        let (mut doc, id) = crosshatch_spike_fixture();
        doc.crosshatch(id, 3, 0, 1).unwrap();
        let p = &doc.layers()[0].pixels;
        assert_eq!(&p[idx(1, 1)..idx(1, 1) + 4], [50, 50, 50, 255]);
        assert_eq!(&p[idx(2, 2)..idx(2, 2) + 4], [100, 100, 100, 255]);
    }

    #[test]
    fn crosshatch_strength_repeats_the_pass() {
        // A second pass runs the same crossing-diagonal min over the
        // first pass's own output (spike corner now 100, centre still
        // 50 everywhere else unaffected): at (2,2), "\" now averages
        // (1,1)=50, (2,2)=100, (2,2) clamped=100 -> 250/3 = 83; "/"
        // averages (1,2)=50, (2,2)=100, (2,1)=50 -> 200/3 = 66.
        // min(83, 66) = 66, darkening further with each pass.
        let idx = |x: usize, y: usize| (y * 3 + x) * 4;
        let (mut doc, id) = crosshatch_spike_fixture();
        doc.crosshatch(id, 3, 0, 2).unwrap();
        let p = &doc.layers()[0].pixels;
        assert_eq!(&p[idx(2, 2)..idx(2, 2) + 4], [66, 66, 66, 255]);
    }

    #[test]
    fn crosshatch_sharpness_blends_the_original_back_in() {
        // Same single-pass hatching as the first test (spike corner
        // hatches to 100), but sharpness 10 (blend factor 0.5) mixes it
        // back with the original 200 exactly halfway: 200*0.5 + 100*0.5
        // = 150.0 exactly, no rounding needed.
        let idx = |x: usize, y: usize| (y * 3 + x) * 4;
        let (mut doc, id) = crosshatch_spike_fixture();
        doc.crosshatch(id, 3, 10, 1).unwrap();
        let p = &doc.layers()[0].pixels;
        assert_eq!(&p[idx(2, 2)..idx(2, 2) + 4], [150, 150, 150, 255]);
    }

    #[test]
    fn crosshatch_is_confined_to_the_selection() {
        let idx = |x: usize, y: usize| (y * 3 + x) * 4;
        let (mut doc, id) = crosshatch_spike_fixture();
        let before = doc.layers()[0].pixels.clone();
        doc.select_rectangle(2.0, 2.0, 3.0, 3.0).unwrap();
        let dirty = doc.crosshatch(id, 3, 0, 1).unwrap();
        let after = &doc.layers()[0].pixels;
        assert_eq!(&after[idx(2, 2)..idx(2, 2) + 4], [100, 100, 100, 255]);
        assert_eq!(after[..idx(2, 2)], before[..idx(2, 2)]); // unselected, untouched
        assert_eq!(
            dirty,
            Some(Rect {
                x0: 2,
                y0: 2,
                x1: 3,
                y1: 3
            })
        );
    }

    #[test]
    fn crosshatch_propagates_errors() {
        let (mut doc, id) = doc_with_one_layer();
        assert!(doc.crosshatch(id, 2, 0, 1).is_err());
        assert!(doc.crosshatch(id, 51, 0, 1).is_err());
        assert!(doc.crosshatch(id, 3, 21, 1).is_err());
        assert!(doc.crosshatch(id, 3, 0, 0).is_err());
        assert!(doc.crosshatch(id, 3, 0, 4).is_err());
        doc.set_locked(id, true).unwrap();
        assert!(doc.crosshatch(id, 3, 0, 1).is_err());
        assert_eq!(doc.layers()[0].pixels, solid(2, 2, [10, 20, 30, 255]));
        let mut empty = Document::new(2, 2).unwrap();
        assert!(empty.crosshatch(999, 3, 0, 1).is_err());
    }

    #[test]
    fn accented_edges_blends_toward_black_or_white_by_brightness() {
        // Same cliff fixture ink_outlines/poster_edges/neon_glow/
        // colored_pencil all already share: 4x4, columns 0-1 solid
        // (200,200,200,255), columns 2-3 solid (50,50,50,255), Sobel
        // magnitude [0, 255, 255, 0] across every row. Edge width 1 maps
        // to dilation radius 0 (measured exactly), smoothness 0 means no
        // blur, so the edge fraction is exactly 0 or 1 per column.
        //
        // At brightness 0 (edge colour black, 0): columns 0 and 3 have
        // edge 0 and are untouched (200, 50); columns 1 and 2 have edge 1
        // and go fully to the edge colour, 0 regardless of their own
        // shade. At brightness 50 (edge colour white, 255): columns 0/3
        // stay untouched and columns 1/2 go fully to 255. At brightness
        // 25 (edge colour 127.5): columns 1/2 blend fully to 127.5,
        // which both Rust's round-half-away-from-zero and Python's
        // round-half-to-even agree rounds to 128 (128 is the nearer even
        // integer to 127.5 either way). Cross-checked with an independent
        // Python script emulating f32 arithmetic via struct pack/unpack.
        let idx = |x: usize, y: usize| (y * 4 + x) * 4;

        let (mut doc, id) = ink_outlines_cliff_fixture();
        doc.accented_edges(id, 1, 0, 0).unwrap();
        let p = &doc.layers()[0].pixels;
        assert_eq!(&p[idx(0, 0)..idx(0, 0) + 4], [200, 200, 200, 255]);
        assert_eq!(&p[idx(1, 0)..idx(1, 0) + 4], [0, 0, 0, 255]);
        assert_eq!(&p[idx(2, 0)..idx(2, 0) + 4], [0, 0, 0, 255]);
        assert_eq!(&p[idx(3, 0)..idx(3, 0) + 4], [50, 50, 50, 255]);

        let (mut doc, id) = ink_outlines_cliff_fixture();
        doc.accented_edges(id, 1, 50, 0).unwrap();
        let p = &doc.layers()[0].pixels;
        assert_eq!(&p[idx(0, 0)..idx(0, 0) + 4], [200, 200, 200, 255]);
        assert_eq!(&p[idx(1, 0)..idx(1, 0) + 4], [255, 255, 255, 255]);
        assert_eq!(&p[idx(2, 0)..idx(2, 0) + 4], [255, 255, 255, 255]);
        assert_eq!(&p[idx(3, 0)..idx(3, 0) + 4], [50, 50, 50, 255]);

        let (mut doc, id) = ink_outlines_cliff_fixture();
        doc.accented_edges(id, 1, 25, 0).unwrap();
        let p = &doc.layers()[0].pixels;
        assert_eq!(&p[idx(1, 0)..idx(1, 0) + 4], [128, 128, 128, 255]);
        assert_eq!(&p[idx(2, 0)..idx(2, 0) + 4], [128, 128, 128, 255]);
    }

    #[test]
    fn accented_edges_width_dilates_the_edge_map() {
        // Edge width 2 maps to dilation radius 1, spreading the
        // 255-magnitude boundary across every column of this 4-wide
        // fixture (the same reasoning as ink_outlines's own
        // stroke-length dilation test), so at brightness 0 every pixel
        // goes fully black regardless of its own shade.
        let idx = |x: usize, y: usize| (y * 4 + x) * 4;
        let (mut doc, id) = ink_outlines_cliff_fixture();
        doc.accented_edges(id, 2, 0, 0).unwrap();
        let p = &doc.layers()[0].pixels;
        for x in 0..4 {
            assert_eq!(&p[idx(x, 0)..idx(x, 0) + 4], [0, 0, 0, 255]);
        }
    }

    #[test]
    fn accented_edges_smoothness_blurs_the_edge_map() {
        // Edge width 1 (no dilation), smoothness 1 (box-blur radius 1)
        // over the measured edge row [0, 255, 255, 0]: since the fixture
        // is vertically uniform, the 3x3 blur window's three rows are
        // identical, so it reduces to a horizontal average of columns
        // (col-1, col, col+1), each counted 3 times out of 9 samples,
        // with clamp-to-edge at the boundary. Column 0: (0, 0, 255) *3 =
        // 765/9 = 85 exactly. Column 1: (0, 255, 255) *3 = 1530/9 = 170.
        // Column 2: (255, 255, 0) *3 = 1530/9 = 170. Column 3: (255, 0,
        // 0) *3 = 765/9 = 85. All four divide evenly, so `box_blur_at`'s
        // integer truncating division introduces no ambiguity. At
        // brightness 0 (edge colour 0), each pixel blends toward black
        // by its own smoothed fraction: column 0, edge 85/255 = 1/3,
        // 200 * (2/3) = 133.33 -> 133; column 1, edge 170/255 = 2/3, 200
        // * (1/3) = 66.67 -> 67; column 2, edge 2/3, 50 * (1/3) = 16.67
        // -> 17; column 3, edge 1/3, 50 * (2/3) = 33.33 -> 33. Cross-
        // checked with an independent Python script emulating f32
        // arithmetic exactly.
        let idx = |x: usize, y: usize| (y * 4 + x) * 4;
        let (mut doc, id) = ink_outlines_cliff_fixture();
        doc.accented_edges(id, 1, 0, 1).unwrap();
        let p = &doc.layers()[0].pixels;
        assert_eq!(&p[idx(0, 0)..idx(0, 0) + 4], [133, 133, 133, 255]);
        assert_eq!(&p[idx(1, 0)..idx(1, 0) + 4], [67, 67, 67, 255]);
        assert_eq!(&p[idx(2, 0)..idx(2, 0) + 4], [17, 17, 17, 255]);
        assert_eq!(&p[idx(3, 0)..idx(3, 0) + 4], [33, 33, 33, 255]);
    }

    #[test]
    fn accented_edges_is_confined_to_the_selection() {
        let idx = |x: usize, y: usize| (y * 4 + x) * 4;
        let (mut doc, id) = ink_outlines_cliff_fixture();
        let before = doc.layers()[0].pixels.clone();
        doc.select_rectangle(1.0, 0.0, 2.0, 1.0).unwrap();
        let dirty = doc.accented_edges(id, 1, 0, 0).unwrap();
        let after = &doc.layers()[0].pixels;
        assert_eq!(&after[idx(1, 0)..idx(1, 0) + 4], [0, 0, 0, 255]);
        assert_eq!(after[..idx(1, 0)], before[..idx(1, 0)]); // unselected, untouched
        assert_eq!(after[idx(1, 0) + 4..], before[idx(1, 0) + 4..]); // unselected, untouched
        assert_eq!(
            dirty,
            Some(Rect {
                x0: 1,
                y0: 0,
                x1: 2,
                y1: 1
            })
        );
    }

    #[test]
    fn accented_edges_propagates_errors() {
        let (mut doc, id) = doc_with_one_layer();
        assert!(doc.accented_edges(id, 0, 0, 0).is_err());
        assert!(doc.accented_edges(id, 15, 0, 0).is_err());
        assert!(doc.accented_edges(id, 1, 51, 0).is_err());
        assert!(doc.accented_edges(id, 1, 0, 16).is_err());
        doc.set_locked(id, true).unwrap();
        assert!(doc.accented_edges(id, 1, 0, 0).is_err());
        assert_eq!(doc.layers()[0].pixels, solid(2, 2, [10, 20, 30, 255]));
        let mut empty = Document::new(2, 2).unwrap();
        assert!(empty.accented_edges(999, 1, 0, 0).is_err());
    }

    #[test]
    fn angled_strokes_paints_light_and_dark_pixels_with_different_diagonals() {
        // Reuses crosshatch's own spike fixture (3x3, flat 50 except a
        // bright 200 at the bottom-right corner) and its own
        // already-verified diagonal averages at stroke length 3 (half
        // 1): the centre (1,1) is 100 along "\" and 50 along "/"; the
        // spike corner (2,2) is 150 along "\" and 100 along "/". At
        // direction balance 50 (threshold 127.5) and sharpness 0 (pure
        // stroke, no blend back): the centre's own luma is 50, below the
        // threshold, so it is painted with "/" (50) -- unchanged from its
        // original value. The corner's own luma is 200, at or above the
        // threshold, so it is painted with "\" (150) instead of "/"
        // (100), a real, direction-dependent change worked out by hand.
        let idx = |x: usize, y: usize| (y * 3 + x) * 4;
        let (mut doc, id) = crosshatch_spike_fixture();
        doc.angled_strokes(id, 50, 3, 0).unwrap();
        let p = &doc.layers()[0].pixels;
        assert_eq!(&p[idx(1, 1)..idx(1, 1) + 4], [50, 50, 50, 255]);
        assert_eq!(&p[idx(2, 2)..idx(2, 2) + 4], [150, 150, 150, 255]);
    }

    #[test]
    fn angled_strokes_direction_balance_shifts_the_threshold() {
        // Same fixture and stroke length as above, but direction balance
        // 90 raises the threshold to 229.5 -- above the spike corner's
        // own luma of 200, so it now falls on the "/" side instead of
        // "\", landing on 100 rather than 150.
        let idx = |x: usize, y: usize| (y * 3 + x) * 4;
        let (mut doc, id) = crosshatch_spike_fixture();
        doc.angled_strokes(id, 90, 3, 0).unwrap();
        let p = &doc.layers()[0].pixels;
        assert_eq!(&p[idx(2, 2)..idx(2, 2) + 4], [100, 100, 100, 255]);
    }

    #[test]
    fn angled_strokes_sharpness_blends_the_original_back_in() {
        // Same as the first test (corner picks the "\" stroke, 150), but
        // sharpness 5 (blend factor 0.5) mixes it back with the original
        // 200 exactly halfway: 200 * 0.5 + 150 * 0.5 = 175.0 exactly, no
        // rounding needed.
        let idx = |x: usize, y: usize| (y * 3 + x) * 4;
        let (mut doc, id) = crosshatch_spike_fixture();
        doc.angled_strokes(id, 50, 3, 5).unwrap();
        let p = &doc.layers()[0].pixels;
        assert_eq!(&p[idx(2, 2)..idx(2, 2) + 4], [175, 175, 175, 255]);
    }

    #[test]
    fn angled_strokes_is_confined_to_the_selection() {
        let idx = |x: usize, y: usize| (y * 3 + x) * 4;
        let (mut doc, id) = crosshatch_spike_fixture();
        let before = doc.layers()[0].pixels.clone();
        doc.select_rectangle(2.0, 2.0, 3.0, 3.0).unwrap();
        let dirty = doc.angled_strokes(id, 50, 3, 0).unwrap();
        let after = &doc.layers()[0].pixels;
        assert_eq!(&after[idx(2, 2)..idx(2, 2) + 4], [150, 150, 150, 255]);
        assert_eq!(after[..idx(2, 2)], before[..idx(2, 2)]); // unselected, untouched
        assert_eq!(
            dirty,
            Some(Rect {
                x0: 2,
                y0: 2,
                x1: 3,
                y1: 3
            })
        );
    }

    #[test]
    fn angled_strokes_propagates_errors() {
        let (mut doc, id) = doc_with_one_layer();
        assert!(doc.angled_strokes(id, 101, 3, 0).is_err());
        assert!(doc.angled_strokes(id, 50, 2, 0).is_err());
        assert!(doc.angled_strokes(id, 50, 51, 0).is_err());
        assert!(doc.angled_strokes(id, 50, 3, 11).is_err());
        doc.set_locked(id, true).unwrap();
        assert!(doc.angled_strokes(id, 50, 3, 0).is_err());
        assert_eq!(doc.layers()[0].pixels, solid(2, 2, [10, 20, 30, 255]));
        let mut empty = Document::new(2, 2).unwrap();
        assert!(empty.angled_strokes(999, 50, 3, 0).is_err());
    }

    #[test]
    fn opacity_is_clamped_and_nan_is_rejected() {
        let (mut doc, id) = doc_with_one_layer();

        doc.set_opacity(id, 1.5).unwrap();
        assert_eq!(doc.layers()[0].opacity, 1.0);
        doc.set_opacity(id, -0.5).unwrap();
        assert_eq!(doc.layers()[0].opacity, 0.0);
        assert!(doc.set_opacity(id, f32::NAN).is_err());
    }

    #[test]
    fn a_fully_transparent_layer_does_not_contribute() {
        let (mut doc, id) = doc_with_one_layer();
        doc.set_opacity(id, 0.0).unwrap();
        assert!(!doc.layers()[0].contributes());
    }

    #[test]
    fn operations_on_an_unknown_layer_are_errors() {
        let (mut doc, _) = doc_with_one_layer();
        assert!(doc.set_visible(999, true).is_err());
        assert!(doc.set_opacity(999, 0.5).is_err());
        assert!(doc.set_blend_mode(999, BlendMode::Screen).is_err());
        assert!(doc.remove_layer(999).is_err());
        assert!(doc.move_layer(999, MoveDirection::Up).is_err());
    }

    #[test]
    fn new_layers_go_on_top() {
        let mut doc = Document::new(1, 1).unwrap();
        let bottom = doc.add_layer("bottom", &solid(1, 1, [0; 4]), 1, 1).unwrap();
        let top = doc.add_layer("top", &solid(1, 1, [0; 4]), 1, 1).unwrap();
        let ids: Vec<_> = doc.layers().iter().map(|l| l.id).collect();
        assert_eq!(ids, vec![bottom, top]);
    }

    #[test]
    fn moving_reorders_the_stack() {
        let mut doc = Document::new(1, 1).unwrap();
        let a = doc.add_layer("a", &solid(1, 1, [0; 4]), 1, 1).unwrap();
        let b = doc.add_layer("b", &solid(1, 1, [0; 4]), 1, 1).unwrap();
        let c = doc.add_layer("c", &solid(1, 1, [0; 4]), 1, 1).unwrap();

        doc.move_layer(a, MoveDirection::Up).unwrap();
        assert_eq!(ids(&doc), vec![b, a, c]);

        doc.move_layer(c, MoveDirection::Down).unwrap();
        assert_eq!(ids(&doc), vec![b, c, a]);
    }

    #[test]
    fn moving_past_the_end_of_the_stack_is_a_no_op() {
        let mut doc = Document::new(1, 1).unwrap();
        let a = doc.add_layer("a", &solid(1, 1, [0; 4]), 1, 1).unwrap();
        let b = doc.add_layer("b", &solid(1, 1, [0; 4]), 1, 1).unwrap();

        doc.move_layer(b, MoveDirection::Up).unwrap();
        doc.move_layer(a, MoveDirection::Down).unwrap();
        assert_eq!(ids(&doc), vec![a, b]);
    }

    #[test]
    fn merge_visible_requires_at_least_two_visible_layers() {
        let mut doc = Document::new(1, 1).unwrap();
        let err = doc.merge_visible().unwrap_err();
        assert!(err.contains("at least two"), "{err}");

        doc.add_layer("solo", &solid(1, 1, [0; 4]), 1, 1).unwrap();
        assert!(doc.merge_visible().is_err());

        let hidden = doc.add_layer("hidden", &solid(1, 1, [0; 4]), 1, 1).unwrap();
        doc.set_visible(hidden, false).unwrap();
        // `solo` is still the only visible layer — one visible layer plus
        // any number of hidden ones is still not "at least two visible".
        assert!(doc.merge_visible().is_err());
    }

    #[test]
    fn merge_visible_combines_exactly_the_visible_layers() {
        let mut doc = Document::new(1, 1).unwrap();
        doc.add_layer("red", &solid(1, 1, [255, 0, 0, 255]), 1, 1)
            .unwrap();
        let hidden = doc
            .add_layer("hidden", &solid(1, 1, [0, 255, 0, 255]), 1, 1)
            .unwrap();
        doc.set_visible(hidden, false).unwrap();
        doc.add_layer("green half", &solid(1, 1, [0, 255, 0, 128]), 1, 1)
            .unwrap();

        let merged_id = doc.merge_visible().unwrap();

        // `red` (bottommost of the two visible layers) and `green_half` are
        // gone, replaced by the merged layer at `red`'s old position;
        // `hidden` survived, untouched, still above it.
        assert_eq!(ids(&doc), vec![merged_id, hidden]);
        let merged = &doc.layers()[0];
        assert!(merged.visible);
        assert_eq!(merged.opacity, 1.0);
        assert_eq!(merged.blend_mode, BlendMode::Normal);
        // Half-alpha green over opaque red == the same source-over blend
        // `flatten` would produce for just those two layers.
        assert_eq!(merged.pixels, vec![127, 128, 0, 255]);
        assert!(!doc.layers()[1].visible); // `hidden`, still hidden
    }

    #[test]
    fn merge_visible_lands_at_the_bottommost_merged_layers_position() {
        let mut doc = Document::new(1, 1).unwrap();
        doc.add_layer("bottom", &solid(1, 1, [1; 4]), 1, 1).unwrap();
        let middle_hidden = doc
            .add_layer("middle hidden", &solid(1, 1, [2; 4]), 1, 1)
            .unwrap();
        doc.set_visible(middle_hidden, false).unwrap();
        doc.add_layer("top", &solid(1, 1, [3; 4]), 1, 1).unwrap();

        let merged_id = doc.merge_visible().unwrap();
        // `bottom` and `top` (both visible) merge into one layer at
        // `bottom`'s old position; `middle_hidden` keeps its place above it.
        assert_eq!(ids(&doc), vec![merged_id, middle_hidden]);
    }

    #[test]
    fn merge_down_on_the_bottom_layer_is_an_error() {
        let mut doc = Document::new(1, 1).unwrap();
        let bottom = doc.add_layer("bottom", &solid(1, 1, [0; 4]), 1, 1).unwrap();
        let err = doc.merge_down(bottom).unwrap_err();
        assert!(err.contains("no layer below"), "{err}");
    }

    #[test]
    fn merge_down_combines_a_layer_with_the_one_below_it() {
        let mut doc = Document::new(1, 1).unwrap();
        doc.add_layer("red", &solid(1, 1, [255, 0, 0, 255]), 1, 1)
            .unwrap();
        let green_half = doc
            .add_layer("green half", &solid(1, 1, [0, 255, 0, 128]), 1, 1)
            .unwrap();
        let top = doc.add_layer("top", &solid(1, 1, [9; 4]), 1, 1).unwrap();

        let merged_id = doc.merge_down(green_half).unwrap();

        // `red` and `green half` collapse into one layer, named after `red`
        // (the layer merged into); `top` is untouched, still above it.
        assert_eq!(ids(&doc), vec![merged_id, top]);
        let merged = &doc.layers()[0];
        assert_eq!(merged.name, "red");
        assert!(merged.visible);
        assert_eq!(merged.opacity, 1.0);
        // Same source-over blend as the equivalent `merge_visible` test.
        assert_eq!(merged.pixels, vec![127, 128, 0, 255]);
    }

    #[test]
    fn merge_down_respects_visibility_of_either_layer() {
        let mut doc = Document::new(1, 1).unwrap();
        doc.add_layer("bottom", &solid(1, 1, [10, 20, 30, 255]), 1, 1)
            .unwrap();
        let top = doc
            .add_layer("top", &solid(1, 1, [255, 255, 255, 255]), 1, 1)
            .unwrap();
        doc.set_visible(top, false).unwrap();

        doc.merge_down(top).unwrap();

        // `top` was hidden, so it contributed nothing — the merged result
        // is exactly `bottom`'s own pixels, not a blend with white.
        assert_eq!(doc.layers()[0].pixels, vec![10, 20, 30, 255]);
    }

    #[test]
    fn flattening_an_empty_document_is_an_error() {
        let mut doc = Document::new(1, 1).unwrap();
        let err = doc.flatten_image().unwrap_err();
        assert!(err.contains("Nothing to flatten"), "{err}");
    }

    #[test]
    fn flatten_image_discards_hidden_layers_unlike_merge_visible() {
        let mut doc = Document::new(1, 1).unwrap();
        doc.add_layer("red", &solid(1, 1, [255, 0, 0, 255]), 1, 1)
            .unwrap();
        let hidden = doc
            .add_layer("hidden", &solid(1, 1, [0, 255, 0, 255]), 1, 1)
            .unwrap();
        doc.set_visible(hidden, false).unwrap();

        let id = doc.flatten_image().unwrap();

        assert_eq!(ids(&doc), vec![id]);
        let flattened = &doc.layers()[0];
        assert_eq!(flattened.name, "Background");
        assert!(flattened.visible);
        assert_eq!(flattened.opacity, 1.0);
        assert_eq!(flattened.blend_mode, BlendMode::Normal);
        // Only the visible red layer contributed — matches flatten()'s own
        // "hidden layers don't contribute" rule, and the hidden layer's
        // pixels are gone from the document entirely, not just invisible.
        assert_eq!(flattened.pixels, vec![255, 0, 0, 255]);
    }

    #[test]
    fn flattening_a_single_layer_document_is_a_no_op_visually() {
        let mut doc = Document::new(1, 1).unwrap();
        doc.add_layer("solo", &solid(1, 1, [9, 8, 7, 255]), 1, 1)
            .unwrap();
        doc.flatten_image().unwrap();
        assert_eq!(ids(&doc).len(), 1);
        assert_eq!(doc.layers()[0].pixels, vec![9, 8, 7, 255]);
    }

    #[test]
    fn removing_takes_the_right_layer_out() {
        let mut doc = Document::new(1, 1).unwrap();
        let a = doc.add_layer("a", &solid(1, 1, [0; 4]), 1, 1).unwrap();
        let b = doc.add_layer("b", &solid(1, 1, [0; 4]), 1, 1).unwrap();
        doc.remove_layer(a).unwrap();
        assert_eq!(ids(&doc), vec![b]);
    }

    #[test]
    fn duplicate_layer_lands_directly_above_the_original_not_at_the_top() {
        let mut doc = Document::new(1, 1).unwrap();
        let a = doc.add_layer("a", &solid(1, 1, [0; 4]), 1, 1).unwrap();
        let b = doc.add_layer("b", &solid(1, 1, [0; 4]), 1, 1).unwrap();
        let c = doc.add_layer("c", &solid(1, 1, [0; 4]), 1, 1).unwrap();

        let dup = doc.duplicate_layer(a).unwrap();

        assert_eq!(ids(&doc), vec![a, dup, b, c]);
        assert_ne!(dup, a);
    }

    #[test]
    fn duplicate_layer_copies_pixels_and_attributes_and_appends_copy_to_the_name() {
        let (mut doc, id) = doc_with_one_layer();
        doc.set_opacity(id, 0.5).unwrap();
        doc.set_blend_mode(id, BlendMode::Multiply).unwrap();
        doc.set_locked(id, true).unwrap();

        let dup = doc.duplicate_layer(id).unwrap();

        let duplicate = doc.layers().iter().find(|l| l.id == dup).unwrap();
        assert_eq!(duplicate.name, "base copy");
        assert_eq!(duplicate.pixels, solid(2, 2, [10, 20, 30, 255]));
        assert_eq!(duplicate.opacity, 0.5);
        assert_eq!(duplicate.blend_mode, BlendMode::Multiply);
        assert!(duplicate.locked);
        assert!(duplicate.visible);
    }

    #[test]
    fn duplicate_layer_does_not_modify_the_original() {
        let (mut doc, id) = doc_with_one_layer();
        doc.duplicate_layer(id).unwrap();
        let original = doc.layers().iter().find(|l| l.id == id).unwrap();
        assert_eq!(original.name, "base");
        assert_eq!(original.pixels, solid(2, 2, [10, 20, 30, 255]));
    }

    #[test]
    fn duplicate_layer_errors_on_an_unknown_layer() {
        let mut doc = Document::new(2, 2).unwrap();
        assert!(doc.duplicate_layer(999).is_err());
    }

    fn ids(doc: &Document) -> Vec<LayerId> {
        doc.layers().iter().map(|l| l.id).collect()
    }

    fn pixel(doc: &Document, id: LayerId, x: u32, y: u32) -> [u8; 4] {
        let layer = doc.layers().iter().find(|l| l.id == id).unwrap();
        let base = (y as usize * doc.width() as usize + x as usize) * CHANNELS;
        [
            layer.pixels[base],
            layer.pixels[base + 1],
            layer.pixels[base + 2],
            layer.pixels[base + 3],
        ]
    }

    fn transparent_doc(size: u32) -> (Document, LayerId) {
        transparent_doc_wh(size, size)
    }

    fn transparent_doc_wh(width: u32, height: u32) -> (Document, LayerId) {
        let mut doc = Document::new(width, height).unwrap();
        let id = doc
            .add_layer(
                "layer",
                &vec![0u8; (width * height) as usize * CHANNELS],
                width,
                height,
            )
            .unwrap();
        (doc, id)
    }

    #[test]
    fn a_brush_dot_paints_a_solid_circle_on_a_transparent_layer() {
        let (mut doc, id) = transparent_doc(9);
        let rect = doc
            .stroke(
                id,
                &[(4.0, 4.0)],
                3.0,
                Stroke::Brush {
                    color: [255, 0, 0, 255],
                },
            )
            .unwrap();
        // A dot at (4,4) with radius 3 touches roughly (1,1)-(7,7), clamped
        // to the document — the returned rect is what a caller would
        // recomposite instead of the whole 9x9 canvas.
        assert_eq!(
            rect,
            Some(Rect {
                x0: 1,
                y0: 1,
                x1: 7,
                y1: 7
            })
        );
        // The centre gets full coverage.
        assert_eq!(pixel(&doc, id, 4, 4), [255, 0, 0, 255]);
        // Well outside the radius is untouched.
        assert_eq!(pixel(&doc, id, 0, 0), [0, 0, 0, 0]);
    }

    #[test]
    fn brush_alpha_blends_source_over_the_existing_pixel() {
        let (mut doc, id) = transparent_doc(3);
        doc.stroke(
            id,
            &[(1.0, 1.0)],
            3.0,
            Stroke::Brush {
                color: [0, 0, 0, 255],
            },
        )
        .unwrap();
        assert_eq!(pixel(&doc, id, 1, 1), [0, 0, 0, 255]);

        doc.stroke(
            id,
            &[(1.0, 1.0)],
            3.0,
            Stroke::Brush {
                color: [255, 255, 255, 128],
            },
        )
        .unwrap();
        // 50%-alpha white over opaque black is mid-grey, same as the compositor.
        let out = pixel(&doc, id, 1, 1);
        assert!(out[3] == 255, "alpha was {}", out[3]);
        for channel in out[..3].iter() {
            assert!(
                channel.abs_diff(128) <= 1,
                "channel {channel} was not near mid-grey"
            );
        }
    }

    #[test]
    fn eraser_multiplies_alpha_toward_zero() {
        let mut doc = Document::new(3, 3).unwrap();
        let id = doc
            .add_layer("l", &solid(3, 3, [10, 20, 30, 255]), 3, 3)
            .unwrap();
        doc.stroke(id, &[(1.0, 1.0)], 3.0, Stroke::Eraser).unwrap();
        assert_eq!(pixel(&doc, id, 1, 1)[3], 0);
        // Colour is left alone; only alpha is erased.
        assert_eq!(&pixel(&doc, id, 1, 1)[..3], &[10, 20, 30]);
    }

    #[test]
    fn dodge_lightens_toward_white_by_exposure() {
        // Exposure 50 at full coverage: 100 -> 100/255 + (155/255) / 2 ->
        // 177.5 -> 178; 0 -> 128; 200 -> 227.5 -> 228.
        let mut doc = Document::new(3, 3).unwrap();
        let id = doc
            .add_layer("l", &solid(3, 3, [100, 0, 200, 255]), 3, 3)
            .unwrap();
        doc.stroke(id, &[(1.0, 1.0)], 3.0, Stroke::Dodge { exposure: 50 })
            .unwrap();
        assert_eq!(pixel(&doc, id, 1, 1), [178, 128, 228, 255]);
    }

    #[test]
    fn dodge_at_full_exposure_is_white_and_at_zero_is_an_identity() {
        let mut doc = Document::new(3, 3).unwrap();
        let id = doc
            .add_layer("l", &solid(3, 3, [100, 0, 200, 255]), 3, 3)
            .unwrap();
        doc.stroke(id, &[(1.0, 1.0)], 3.0, Stroke::Dodge { exposure: 0 })
            .unwrap();
        assert_eq!(pixel(&doc, id, 1, 1), [100, 0, 200, 255]);
        doc.stroke(id, &[(1.0, 1.0)], 3.0, Stroke::Dodge { exposure: 100 })
            .unwrap();
        assert_eq!(pixel(&doc, id, 1, 1), [255, 255, 255, 255]);
    }

    #[test]
    fn dodge_scales_with_the_brushs_soft_edge_coverage() {
        // Radius 1 at (1, 1): pixel (0, 0)'s centre is sqrt(0.5) away, so
        // coverage is 1 - 0.7071 + 0.5 = 0.7929 and 100 lifts by 155/255 *
        // 0.5 * 0.7929 -> 161.
        let mut doc = Document::new(3, 3).unwrap();
        let id = doc
            .add_layer("l", &solid(3, 3, [100, 0, 0, 255]), 3, 3)
            .unwrap();
        doc.stroke(id, &[(1.0, 1.0)], 1.0, Stroke::Dodge { exposure: 50 })
            .unwrap();
        assert_eq!(pixel(&doc, id, 0, 0)[0], 161);
    }

    #[test]
    fn dodge_leaves_alpha_alone_and_skips_transparent_pixels() {
        // (0, 0) fully transparent, (1, 1) at alpha 128.
        let mut pixels = solid(3, 3, [100, 0, 0, 255]);
        pixels[3] = 0;
        pixels[(3 + 1) * 4 + 3] = 128;
        let mut doc = Document::new(3, 3).unwrap();
        let id = doc.add_layer("l", &pixels, 3, 3).unwrap();
        assert_eq!(pixel(&doc, id, 1, 1)[3], 128);
        doc.stroke(id, &[(1.0, 1.0)], 3.0, Stroke::Dodge { exposure: 50 })
            .unwrap();
        assert_eq!(pixel(&doc, id, 1, 1), [178, 128, 128, 128]);
        assert_eq!(pixel(&doc, id, 0, 0), [100, 0, 0, 0]);
    }

    #[test]
    fn dodge_respects_the_selection_and_a_locked_layer() {
        let mut doc = Document::new(3, 3).unwrap();
        let id = doc
            .add_layer("l", &solid(3, 3, [100, 0, 200, 255]), 3, 3)
            .unwrap();
        doc.select_rectangle(0.0, 0.0, 1.0, 1.0).unwrap();
        doc.stroke(id, &[(1.0, 1.0)], 3.0, Stroke::Dodge { exposure: 50 })
            .unwrap();
        assert_eq!(pixel(&doc, id, 0, 0), [178, 128, 228, 255]);
        assert_eq!(pixel(&doc, id, 1, 1), [100, 0, 200, 255]);
        doc.set_locked(id, true).unwrap();
        assert!(doc
            .stroke(id, &[(1.0, 1.0)], 3.0, Stroke::Dodge { exposure: 50 })
            .is_err());
    }

    #[test]
    fn burn_darkens_toward_black_by_exposure() {
        // Exposure 50 at full coverage halves every channel: 100 -> 50,
        // 200 -> 100, 255 -> 127.5 -> 128.
        let mut doc = Document::new(3, 3).unwrap();
        let id = doc
            .add_layer("l", &solid(3, 3, [100, 200, 255, 255]), 3, 3)
            .unwrap();
        doc.stroke(id, &[(1.0, 1.0)], 3.0, Stroke::Burn { exposure: 50 })
            .unwrap();
        assert_eq!(pixel(&doc, id, 1, 1), [50, 100, 128, 255]);
    }

    #[test]
    fn burn_at_full_exposure_is_black_and_at_zero_is_an_identity() {
        let mut doc = Document::new(3, 3).unwrap();
        let id = doc
            .add_layer("l", &solid(3, 3, [100, 0, 200, 255]), 3, 3)
            .unwrap();
        doc.stroke(id, &[(1.0, 1.0)], 3.0, Stroke::Burn { exposure: 0 })
            .unwrap();
        assert_eq!(pixel(&doc, id, 1, 1), [100, 0, 200, 255]);
        doc.stroke(id, &[(1.0, 1.0)], 3.0, Stroke::Burn { exposure: 100 })
            .unwrap();
        assert_eq!(pixel(&doc, id, 1, 1), [0, 0, 0, 255]);
    }

    #[test]
    fn burn_scales_with_the_brushs_soft_edge_coverage() {
        // The same 0.7929 edge coverage as Dodge's test: 200 * (1 - 0.5 *
        // 0.7929) -> 120.7 -> 121.
        let mut doc = Document::new(3, 3).unwrap();
        let id = doc
            .add_layer("l", &solid(3, 3, [200, 0, 0, 255]), 3, 3)
            .unwrap();
        doc.stroke(id, &[(1.0, 1.0)], 1.0, Stroke::Burn { exposure: 50 })
            .unwrap();
        assert_eq!(pixel(&doc, id, 0, 0)[0], 121);
    }

    #[test]
    fn burn_leaves_alpha_alone_and_skips_transparent_pixels() {
        let mut pixels = solid(3, 3, [100, 200, 0, 255]);
        pixels[3] = 0;
        pixels[(3 + 1) * 4 + 3] = 128;
        let mut doc = Document::new(3, 3).unwrap();
        let id = doc.add_layer("l", &pixels, 3, 3).unwrap();
        doc.stroke(id, &[(1.0, 1.0)], 3.0, Stroke::Burn { exposure: 50 })
            .unwrap();
        assert_eq!(pixel(&doc, id, 1, 1), [50, 100, 0, 128]);
        assert_eq!(pixel(&doc, id, 0, 0), [100, 200, 0, 0]);
    }

    #[test]
    fn burn_undoes_dodge_only_approximately_and_respects_locks() {
        // Dodge then Burn at the same exposure is not an identity (the two
        // move by different amounts): 100 -> 178 -> 89.
        let mut doc = Document::new(3, 3).unwrap();
        let id = doc
            .add_layer("l", &solid(3, 3, [100, 0, 0, 255]), 3, 3)
            .unwrap();
        doc.stroke(id, &[(1.0, 1.0)], 3.0, Stroke::Dodge { exposure: 50 })
            .unwrap();
        doc.stroke(id, &[(1.0, 1.0)], 3.0, Stroke::Burn { exposure: 50 })
            .unwrap();
        assert_eq!(pixel(&doc, id, 1, 1)[0], 89);
        doc.set_locked(id, true).unwrap();
        assert!(doc
            .stroke(id, &[(1.0, 1.0)], 3.0, Stroke::Burn { exposure: 50 })
            .is_err());
    }

    fn sponge(flow: u8, saturate: bool) -> Stroke<'static> {
        Stroke::Sponge { flow, saturate }
    }

    #[test]
    fn sponge_desaturates_toward_grey() {
        // (200, 100, 100) is HSL (0, 0.476, 0.588): flow 100 drops it to
        // the grey of its lightness, 150; flow 50 halves the saturation to
        // 0.238 -> (175, 125, 125).
        let mut doc = Document::new(3, 3).unwrap();
        let id = doc
            .add_layer("l", &solid(3, 3, [200, 100, 100, 255]), 3, 3)
            .unwrap();
        doc.stroke(id, &[(1.0, 1.0)], 3.0, sponge(50, false))
            .unwrap();
        assert_eq!(pixel(&doc, id, 1, 1), [175, 125, 125, 255]);
        let mut doc = Document::new(3, 3).unwrap();
        let id = doc
            .add_layer("l", &solid(3, 3, [200, 100, 100, 255]), 3, 3)
            .unwrap();
        doc.stroke(id, &[(1.0, 1.0)], 3.0, sponge(100, false))
            .unwrap();
        assert_eq!(pixel(&doc, id, 1, 1), [150, 150, 150, 255]);
    }

    #[test]
    fn sponge_saturates_toward_full_saturation_keeping_hue() {
        // Full saturation at lightness 0.588 is (255, 45, 45); flow 50 lands
        // at s = 0.738 -> (228, 73, 73). A green keeps its hue: (45, 255, 45).
        let mut doc = Document::new(3, 3).unwrap();
        let id = doc
            .add_layer("l", &solid(3, 3, [200, 100, 100, 255]), 3, 3)
            .unwrap();
        doc.stroke(id, &[(1.0, 1.0)], 3.0, sponge(50, true))
            .unwrap();
        assert_eq!(pixel(&doc, id, 1, 1), [228, 73, 73, 255]);
        let mut doc = Document::new(3, 3).unwrap();
        let id = doc
            .add_layer("l", &solid(3, 3, [200, 100, 100, 255]), 3, 3)
            .unwrap();
        doc.stroke(id, &[(1.0, 1.0)], 3.0, sponge(100, true))
            .unwrap();
        assert_eq!(pixel(&doc, id, 1, 1), [255, 45, 45, 255]);
        let mut doc = Document::new(3, 3).unwrap();
        let id = doc
            .add_layer("l", &solid(3, 3, [100, 200, 100, 255]), 3, 3)
            .unwrap();
        doc.stroke(id, &[(1.0, 1.0)], 3.0, sponge(100, true))
            .unwrap();
        assert_eq!(pixel(&doc, id, 1, 1), [45, 255, 45, 255]);
    }

    #[test]
    fn sponge_scales_with_the_brushs_soft_edge_coverage() {
        // The 0.7929 edge coverage at flow 50 desaturates (200, 100, 100)
        // to s = 0.476 * (1 - 0.396) -> (180, 120, 120).
        let mut doc = Document::new(3, 3).unwrap();
        let id = doc
            .add_layer("l", &solid(3, 3, [200, 100, 100, 255]), 3, 3)
            .unwrap();
        doc.stroke(id, &[(1.0, 1.0)], 1.0, sponge(50, false))
            .unwrap();
        assert_eq!(pixel(&doc, id, 0, 0), [180, 120, 120, 255]);
    }

    #[test]
    fn sponge_leaves_greys_alpha_and_transparent_pixels_alone() {
        // (0, 0) transparent, (1, 1) at alpha 128, (2, 2) grey.
        let mut pixels = solid(3, 3, [200, 100, 100, 255]);
        pixels[3] = 0;
        pixels[(3 + 1) * 4 + 3] = 128;
        pixels[32..36].copy_from_slice(&[150, 150, 150, 255]);
        let mut doc = Document::new(3, 3).unwrap();
        let id = doc.add_layer("l", &pixels, 3, 3).unwrap();
        doc.stroke(id, &[(1.0, 1.0)], 3.0, sponge(100, true))
            .unwrap();
        assert_eq!(pixel(&doc, id, 0, 0), [200, 100, 100, 0]);
        assert_eq!(pixel(&doc, id, 1, 1), [255, 45, 45, 128]);
        assert_eq!(pixel(&doc, id, 2, 2), [150, 150, 150, 255]);
        doc.stroke(id, &[(1.0, 1.0)], 3.0, sponge(0, false))
            .unwrap();
        assert_eq!(pixel(&doc, id, 1, 1), [255, 45, 45, 128]);
    }

    #[test]
    fn sponge_respects_the_selection_and_a_locked_layer() {
        let mut doc = Document::new(3, 3).unwrap();
        let id = doc
            .add_layer("l", &solid(3, 3, [200, 100, 100, 255]), 3, 3)
            .unwrap();
        doc.select_rectangle(0.0, 0.0, 1.0, 1.0).unwrap();
        doc.stroke(id, &[(1.0, 1.0)], 3.0, sponge(100, false))
            .unwrap();
        assert_eq!(pixel(&doc, id, 0, 0), [150, 150, 150, 255]);
        assert_eq!(pixel(&doc, id, 1, 1), [200, 100, 100, 255]);
        doc.set_locked(id, true).unwrap();
        assert!(doc
            .stroke(id, &[(1.0, 1.0)], 3.0, sponge(100, false))
            .is_err());
    }

    #[test]
    fn blur_tool_at_full_strength_matches_the_box_blur_filter() {
        // A radius-3 dot covers every pixel of the 3x3 fully, so the stroke
        // is exactly Filter > Blur > Box Blur at radius 1 -- including the
        // edge-clamped corners ((10+10+20)*2 + 40+40+50) / 9 = 23.
        let (mut doc, id) = ramped_3x3();
        doc.stroke(id, &[(1.0, 1.0)], 3.0, Stroke::Blur { strength: 100 })
            .unwrap();
        assert_eq!(
            red_channel_grid(&doc),
            vec![vec![23, 30, 36], vec![43, 50, 56], vec![63, 70, 76]]
        );
        let (mut filtered, id2) = ramped_3x3();
        filtered.box_blur(id2, 1).unwrap();
        assert_eq!(doc.layers()[0].pixels, filtered.layers()[0].pixels);
    }

    #[test]
    fn blur_tool_strength_scales_the_move() {
        // Half way from 10 to 23 is 16.5 -> 17; strength 0 changes nothing.
        let (mut doc, id) = ramped_3x3();
        doc.stroke(id, &[(1.0, 1.0)], 3.0, Stroke::Blur { strength: 50 })
            .unwrap();
        assert_eq!(pixel(&doc, id, 0, 0)[0], 17);
        let (mut doc, id) = ramped_3x3();
        doc.stroke(id, &[(1.0, 1.0)], 3.0, Stroke::Blur { strength: 0 })
            .unwrap();
        assert_eq!(doc.layers()[0].pixels, ramped_3x3().0.layers()[0].pixels);
    }

    #[test]
    fn blur_tool_scales_with_the_brushs_soft_edge_coverage() {
        // The 0.7929 edge coverage moves 10 toward 23 by 10.3 -> 20.
        let (mut doc, id) = ramped_3x3();
        doc.stroke(id, &[(1.0, 1.0)], 1.0, Stroke::Blur { strength: 100 })
            .unwrap();
        assert_eq!(pixel(&doc, id, 0, 0)[0], 20);
    }

    #[test]
    fn blur_tool_blurs_alpha_too_and_respects_the_selection() {
        // depth_ramped_3x3's alpha columns 0 / 128 / 255 average to 127 at
        // the centre; its red stays the symmetric 50.
        let (mut doc, id) = depth_ramped_3x3();
        doc.stroke(id, &[(1.0, 1.0)], 3.0, Stroke::Blur { strength: 100 })
            .unwrap();
        assert_eq!(pixel(&doc, id, 1, 1), [50, 0, 0, 127]);

        let (mut doc, id) = ramped_3x3();
        doc.select_rectangle(0.0, 0.0, 1.0, 1.0).unwrap();
        doc.stroke(id, &[(1.0, 1.0)], 3.0, Stroke::Blur { strength: 100 })
            .unwrap();
        assert_eq!(pixel(&doc, id, 0, 0)[0], 23);
        assert_eq!(pixel(&doc, id, 1, 1)[0], 50);
        assert_eq!(pixel(&doc, id, 1, 0)[0], 20);
    }

    #[test]
    fn blur_tool_reads_the_pre_stroke_layer_and_rejects_a_locked_layer() {
        // A stroke dragged across the whole layer equals the one-dot stroke:
        // every pixel is blurred from the untouched snapshot, never from
        // pixels the stroke already softened.
        let (mut doc, id) = ramped_3x3();
        doc.stroke(
            id,
            &[(0.0, 0.0), (3.0, 3.0)],
            3.0,
            Stroke::Blur { strength: 100 },
        )
        .unwrap();
        assert_eq!(
            red_channel_grid(&doc),
            vec![vec![23, 30, 36], vec![43, 50, 56], vec![63, 70, 76]]
        );
        doc.set_locked(id, true).unwrap();
        assert!(doc
            .stroke(id, &[(1.0, 1.0)], 3.0, Stroke::Blur { strength: 100 })
            .is_err());
    }

    #[test]
    fn sharpen_tool_at_full_strength_matches_sharpen_more() {
        // original + (original - box blur): the corner 10 - 13 clamps to 0,
        // the far corner 90 + 14 = 104, the centre stays 50.
        let (mut doc, id) = ramped_3x3();
        doc.stroke(
            id,
            &[(1.0, 1.0)],
            3.0,
            Stroke::Sharpen {
                strength: 100,
                protect_detail: false,
                sample_all_layers: false,
            },
        )
        .unwrap();
        assert_eq!(
            red_channel_grid(&doc),
            vec![vec![0, 10, 24], vec![37, 50, 64], vec![77, 90, 104]]
        );
        let (mut filtered, id2) = ramped_3x3();
        filtered.sharpen_more(id2).unwrap();
        assert_eq!(doc.layers()[0].pixels, filtered.layers()[0].pixels);
    }

    #[test]
    fn sharpen_tool_strength_scales_the_move() {
        // Half strength: 10 - 6.5 = 3.5 -> 4 and 90 + 7 = 97; strength 0 is
        // an identity.
        let (mut doc, id) = ramped_3x3();
        doc.stroke(
            id,
            &[(1.0, 1.0)],
            3.0,
            Stroke::Sharpen {
                strength: 50,
                protect_detail: false,
                sample_all_layers: false,
            },
        )
        .unwrap();
        assert_eq!(pixel(&doc, id, 0, 0)[0], 4);
        assert_eq!(pixel(&doc, id, 2, 2)[0], 97);
        let (mut doc, id) = ramped_3x3();
        doc.stroke(
            id,
            &[(1.0, 1.0)],
            3.0,
            Stroke::Sharpen {
                strength: 0,
                protect_detail: false,
                sample_all_layers: false,
            },
        )
        .unwrap();
        assert_eq!(doc.layers()[0].pixels, ramped_3x3().0.layers()[0].pixels);
    }

    #[test]
    fn sharpen_tool_scales_with_the_brushs_soft_edge_coverage() {
        // Pixel (1, 0) sits sqrt(0.5) from (1, 1): coverage 0.7929, so 20
        // moves by -10 * 0.7929 to 12.07 -> 12.
        let (mut doc, id) = ramped_3x3();
        doc.stroke(
            id,
            &[(1.0, 1.0)],
            1.0,
            Stroke::Sharpen {
                strength: 100,
                protect_detail: false,
                sample_all_layers: false,
            },
        )
        .unwrap();
        assert_eq!(pixel(&doc, id, 1, 0)[0], 12);
    }

    #[test]
    fn sharpen_tool_leaves_alpha_alone_and_respects_the_selection() {
        let (mut doc, id) = depth_ramped_3x3();
        doc.stroke(
            id,
            &[(1.0, 1.0)],
            3.0,
            Stroke::Sharpen {
                strength: 100,
                protect_detail: false,
                sample_all_layers: false,
            },
        )
        .unwrap();
        assert_eq!(pixel(&doc, id, 1, 1), [50, 0, 0, 128]);
        assert_eq!(pixel(&doc, id, 0, 1)[3], 0);

        let (mut doc, id) = ramped_3x3();
        doc.select_rectangle(2.0, 2.0, 3.0, 3.0).unwrap();
        doc.stroke(
            id,
            &[(1.0, 1.0)],
            3.0,
            Stroke::Sharpen {
                strength: 100,
                protect_detail: false,
                sample_all_layers: false,
            },
        )
        .unwrap();
        assert_eq!(pixel(&doc, id, 2, 2)[0], 104);
        assert_eq!(pixel(&doc, id, 0, 0)[0], 10);
    }

    #[test]
    fn sharpen_tool_reads_the_pre_stroke_layer_and_rejects_a_locked_layer() {
        let (mut doc, id) = ramped_3x3();
        doc.stroke(
            id,
            &[(0.0, 0.0), (3.0, 3.0)],
            3.0,
            Stroke::Sharpen {
                strength: 100,
                protect_detail: false,
                sample_all_layers: false,
            },
        )
        .unwrap();
        assert_eq!(
            red_channel_grid(&doc),
            vec![vec![0, 10, 24], vec![37, 50, 64], vec![77, 90, 104]]
        );
        doc.set_locked(id, true).unwrap();
        assert!(doc
            .stroke(
                id,
                &[(1.0, 1.0)],
                3.0,
                Stroke::Sharpen {
                    strength: 100,
                    protect_detail: false,
                    sample_all_layers: false
                }
            )
            .is_err());
    }

    /// A transparent 4x4 with a one-pixel red dot painted at (0, 0) under
    /// `symmetry`: radius 0.5 at the pixel's centre covers it fully and its
    /// neighbours (a full pixel away) not at all.
    fn symmetric_dot(symmetry: Option<Symmetry>) -> (Document, LayerId, Option<Rect>) {
        let mut doc = Document::new(4, 4).unwrap();
        let id = doc
            .add_layer("l", &solid(4, 4, [0, 0, 0, 0]), 4, 4)
            .unwrap();
        let rect = doc
            .stroke_symmetric(
                id,
                &[(0.5, 0.5)],
                0.5,
                Stroke::Brush {
                    color: [255, 0, 0, 255],
                },
                symmetry,
            )
            .unwrap();
        (doc, id, rect)
    }

    fn painted(doc: &Document, id: LayerId) -> Vec<(u32, u32)> {
        (0..4)
            .flat_map(|y| (0..4).map(move |x| (x, y)))
            .filter(|&(x, y)| pixel(doc, id, x, y)[3] > 0)
            .collect()
    }

    #[test]
    fn polygonal_lasso_selects_the_pixel_centres_inside_a_triangle() {
        // The right triangle (0,0)-(4,0)-(0,4) on 4x4 contains a pixel
        // centre when (x + 0.5) + (y + 0.5) < 4, i.e. x + y < 3: six pixels.
        let mut doc = Document::new(4, 4).unwrap();
        doc.select_polygon_with(SelectionMode::New, &[(0.0, 0.0), (4.0, 0.0), (0.0, 4.0)])
            .unwrap();
        assert_eq!(
            selected_pixels(&doc),
            vec![(0, 0), (1, 0), (2, 0), (0, 1), (1, 1), (0, 2)]
        );
        let s = doc.selection().unwrap();
        assert_eq!(s.shape, SelectionShape::Mask);
        assert_eq!(
            s.bounds,
            Rect {
                x0: 0,
                y0: 0,
                x1: 3,
                y1: 3
            }
        );
    }

    #[test]
    fn polygonal_lasso_square_matches_the_rectangle_marquee() {
        let mut doc = Document::new(4, 4).unwrap();
        doc.select_polygon_with(
            SelectionMode::New,
            &[(1.0, 1.0), (3.0, 1.0), (3.0, 3.0), (1.0, 3.0)],
        )
        .unwrap();
        assert_eq!(selected_pixels(&doc), vec![(1, 1), (2, 1), (1, 2), (2, 2)]);
        let mut marquee = Document::new(4, 4).unwrap();
        marquee.select_rectangle(1.0, 1.0, 3.0, 3.0).unwrap();
        assert_eq!(selected_pixels(&marquee), selected_pixels(&doc));
    }

    #[test]
    fn polygonal_lasso_combines_with_the_current_selection() {
        let mut doc = Document::new(4, 4).unwrap();
        doc.select_rectangle(3.0, 3.0, 4.0, 4.0).unwrap();
        doc.select_polygon_with(SelectionMode::Add, &[(0.0, 0.0), (2.0, 0.0), (0.0, 2.0)])
            .unwrap();
        assert_eq!(selected_pixels(&doc), vec![(0, 0), (3, 3)]);
        doc.select_polygon_with(
            SelectionMode::Subtract,
            &[(0.0, 0.0), (1.0, 0.0), (1.0, 1.0), (0.0, 1.0)],
        )
        .unwrap();
        assert_eq!(selected_pixels(&doc), vec![(3, 3)]);
    }

    #[test]
    fn polygonal_lasso_uses_the_even_odd_rule_for_a_self_crossing_outline() {
        // The bow-tie (0,0)-(4,3)-(4,0)-(0,3) on 4x3 crosses itself at the
        // centre; its two lobes are the left and right triangles, whose
        // diagonals (y = 3x/4 and y = 3 - 3x/4) pass through no pixel
        // centre. Left lobe: x = 0.5 admits y 0.5..2.5, x = 1.5 only 1.5;
        // mirrored on the right.
        let mut doc = Document::new(4, 3).unwrap();
        doc.select_polygon_with(
            SelectionMode::New,
            &[(0.0, 0.0), (4.0, 3.0), (4.0, 0.0), (0.0, 3.0)],
        )
        .unwrap();
        assert_eq!(
            selected_pixels(&doc),
            vec![
                (0, 0),
                (3, 0),
                (0, 1),
                (1, 1),
                (2, 1),
                (3, 1),
                (0, 2),
                (3, 2)
            ]
        );
    }

    #[test]
    fn polygonal_lasso_rejects_bad_polygons() {
        let (mut doc, _) = ramped_3x3();
        doc.select_rectangle(0.0, 0.0, 1.0, 1.0).unwrap();
        assert!(doc
            .select_polygon_with(SelectionMode::New, &[(0.0, 0.0), (2.0, 0.0)])
            .is_err());
        assert!(doc
            .select_polygon_with(
                SelectionMode::New,
                &[(0.0, 0.0), (f32::NAN, 0.0), (0.0, 2.0)]
            )
            .is_err());
        let err = doc
            .select_polygon_with(
                SelectionMode::New,
                &[(-3.0, -3.0), (-1.0, -3.0), (-1.0, -1.0)],
            )
            .unwrap_err();
        assert!(err.contains("nothing selected"), "{err}");
        assert_eq!(doc.selection().unwrap().shape, SelectionShape::Rectangle);
    }

    #[test]
    fn lasso_drops_consecutive_duplicate_points() {
        let mut doc = Document::new(4, 4).unwrap();
        let trail = [
            (0.0, 0.0),
            (0.0, 0.0),
            (4.0, 0.0),
            (4.0, 0.0),
            (4.0, 0.0),
            (0.0, 4.0),
            (0.0, 4.0),
        ];
        doc.select_lasso_with(SelectionMode::New, &trail).unwrap();
        let mut polygon = Document::new(4, 4).unwrap();
        polygon
            .select_polygon_with(SelectionMode::New, &[(0.0, 0.0), (4.0, 0.0), (0.0, 4.0)])
            .unwrap();
        assert_eq!(selected_pixels(&doc), selected_pixels(&polygon));
        assert_eq!(selected_pixels(&doc).len(), 6);
    }

    #[test]
    fn lasso_trail_approximating_a_circle_matches_the_ellipse_marquee() {
        // A 64-gon inscribed in the canvas-spanning circle on 4x4: its
        // apothem 2 cos(pi/64) = 1.998 clears every pixel centre the ellipse
        // admits (the nearest edge centres sit 1.58 from the middle) and
        // excludes the corners (2.12 away), exactly as the ellipse does.
        let trail: Vec<(f32, f32)> = (0..64)
            .map(|i| {
                let t = i as f32 / 64.0 * std::f32::consts::TAU;
                (2.0 + 2.0 * t.cos(), 2.0 + 2.0 * t.sin())
            })
            .collect();
        let mut doc = Document::new(4, 4).unwrap();
        doc.select_lasso_with(SelectionMode::New, &trail).unwrap();
        let mut marquee = Document::new(4, 4).unwrap();
        marquee.select_ellipse(0.0, 0.0, 4.0, 4.0).unwrap();
        assert_eq!(selected_pixels(&doc), selected_pixels(&marquee));
        assert_eq!(selected_pixels(&doc).len(), 12);
    }

    #[test]
    fn lasso_combines_with_the_current_selection() {
        let mut doc = Document::new(4, 4).unwrap();
        doc.select_rectangle(3.0, 3.0, 4.0, 4.0).unwrap();
        doc.select_lasso_with(
            SelectionMode::Add,
            &[(0.0, 0.0), (0.0, 0.0), (2.0, 0.0), (0.0, 2.0)],
        )
        .unwrap();
        assert_eq!(selected_pixels(&doc), vec![(0, 0), (3, 3)]);
    }

    #[test]
    fn lasso_rejects_a_trail_that_encloses_nothing() {
        let (mut doc, _) = ramped_3x3();
        doc.select_rectangle(0.0, 0.0, 1.0, 1.0).unwrap();
        let err = doc
            .select_lasso_with(SelectionMode::New, &[(0.0, 0.0), (0.0, 0.0), (2.0, 2.0)])
            .unwrap_err();
        assert!(err.contains("enclose"), "{err}");
        let err = doc
            .select_lasso_with(
                SelectionMode::New,
                &[(0.0, 0.0), (1.0, 1.0), (2.0, 2.0), (3.0, 3.0)],
            )
            .unwrap_err();
        assert!(err.contains("nothing selected"), "{err}");
        assert_eq!(doc.selection().unwrap().shape, SelectionShape::Rectangle);
    }

    #[test]
    fn lasso_closes_back_to_its_start() {
        // The same three corners in either winding, with the trail's end
        // left open, still enclose the triangle.
        let mut doc = Document::new(4, 4).unwrap();
        doc.select_lasso_with(SelectionMode::New, &[(0.0, 4.0), (4.0, 0.0), (0.0, 0.0)])
            .unwrap();
        assert_eq!(
            selected_pixels(&doc),
            vec![(0, 0), (1, 0), (2, 0), (0, 1), (1, 1), (0, 2)]
        );
    }

    #[test]
    fn move_tool_shifts_the_whole_layer_with_transparent_fill() {
        let (mut doc, id) = ramped_3x3();
        let rect = doc.move_pixels(id, 1, 0).unwrap();
        assert_eq!(
            rect,
            Some(Rect {
                x0: 0,
                y0: 0,
                x1: 3,
                y1: 3
            })
        );
        assert_eq!(
            red_channel_grid(&doc),
            vec![vec![0, 10, 20], vec![0, 40, 50], vec![0, 70, 80]]
        );
        assert_eq!(pixel(&doc, id, 0, 1), [0, 0, 0, 0]);
        let (mut translated, id2) = ramped_3x3();
        translated.translate(id2, 1, 0).unwrap();
        assert_eq!(doc.layers()[0].pixels, translated.layers()[0].pixels);
    }

    #[test]
    fn move_tool_moves_only_the_selected_pixels_and_their_outline() {
        let (mut doc, id) = ramped_3x3();
        doc.select_rectangle(0.0, 0.0, 1.0, 1.0).unwrap();
        doc.move_pixels(id, 1, 1).unwrap();
        assert_eq!(pixel(&doc, id, 1, 1), [10, 0, 0, 255]);
        assert_eq!(pixel(&doc, id, 0, 0), [0, 0, 0, 0]);
        assert_eq!(pixel(&doc, id, 2, 2), [90, 0, 0, 255]);
        assert_eq!(pixel(&doc, id, 1, 0), [20, 0, 0, 255]);
        let s = doc.selection().unwrap();
        assert_eq!(
            s.bounds,
            Rect {
                x0: 1,
                y0: 1,
                x1: 2,
                y1: 2
            }
        );
    }

    #[test]
    fn move_tool_reads_the_pre_move_pixels_when_source_and_target_overlap() {
        // Moving the pair 10 20 right by one lands 10 on 20's old spot and
        // 20 on 30's: each moved pixel is read from the snapshot, not from
        // a neighbour already overwritten.
        let (mut doc, id) = ramped_3x3();
        doc.select_rectangle(0.0, 0.0, 2.0, 1.0).unwrap();
        doc.move_pixels(id, 1, 0).unwrap();
        assert_eq!(red_channel_grid(&doc)[0], vec![0, 10, 20]);
        assert_eq!(pixel(&doc, id, 0, 0)[3], 0);
    }

    #[test]
    fn move_tool_drops_pixels_and_the_outline_that_leave_the_canvas() {
        let (mut doc, id) = ramped_3x3();
        doc.select_rectangle(2.0, 0.0, 3.0, 3.0).unwrap();
        doc.move_pixels(id, 1, 0).unwrap();
        for y in 0..3 {
            assert_eq!(pixel(&doc, id, 2, y)[3], 0, "row {y}");
        }
        assert_eq!(pixel(&doc, id, 1, 1), [50, 0, 0, 255]);
        assert!(doc.selection().is_none());
    }

    #[test]
    fn move_tool_ignores_a_zero_move_and_rejects_locked_or_unknown_layers() {
        let (mut doc, id) = ramped_3x3();
        assert_eq!(doc.move_pixels(id, 0, 0).unwrap(), None);
        assert_eq!(doc.layers()[0].pixels, ramped_3x3().0.layers()[0].pixels);
        assert!(doc.move_pixels(999, 1, 0).is_err());
        doc.select_rectangle(0.0, 0.0, 1.0, 1.0).unwrap();
        doc.set_locked(id, true).unwrap();
        assert!(doc.move_pixels(id, 1, 0).is_err());
        assert_eq!(pixel(&doc, id, 0, 0), [10, 0, 0, 255]);
        assert_eq!(doc.selection().unwrap().shape, SelectionShape::Rectangle);
    }

    fn clone(offset: (i32, i32)) -> Stroke<'static> {
        Stroke::Clone { offset }
    }

    #[test]
    fn clone_stamp_paints_the_pixel_offset_from_the_source() {
        // A full-coverage dot on (0, 0) with the source one pixel to the
        // right copies (1, 0)'s 20 over it.
        let (mut doc, id) = ramped_3x3();
        doc.stroke(id, &[(0.5, 0.5)], 0.5, clone((1, 0))).unwrap();
        assert_eq!(pixel(&doc, id, 0, 0), [20, 0, 0, 255]);
        assert_eq!(pixel(&doc, id, 1, 0), [20, 0, 0, 255]);
        assert_eq!(pixel(&doc, id, 0, 1), [40, 0, 0, 255]);
    }

    #[test]
    fn clone_stamp_skips_samples_off_the_canvas() {
        // Everything covered: each pixel takes its right-hand neighbour and
        // the right column, whose source lies off the canvas, is untouched.
        let (mut doc, id) = ramped_3x3();
        doc.stroke(id, &[(1.0, 1.0)], 3.0, clone((1, 0))).unwrap();
        assert_eq!(
            red_channel_grid(&doc),
            vec![vec![20, 30, 30], vec![50, 60, 60], vec![80, 90, 90]]
        );
    }

    #[test]
    fn clone_stamp_blends_the_sample_by_coverage() {
        // The 0.7929 edge coverage composites (1, 0)'s 20 over (0, 0)'s 10
        // source-over: 0.7929 * 20 + 0.2071 * 10 = 17.9 -> 18.
        let (mut doc, id) = ramped_3x3();
        doc.stroke(id, &[(1.0, 1.0)], 1.0, clone((1, 0))).unwrap();
        assert_eq!(pixel(&doc, id, 0, 0), [18, 0, 0, 255]);
    }

    #[test]
    fn clone_stamp_reads_the_pre_stroke_layer() {
        // Cloning from the left: column 1 takes column 0's values and column
        // 2 takes column 1's ORIGINAL values (20, 50, 80), not the 10s just
        // written there.
        let (mut doc, id) = ramped_3x3();
        doc.stroke(id, &[(1.0, 1.0)], 3.0, clone((-1, 0))).unwrap();
        assert_eq!(
            red_channel_grid(&doc),
            vec![vec![10, 10, 20], vec![40, 40, 50], vec![70, 70, 80]]
        );
    }

    #[test]
    fn clone_stamp_respects_the_selection_transparency_and_locks() {
        let (mut doc, id) = ramped_3x3();
        doc.select_rectangle(0.0, 0.0, 1.0, 1.0).unwrap();
        doc.stroke(id, &[(1.0, 1.0)], 3.0, clone((1, 0))).unwrap();
        assert_eq!(pixel(&doc, id, 0, 0)[0], 20);
        assert_eq!(pixel(&doc, id, 1, 0)[0], 20);
        assert_eq!(pixel(&doc, id, 1, 1)[0], 50);
        // A transparent sample paints nothing.
        let (mut doc, id) = depth_ramped_3x3();
        doc.stroke(id, &[(1.5, 1.5)], 0.5, clone((-1, 0))).unwrap();
        assert_eq!(pixel(&doc, id, 1, 1), [50, 0, 0, 128]);
        doc.set_locked(id, true).unwrap();
        assert!(doc.stroke(id, &[(1.5, 1.5)], 0.5, clone((1, 0))).is_err());
    }

    #[test]
    fn history_brush_paints_the_remembered_pixel_back() {
        // Invert the whole layer, then brush one pixel back from the
        // remembered original: (0, 0) returns to 10, (1, 1) stays inverted.
        let (mut doc, id) = ramped_3x3();
        let original = doc.layers()[0].pixels.clone();
        doc.invert_colors(id).unwrap();
        assert_eq!(pixel(&doc, id, 1, 1), [205, 255, 255, 255]);
        doc.stroke(
            id,
            &[(0.5, 0.5)],
            0.5,
            Stroke::History { source: &original },
        )
        .unwrap();
        assert_eq!(pixel(&doc, id, 0, 0), [10, 0, 0, 255]);
        assert_eq!(pixel(&doc, id, 1, 1), [205, 255, 255, 255]);
    }

    #[test]
    fn history_brush_over_everything_restores_the_source_exactly() {
        let (mut doc, id) = ramped_3x3();
        let original = doc.layers()[0].pixels.clone();
        doc.invert_colors(id).unwrap();
        doc.stroke(
            id,
            &[(1.0, 1.0)],
            3.0,
            Stroke::History { source: &original },
        )
        .unwrap();
        assert_eq!(doc.layers()[0].pixels, original);
    }

    #[test]
    fn history_brush_blends_by_coverage() {
        // The 0.7929 edge coverage composites the source's 10 over a solid
        // 100: 0.7929 * 10 + 0.2071 * 100 = 28.6 -> 29.
        let (doc, _) = ramped_3x3();
        let original = doc.layers()[0].pixels.clone();
        let mut doc = Document::new(3, 3).unwrap();
        let id = doc
            .add_layer("l", &solid(3, 3, [100, 0, 0, 255]), 3, 3)
            .unwrap();
        doc.stroke(
            id,
            &[(1.0, 1.0)],
            1.0,
            Stroke::History { source: &original },
        )
        .unwrap();
        assert_eq!(pixel(&doc, id, 0, 0), [29, 0, 0, 255]);
    }

    #[test]
    fn history_brush_respects_transparency_and_the_selection() {
        // A transparent source pixel paints nothing; a selection confines
        // the restore.
        let (transparent, _) = depth_ramped_3x3();
        let source = transparent.layers()[0].pixels.clone();
        let mut doc = Document::new(3, 3).unwrap();
        let id = doc
            .add_layer("l", &solid(3, 3, [100, 0, 0, 255]), 3, 3)
            .unwrap();
        doc.stroke(id, &[(1.0, 1.0)], 3.0, Stroke::History { source: &source })
            .unwrap();
        assert_eq!(pixel(&doc, id, 0, 1), [100, 0, 0, 255]);
        assert_eq!(pixel(&doc, id, 2, 1), [60, 0, 0, 255]);

        let (mut doc, id) = ramped_3x3();
        let original = doc.layers()[0].pixels.clone();
        doc.invert_colors(id).unwrap();
        doc.select_rectangle(0.0, 0.0, 1.0, 1.0).unwrap();
        doc.stroke(
            id,
            &[(1.0, 1.0)],
            3.0,
            Stroke::History { source: &original },
        )
        .unwrap();
        assert_eq!(pixel(&doc, id, 0, 0)[0], 10);
        assert_eq!(pixel(&doc, id, 1, 0)[0], 235);
    }

    #[test]
    fn history_brush_rejects_a_mismatched_source_and_a_locked_layer() {
        let (mut doc, id) = ramped_3x3();
        let err = doc
            .stroke(
                id,
                &[(1.0, 1.0)],
                3.0,
                Stroke::History { source: &[0u8; 4] },
            )
            .unwrap_err();
        assert!(err.contains("size"), "{err}");
        let original = doc.layers()[0].pixels.clone();
        doc.set_locked(id, true).unwrap();
        assert!(doc
            .stroke(
                id,
                &[(1.0, 1.0)],
                3.0,
                Stroke::History { source: &original }
            )
            .is_err());
    }

    fn smudge(strength: u8) -> Stroke<'static> {
        Stroke::Smudge { strength }
    }

    #[test]
    fn smudge_drags_the_trailing_colour_forward() {
        // A one-pixel step to the right along the middle row: (1, 1) takes
        // (0, 1)'s 40; (0, 1)'s own source lies off the canvas and stays.
        let (mut doc, id) = ramped_3x3();
        doc.stroke(id, &[(0.5, 1.5), (1.5, 1.5)], 0.5, smudge(100))
            .unwrap();
        assert_eq!(red_channel_grid(&doc)[1], vec![40, 40, 60]);
        assert_eq!(red_channel_grid(&doc)[0], vec![10, 20, 30]);
    }

    #[test]
    fn smudge_strength_scales_the_pull() {
        let (mut doc, id) = ramped_3x3();
        doc.stroke(id, &[(0.5, 1.5), (1.5, 1.5)], 0.5, smudge(50))
            .unwrap();
        assert_eq!(pixel(&doc, id, 1, 1)[0], 45);
        let (mut doc, id) = ramped_3x3();
        doc.stroke(id, &[(0.5, 1.5), (1.5, 1.5)], 0.5, smudge(0))
            .unwrap();
        assert_eq!(doc.layers()[0].pixels, ramped_3x3().0.layers()[0].pixels);
    }

    #[test]
    fn smudge_follows_the_stroke_direction_and_scales_with_coverage() {
        // A diagonal step pulls (1, 1) from (0, 0)'s 10. With radius 1 the
        // horizontal step's edge covers (1, 0) at 0.5, pulling its 20 half
        // way toward (0, 0)'s 10.
        let (mut doc, id) = ramped_3x3();
        doc.stroke(id, &[(0.5, 0.5), (1.5, 1.5)], 0.5, smudge(100))
            .unwrap();
        assert_eq!(pixel(&doc, id, 1, 1)[0], 10);
        let (mut doc, id) = ramped_3x3();
        doc.stroke(id, &[(0.5, 1.5), (1.5, 1.5)], 1.0, smudge(100))
            .unwrap();
        assert_eq!(pixel(&doc, id, 1, 0)[0], 15);
    }

    #[test]
    fn smudge_needs_a_direction_and_reads_the_pre_stroke_layer() {
        let (mut doc, id) = ramped_3x3();
        doc.stroke(id, &[(1.5, 1.5)], 3.0, smudge(100)).unwrap();
        assert_eq!(doc.layers()[0].pixels, ramped_3x3().0.layers()[0].pixels);
        // A two-step drag across the whole row at full coverage reads every
        // source from the snapshot: the row shifts by one, not more.
        let (mut doc, id) = ramped_3x3();
        doc.stroke(id, &[(0.5, 1.5), (2.5, 1.5), (3.5, 1.5)], 0.5, smudge(100))
            .unwrap();
        assert_eq!(red_channel_grid(&doc)[1], vec![40, 40, 50]);
    }

    #[test]
    fn smudge_respects_the_selection_and_a_locked_layer() {
        let (mut doc, id) = ramped_3x3();
        doc.select_rectangle(0.0, 0.0, 1.0, 3.0).unwrap();
        doc.stroke(id, &[(0.5, 1.5), (1.5, 1.5)], 0.5, smudge(100))
            .unwrap();
        assert_eq!(red_channel_grid(&doc)[1], vec![40, 50, 60]);
        doc.set_locked(id, true).unwrap();
        assert!(doc
            .stroke(id, &[(0.5, 1.5), (1.5, 1.5)], 0.5, smudge(100))
            .is_err());
    }

    fn replace(color: [u8; 3], tolerance: u8) -> Stroke<'static> {
        Stroke::ColorReplace { color, tolerance }
    }

    #[test]
    fn color_replacement_keeps_lightness_and_takes_the_brush_hue() {
        // (100, 200, 100) is HSL (120, 0.476, 0.588); pure red's hue and
        // saturation at that lightness is (255, 45, 45).
        let mut doc = Document::new(3, 3).unwrap();
        let id = doc
            .add_layer("l", &solid(3, 3, [100, 200, 100, 255]), 3, 3)
            .unwrap();
        doc.stroke(id, &[(1.5, 1.5)], 3.0, replace([255, 0, 0], 32))
            .unwrap();
        assert_eq!(pixel(&doc, id, 1, 1), [255, 45, 45, 255]);
        assert_eq!(pixel(&doc, id, 0, 0), [255, 45, 45, 255]);
        let mut doc = Document::new(3, 3).unwrap();
        let id = doc
            .add_layer("l", &solid(3, 3, [100, 200, 100, 255]), 3, 3)
            .unwrap();
        doc.stroke(id, &[(1.5, 1.5)], 3.0, replace([0, 0, 255], 32))
            .unwrap();
        assert_eq!(pixel(&doc, id, 1, 1), [45, 45, 255, 255]);
    }

    #[test]
    fn color_replacement_only_touches_colours_near_the_first_point_sample() {
        // A blue pixel at (2, 2) is far from the green sampled under the
        // stroke's start, so tolerance 32 leaves it alone.
        let mut pixels = solid(3, 3, [100, 200, 100, 255]);
        pixels[32..36].copy_from_slice(&[50, 50, 200, 255]);
        let mut doc = Document::new(3, 3).unwrap();
        let id = doc.add_layer("l", &pixels, 3, 3).unwrap();
        doc.stroke(id, &[(0.5, 0.5), (2.5, 2.5)], 3.0, replace([255, 0, 0], 32))
            .unwrap();
        assert_eq!(pixel(&doc, id, 2, 2), [50, 50, 200, 255]);
        assert_eq!(pixel(&doc, id, 0, 0), [255, 45, 45, 255]);
        assert_eq!(pixel(&doc, id, 1, 1), [255, 45, 45, 255]);
        // Tolerance 255 replaces everything, the blue at its own lightness
        // (a radius-3 dot at the centre covers the corner fully).
        doc.stroke(id, &[(1.5, 1.5)], 3.0, replace([255, 0, 0], 255))
            .unwrap();
        assert_eq!(pixel(&doc, id, 2, 2), [250, 0, 0, 255]);
    }

    #[test]
    fn color_replacement_scales_with_coverage_and_colours_greys() {
        // The 0.7929 edge coverage mixes (100, 200, 100) toward (255, 45,
        // 45): (223, 77, 56). A grey takes the brush hue at its lightness.
        let mut doc = Document::new(3, 3).unwrap();
        let id = doc
            .add_layer("l", &solid(3, 3, [100, 200, 100, 255]), 3, 3)
            .unwrap();
        doc.stroke(id, &[(1.0, 1.0)], 1.0, replace([255, 0, 0], 32))
            .unwrap();
        assert_eq!(pixel(&doc, id, 0, 0), [223, 77, 56, 255]);
        let mut doc = Document::new(3, 3).unwrap();
        let id = doc
            .add_layer("l", &solid(3, 3, [150, 150, 150, 255]), 3, 3)
            .unwrap();
        doc.stroke(id, &[(1.5, 1.5)], 3.0, replace([255, 0, 0], 32))
            .unwrap();
        assert_eq!(pixel(&doc, id, 1, 1), [255, 45, 45, 255]);
    }

    #[test]
    fn color_replacement_leaves_alpha_and_transparent_pixels_alone() {
        let mut pixels = solid(3, 3, [100, 200, 100, 255]);
        pixels[3] = 0;
        pixels[(3 + 1) * 4 + 3] = 128;
        let mut doc = Document::new(3, 3).unwrap();
        let id = doc.add_layer("l", &pixels, 3, 3).unwrap();
        doc.stroke(id, &[(1.5, 1.5)], 3.0, replace([255, 0, 0], 32))
            .unwrap();
        assert_eq!(pixel(&doc, id, 0, 0), [100, 200, 100, 0]);
        assert_eq!(pixel(&doc, id, 1, 1), [255, 45, 45, 128]);
    }

    #[test]
    fn color_replacement_respects_the_selection_and_a_locked_layer() {
        let mut doc = Document::new(3, 3).unwrap();
        let id = doc
            .add_layer("l", &solid(3, 3, [100, 200, 100, 255]), 3, 3)
            .unwrap();
        doc.select_rectangle(0.0, 0.0, 1.0, 1.0).unwrap();
        doc.stroke(id, &[(1.5, 1.5)], 3.0, replace([255, 0, 0], 32))
            .unwrap();
        assert_eq!(pixel(&doc, id, 0, 0), [255, 45, 45, 255]);
        assert_eq!(pixel(&doc, id, 1, 1), [100, 200, 100, 255]);
        doc.set_locked(id, true).unwrap();
        assert!(doc
            .stroke(id, &[(1.5, 1.5)], 3.0, replace([255, 0, 0], 32))
            .is_err());
    }

    /// A green 3x3 background with a blue "subject" pixel at (2, 2).
    fn subject_on_green() -> (Document, LayerId) {
        let mut pixels = solid(3, 3, [100, 200, 100, 255]);
        pixels[32..36].copy_from_slice(&[50, 50, 200, 255]);
        let mut doc = Document::new(3, 3).unwrap();
        let id = doc.add_layer("l", &pixels, 3, 3).unwrap();
        (doc, id)
    }

    fn background_erase(tolerance: u8) -> Stroke<'static> {
        Stroke::BackgroundErase { tolerance }
    }

    #[test]
    fn background_eraser_erases_the_sampled_colour_and_spares_the_subject() {
        let (mut doc, id) = subject_on_green();
        doc.stroke(id, &[(0.5, 0.5), (2.5, 2.5)], 3.0, background_erase(32))
            .unwrap();
        for (x, y) in [(0, 0), (1, 1), (2, 0), (0, 2)] {
            assert_eq!(pixel(&doc, id, x, y), [100, 200, 100, 0], "({x}, {y})");
        }
        assert_eq!(pixel(&doc, id, 2, 2), [50, 50, 200, 255]);
    }

    #[test]
    fn background_eraser_samples_under_the_strokes_first_point() {
        // Starting on the blue subject erases it and spares the green.
        let (mut doc, id) = subject_on_green();
        doc.stroke(id, &[(2.5, 2.5), (0.5, 0.5)], 3.0, background_erase(32))
            .unwrap();
        assert_eq!(pixel(&doc, id, 2, 2)[3], 0);
        assert_eq!(pixel(&doc, id, 0, 0)[3], 255);
    }

    #[test]
    fn background_eraser_scales_with_coverage_and_tolerance() {
        // The 0.7929 edge coverage leaves 255 * (1 - 0.7929) = 52.8 -> 53.
        let (mut doc, id) = subject_on_green();
        doc.stroke(id, &[(1.0, 1.0)], 1.0, background_erase(0))
            .unwrap();
        assert_eq!(pixel(&doc, id, 0, 0)[3], 53);
        // Tolerance 255 takes the subject too.
        let (mut doc, id) = subject_on_green();
        doc.stroke(id, &[(0.5, 0.5), (2.5, 2.5)], 3.0, background_erase(255))
            .unwrap();
        assert_eq!(pixel(&doc, id, 2, 2)[3], 0);
    }

    #[test]
    fn background_eraser_keeps_colour_bytes_and_compounds_like_the_eraser() {
        let (mut doc, id) = subject_on_green();
        doc.stroke(id, &[(1.0, 1.0)], 1.0, background_erase(0))
            .unwrap();
        doc.stroke(id, &[(1.0, 1.0)], 1.0, background_erase(0))
            .unwrap();
        // 53 * (1 - 0.7929) = 11.0 -> 11; colour untouched.
        assert_eq!(pixel(&doc, id, 0, 0), [100, 200, 100, 11]);
    }

    #[test]
    fn background_eraser_respects_the_selection_and_a_locked_layer() {
        let (mut doc, id) = subject_on_green();
        doc.select_rectangle(0.0, 0.0, 1.0, 1.0).unwrap();
        doc.stroke(id, &[(1.5, 1.5)], 3.0, background_erase(32))
            .unwrap();
        assert_eq!(pixel(&doc, id, 0, 0)[3], 0);
        assert_eq!(pixel(&doc, id, 1, 1)[3], 255);
        doc.set_locked(id, true).unwrap();
        assert!(doc
            .stroke(id, &[(1.5, 1.5)], 3.0, background_erase(32))
            .is_err());
    }

    fn heal(offset: (i32, i32)) -> Stroke<'static> {
        Stroke::Heal { offset }
    }

    #[test]
    fn healing_brush_takes_source_texture_at_the_destinations_tone() {
        // Healing (1, 1) from (2, 1): sample 60, source mean 56, destination
        // mean 50 -> 60 + (50 - 56) = 54. (0, 0) from (1, 0): 20 + (23 - 30)
        // = 13.
        let (mut doc, id) = ramped_3x3();
        doc.stroke(id, &[(1.5, 1.5)], 0.5, heal((1, 0))).unwrap();
        assert_eq!(pixel(&doc, id, 1, 1), [54, 0, 0, 255]);
        let (mut doc, id) = ramped_3x3();
        doc.stroke(id, &[(0.5, 0.5)], 0.5, heal((1, 0))).unwrap();
        assert_eq!(pixel(&doc, id, 0, 0), [13, 0, 0, 255]);
    }

    #[test]
    fn healing_brush_over_everything_matches_the_hand_computed_grid() {
        // Sources off the right edge leave the right column alone.
        let (mut doc, id) = ramped_3x3();
        doc.stroke(id, &[(1.0, 1.0)], 3.0, heal((1, 0))).unwrap();
        assert_eq!(
            red_channel_grid(&doc),
            vec![vec![13, 24, 30], vec![43, 54, 60], vec![73, 84, 90]]
        );
        let (mut doc, id) = ramped_3x3();
        doc.stroke(id, &[(1.0, 1.0)], 3.0, heal((-1, 0))).unwrap();
        assert_eq!(
            red_channel_grid(&doc),
            vec![vec![10, 17, 26], vec![40, 47, 56], vec![70, 77, 86]]
        );
    }

    #[test]
    fn healing_brush_blends_by_coverage() {
        // The 0.7929 edge coverage mixes 10 toward the healed 13: 12.4 -> 12.
        let (mut doc, id) = ramped_3x3();
        doc.stroke(id, &[(1.0, 1.0)], 1.0, heal((1, 0))).unwrap();
        assert_eq!(pixel(&doc, id, 0, 0)[0], 12);
    }

    #[test]
    fn healing_brush_keeps_alpha_and_skips_transparent_samples() {
        // depth_ramped_3x3: healing (1, 1) from the transparent (0, 1) paints
        // nothing; healing from the opaque (2, 1) keeps (1, 1)'s alpha 128.
        let (mut doc, id) = depth_ramped_3x3();
        doc.stroke(id, &[(1.5, 1.5)], 0.5, heal((-1, 0))).unwrap();
        assert_eq!(pixel(&doc, id, 1, 1), [50, 0, 0, 128]);
        doc.stroke(id, &[(1.5, 1.5)], 0.5, heal((1, 0))).unwrap();
        assert_eq!(pixel(&doc, id, 1, 1)[3], 128);
        assert_ne!(pixel(&doc, id, 1, 1)[0], 50);
    }

    #[test]
    fn healing_brush_respects_the_selection_and_a_locked_layer() {
        let (mut doc, id) = ramped_3x3();
        doc.select_rectangle(0.0, 0.0, 1.0, 1.0).unwrap();
        doc.stroke(id, &[(1.0, 1.0)], 3.0, heal((1, 0))).unwrap();
        assert_eq!(pixel(&doc, id, 0, 0)[0], 13);
        assert_eq!(pixel(&doc, id, 1, 1)[0], 50);
        doc.set_locked(id, true).unwrap();
        assert!(doc.stroke(id, &[(1.0, 1.0)], 3.0, heal((1, 0))).is_err());
    }

    #[test]
    fn spot_healing_brush_replaces_a_blemish_with_its_surroundings() {
        // A 200 spot on solid 100: the ring two pixels out is all 100.
        let mut pixels = solid(3, 3, [100, 0, 0, 255]);
        pixels[(3 + 1) * 4] = 200;
        let mut doc = Document::new(3, 3).unwrap();
        let id = doc.add_layer("l", &pixels, 3, 3).unwrap();
        doc.stroke(id, &[(1.5, 1.5)], 0.5, Stroke::SpotHeal)
            .unwrap();
        assert_eq!(pixel(&doc, id, 1, 1), [100, 0, 0, 255]);
        assert_eq!(pixel(&doc, id, 0, 0), [100, 0, 0, 255]);
    }

    #[test]
    fn spot_healing_brush_over_everything_matches_the_ring_means() {
        // Edge-clamped ring means of ramped_3x3, sixteen samples each,
        // truncated: [[40, 42, 45], [47, 50, 52], [55, 57, 60]].
        let (mut doc, id) = ramped_3x3();
        doc.stroke(id, &[(1.0, 1.0)], 3.0, Stroke::SpotHeal)
            .unwrap();
        assert_eq!(
            red_channel_grid(&doc),
            vec![vec![40, 42, 45], vec![47, 50, 52], vec![55, 57, 60]]
        );
    }

    #[test]
    fn spot_healing_brush_blends_by_coverage_and_reads_the_snapshot() {
        // The 0.7929 edge coverage mixes 10 toward its ring mean 40: 34.
        let (mut doc, id) = ramped_3x3();
        doc.stroke(id, &[(1.0, 1.0)], 1.0, Stroke::SpotHeal)
            .unwrap();
        assert_eq!(pixel(&doc, id, 0, 0)[0], 34);
        // A corner-to-corner drag equals the one-dot result: every ring is
        // read from the untouched snapshot.
        let (mut doc, id) = ramped_3x3();
        doc.stroke(id, &[(0.0, 0.0), (3.0, 3.0)], 3.0, Stroke::SpotHeal)
            .unwrap();
        assert_eq!(red_channel_grid(&doc)[1], vec![47, 50, 52]);
    }

    #[test]
    fn spot_healing_brush_leaves_alpha_and_transparent_pixels_alone() {
        let (mut doc, id) = depth_ramped_3x3();
        doc.stroke(id, &[(1.0, 1.0)], 3.0, Stroke::SpotHeal)
            .unwrap();
        assert_eq!(pixel(&doc, id, 0, 1), [40, 0, 0, 0]);
        assert_eq!(pixel(&doc, id, 1, 1)[3], 128);
        assert_eq!(pixel(&doc, id, 1, 1)[0], 50);
    }

    #[test]
    fn spot_healing_brush_respects_the_selection_and_a_locked_layer() {
        let (mut doc, id) = ramped_3x3();
        doc.select_rectangle(0.0, 0.0, 1.0, 1.0).unwrap();
        doc.stroke(id, &[(1.0, 1.0)], 3.0, Stroke::SpotHeal)
            .unwrap();
        assert_eq!(pixel(&doc, id, 0, 0)[0], 40);
        assert_eq!(pixel(&doc, id, 1, 1)[0], 50);
        doc.set_locked(id, true).unwrap();
        assert!(doc
            .stroke(id, &[(1.0, 1.0)], 3.0, Stroke::SpotHeal)
            .is_err());
    }

    #[test]
    fn patch_rebuilds_the_selection_from_the_dragged_source_at_its_own_tone() {
        // The centre patched from one pixel right: 60 + (50 - 56) = 54, the
        // Healing Brush's own number; the outline stays put.
        let (mut doc, id) = ramped_3x3();
        doc.select_rectangle(1.0, 1.0, 2.0, 2.0).unwrap();
        let rect = doc.patch(id, 1, 0).unwrap();
        assert_eq!(
            rect,
            Some(Rect {
                x0: 1,
                y0: 1,
                x1: 2,
                y1: 2
            })
        );
        assert_eq!(pixel(&doc, id, 1, 1), [54, 0, 0, 255]);
        assert_eq!(pixel(&doc, id, 2, 1), [60, 0, 0, 255]);
        assert_eq!(doc.selection().unwrap().bounds, rect.unwrap());
    }

    #[test]
    fn patch_replaces_every_selected_pixel_outright() {
        // The left column patched from the middle column: 13, 43, 73.
        let (mut doc, id) = ramped_3x3();
        doc.select_rectangle(0.0, 0.0, 1.0, 3.0).unwrap();
        doc.patch(id, 1, 0).unwrap();
        assert_eq!(
            red_channel_grid(&doc),
            vec![vec![13, 20, 30], vec![43, 50, 60], vec![73, 80, 90]]
        );
    }

    #[test]
    fn patch_skips_sources_off_the_canvas_or_transparent() {
        let (mut doc, id) = ramped_3x3();
        doc.select_rectangle(2.0, 0.0, 3.0, 3.0).unwrap();
        doc.patch(id, 1, 0).unwrap();
        assert_eq!(doc.layers()[0].pixels, ramped_3x3().0.layers()[0].pixels);
        let (mut doc, id) = depth_ramped_3x3();
        doc.select_rectangle(1.0, 1.0, 2.0, 2.0).unwrap();
        doc.patch(id, -1, 0).unwrap();
        assert_eq!(pixel(&doc, id, 1, 1), [50, 0, 0, 128]);
        doc.patch(id, 1, 0).unwrap();
        assert_eq!(pixel(&doc, id, 1, 1)[3], 128);
        assert_ne!(pixel(&doc, id, 1, 1)[0], 50);
    }

    #[test]
    fn patch_reads_the_pre_patch_pixels() {
        // Patching the two left columns from one pixel right: column 1's
        // sources are column 2's ORIGINAL values, column 0's are column
        // 1's original 20/50/80, not the freshly patched ones.
        let (mut doc, id) = ramped_3x3();
        doc.select_rectangle(0.0, 0.0, 2.0, 3.0).unwrap();
        doc.patch(id, 1, 0).unwrap();
        assert_eq!(
            red_channel_grid(&doc),
            vec![vec![13, 24, 30], vec![43, 54, 60], vec![73, 84, 90]]
        );
    }

    #[test]
    fn patch_rejects_no_selection_and_locked_layers_and_ignores_a_zero_drag() {
        let (mut doc, id) = ramped_3x3();
        let err = doc.patch(id, 1, 0).unwrap_err();
        assert!(err.contains("Nothing is selected"), "{err}");
        doc.select_rectangle(1.0, 1.0, 2.0, 2.0).unwrap();
        assert_eq!(doc.patch(id, 0, 0).unwrap(), None);
        assert!(doc.patch(999, 1, 0).is_err());
        doc.set_locked(id, true).unwrap();
        assert!(doc.patch(id, 1, 0).is_err());
        assert_eq!(pixel(&doc, id, 1, 1)[0], 50);
    }

    #[test]
    fn content_aware_move_moves_the_pixels_and_fills_the_hole_from_around_it() {
        // A 200 spot on solid 100 moved one pixel right: the spot lands on
        // (2, 1) and its old place is filled from the all-100 ring.
        let mut pixels = solid(3, 3, [100, 0, 0, 255]);
        pixels[(3 + 1) * 4] = 200;
        let mut doc = Document::new(3, 3).unwrap();
        let id = doc.add_layer("l", &pixels, 3, 3).unwrap();
        doc.select_rectangle(1.0, 1.0, 2.0, 2.0).unwrap();
        doc.content_aware_move(id, 1, 0).unwrap();
        assert_eq!(pixel(&doc, id, 2, 1), [200, 0, 0, 255]);
        assert_eq!(pixel(&doc, id, 1, 1), [100, 0, 0, 255]);
        assert_eq!(
            doc.selection().unwrap().bounds,
            Rect {
                x0: 2,
                y0: 1,
                x1: 3,
                y1: 2
            }
        );
    }

    #[test]
    fn content_aware_move_fills_with_the_ring_means_of_the_pre_move_layer() {
        // The left column moved onto the middle: the middle takes 10 40 70
        // and the vacated column is filled with ramped_3x3's ring means at
        // (0, y): 40, 47, 55.
        let (mut doc, id) = ramped_3x3();
        doc.select_rectangle(0.0, 0.0, 1.0, 3.0).unwrap();
        doc.content_aware_move(id, 1, 0).unwrap();
        assert_eq!(
            red_channel_grid(&doc),
            vec![vec![40, 10, 30], vec![47, 40, 60], vec![55, 70, 90]]
        );
        assert_eq!(pixel(&doc, id, 0, 0)[3], 255);
    }

    #[test]
    fn content_aware_move_leaves_overlapped_and_transparent_pixels_alone() {
        // Moving the two left columns right by one: column 1 is vacated but
        // immediately re-covered by column 0's pixels, so only column 0 is
        // filled. A transparent source pixel stays transparent.
        let (mut doc, id) = ramped_3x3();
        doc.select_rectangle(0.0, 0.0, 2.0, 3.0).unwrap();
        doc.content_aware_move(id, 1, 0).unwrap();
        assert_eq!(red_channel_grid(&doc)[1], vec![47, 40, 50]);
        let (mut doc, id) = depth_ramped_3x3();
        doc.select_rectangle(0.0, 0.0, 1.0, 3.0).unwrap();
        doc.content_aware_move(id, 1, 0).unwrap();
        assert_eq!(pixel(&doc, id, 0, 1), [0, 0, 0, 0]);
        assert_eq!(pixel(&doc, id, 1, 1), [40, 0, 0, 0]);
    }

    #[test]
    fn content_aware_move_off_the_canvas_still_fills_the_hole() {
        let (mut doc, id) = ramped_3x3();
        doc.select_rectangle(2.0, 0.0, 3.0, 3.0).unwrap();
        doc.content_aware_move(id, 1, 0).unwrap();
        assert_eq!(red_channel_grid(&doc)[0], vec![10, 20, 45]);
        assert!(doc.selection().is_none());
    }

    #[test]
    fn content_aware_move_rejects_no_selection_and_locks_and_ignores_zero() {
        let (mut doc, id) = ramped_3x3();
        assert!(doc.content_aware_move(id, 1, 0).is_err());
        doc.select_rectangle(1.0, 1.0, 2.0, 2.0).unwrap();
        assert_eq!(doc.content_aware_move(id, 0, 0).unwrap(), None);
        doc.set_locked(id, true).unwrap();
        assert!(doc.content_aware_move(id, 1, 0).is_err());
        assert_eq!(pixel(&doc, id, 1, 1)[0], 50);
    }

    #[test]
    fn content_aware_fill_replaces_the_selection_with_its_surroundings() {
        let mut pixels = solid(3, 3, [100, 0, 0, 255]);
        pixels[(3 + 1) * 4] = 200;
        let mut doc = Document::new(3, 3).unwrap();
        let id = doc.add_layer("l", &pixels, 3, 3).unwrap();
        doc.select_rectangle(1.0, 1.0, 2.0, 2.0).unwrap();
        let rect = doc.content_aware_fill(id).unwrap();
        assert_eq!(pixel(&doc, id, 1, 1), [100, 0, 0, 255]);
        assert_eq!(
            rect,
            Some(Rect {
                x0: 1,
                y0: 1,
                x1: 2,
                y1: 2
            })
        );
    }

    #[test]
    fn content_aware_fill_of_everything_is_the_ring_mean_grid() {
        let (mut doc, id) = ramped_3x3();
        doc.select_all().unwrap();
        doc.content_aware_fill(id).unwrap();
        assert_eq!(
            red_channel_grid(&doc),
            vec![vec![40, 42, 45], vec![47, 50, 52], vec![55, 57, 60]]
        );
    }

    #[test]
    fn content_aware_fill_reads_the_pre_fill_layer_and_fills_alpha() {
        // Filling the left column: (0, 1)'s ring over depth_ramped_3x3
        // averages red 760/16 = 47 and alpha 1531/16 = 95, from the
        // untouched neighbours even though (0, 0) was filled first.
        let (mut doc, id) = depth_ramped_3x3();
        doc.select_rectangle(0.0, 0.0, 1.0, 3.0).unwrap();
        doc.content_aware_fill(id).unwrap();
        assert_eq!(pixel(&doc, id, 0, 1), [47, 0, 0, 95]);
        assert_eq!(pixel(&doc, id, 1, 1), [50, 0, 0, 128]);
    }

    #[test]
    fn content_aware_fill_honours_the_selections_shape() {
        let (mut doc, id) = ramped_3x3();
        doc.select_rectangle(1.0, 1.0, 2.0, 2.0).unwrap();
        doc.invert_selection().unwrap();
        doc.content_aware_fill(id).unwrap();
        assert_eq!(pixel(&doc, id, 1, 1)[0], 50);
        assert_eq!(pixel(&doc, id, 0, 0)[0], 40);
        assert_eq!(pixel(&doc, id, 2, 2)[0], 60);
    }

    #[test]
    fn content_aware_fill_rejects_no_selection_and_locked_or_unknown_layers() {
        let (mut doc, id) = ramped_3x3();
        let err = doc.content_aware_fill(id).unwrap_err();
        assert!(err.contains("Nothing is selected"), "{err}");
        doc.select_all().unwrap();
        assert!(doc.content_aware_fill(999).is_err());
        doc.set_locked(id, true).unwrap();
        assert!(doc.content_aware_fill(id).is_err());
        assert_eq!(pixel(&doc, id, 0, 0)[0], 10);
    }

    /// Solid 100 with a 200 stripe across the middle row.
    fn striped_3x3() -> (Document, LayerId) {
        let mut pixels = solid(3, 3, [100, 0, 0, 255]);
        for x in 0..3 {
            pixels[(3 + x) * 4] = 200;
        }
        let mut doc = Document::new(3, 3).unwrap();
        let id = doc.add_layer("l", &pixels, 3, 3).unwrap();
        (doc, id)
    }

    #[test]
    fn remove_tool_fills_from_outside_the_brushed_area() {
        // Brushing the whole stripe at radius 0.5 covers exactly the middle
        // row: the ring samples that land on the stripe are excluded, so
        // every stripe pixel becomes the surrounding 100. The Spot Healing
        // Brush, averaging the stripe's own neighbours too, gives 112.
        let (mut doc, id) = striped_3x3();
        doc.stroke(id, &[(0.5, 1.5), (2.5, 1.5)], 0.5, Stroke::Remove)
            .unwrap();
        assert_eq!(red_channel_grid(&doc)[1], vec![100, 100, 100]);
        assert_eq!(red_channel_grid(&doc)[0], vec![100, 100, 100]);
        let (mut doc, id) = striped_3x3();
        doc.stroke(id, &[(0.5, 1.5), (2.5, 1.5)], 0.5, Stroke::SpotHeal)
            .unwrap();
        assert_eq!(red_channel_grid(&doc)[1], vec![112, 112, 112]);
    }

    #[test]
    fn remove_tool_falls_back_to_the_plain_ring_mean_when_everything_is_covered() {
        let (mut doc, id) = ramped_3x3();
        doc.stroke(id, &[(1.0, 1.0)], 3.0, Stroke::Remove).unwrap();
        assert_eq!(
            red_channel_grid(&doc),
            vec![vec![40, 42, 45], vec![47, 50, 52], vec![55, 57, 60]]
        );
    }

    #[test]
    fn remove_tool_blends_by_coverage_over_uncovered_samples() {
        // A radius-1 dot at (1, 1) covers (0,0), (1,0), (0,1), (1,1); the
        // nine uncovered ring samples of (0, 0) average 58, and its 0.7929
        // coverage mixes 10 toward 58: 48.
        let (mut doc, id) = ramped_3x3();
        doc.stroke(id, &[(1.0, 1.0)], 1.0, Stroke::Remove).unwrap();
        assert_eq!(pixel(&doc, id, 0, 0)[0], 48);
    }

    #[test]
    fn remove_tool_leaves_alpha_and_transparent_pixels_alone() {
        let (mut doc, id) = depth_ramped_3x3();
        doc.stroke(id, &[(1.0, 1.0)], 3.0, Stroke::Remove).unwrap();
        assert_eq!(pixel(&doc, id, 0, 1), [40, 0, 0, 0]);
        assert_eq!(pixel(&doc, id, 1, 1)[3], 128);
    }

    #[test]
    fn remove_tool_respects_the_selection_and_a_locked_layer() {
        let (mut doc, id) = striped_3x3();
        doc.select_rectangle(0.0, 0.0, 1.0, 3.0).unwrap();
        doc.stroke(id, &[(0.5, 1.5), (2.5, 1.5)], 0.5, Stroke::Remove)
            .unwrap();
        // Only the selected pixel is covered, so its ring keeps the
        // unselected stripe pixel at (2, 1): 14 × 100 + 200 over 15 = 106.
        assert_eq!(red_channel_grid(&doc)[1], vec![106, 200, 200]);
        doc.set_locked(id, true).unwrap();
        assert!(doc.stroke(id, &[(0.5, 1.5)], 0.5, Stroke::Remove).is_err());
    }

    fn blank_5x5() -> (Document, LayerId) {
        let mut doc = Document::new(5, 5).unwrap();
        let id = doc
            .add_layer("l", &solid(5, 5, [0, 0, 0, 0]), 5, 5)
            .unwrap();
        (doc, id)
    }

    const FILL: [u8; 4] = [0, 255, 0, 255];
    const STROKE: [u8; 4] = [0, 0, 255, 255];

    /// One character per pixel: `.` untouched, `F` fill, `S` stroke.
    fn shape_grid(doc: &Document, id: LayerId) -> Vec<String> {
        (0..doc.height())
            .map(|y| {
                (0..doc.width())
                    .map(|x| match pixel(doc, id, x, y) {
                        p if p == FILL => 'F',
                        p if p == STROKE => 'S',
                        [0, 0, 0, 0] => '.',
                        other => panic!("unexpected pixel {other:?} at ({x}, {y})"),
                    })
                    .collect()
            })
            .collect()
    }

    #[test]
    fn rectangle_tool_fills_the_box_in_either_drag_direction() {
        let mut doc = Document::new(3, 3).unwrap();
        let id = doc
            .add_layer("l", &solid(3, 3, [0, 0, 0, 0]), 3, 3)
            .unwrap();
        let dirty = doc
            .draw_rectangle(id, 2.0, 2.0, 0.0, 0.0, 0, Some(FILL), None)
            .unwrap();
        assert_eq!(
            dirty,
            Some(Rect {
                x0: 0,
                y0: 0,
                x1: 2,
                y1: 2
            })
        );
        assert_eq!(shape_grid(&doc, id), ["FF.", "FF.", "..."]);
    }

    #[test]
    fn rectangle_tool_strokes_a_band_inside_the_edge() {
        let (mut doc, id) = blank_5x5();
        doc.draw_rectangle(id, 0.0, 0.0, 5.0, 5.0, 0, Some(FILL), Some((STROKE, 1)))
            .unwrap();
        assert_eq!(
            shape_grid(&doc, id),
            ["SSSSS", "SFFFS", "SFFFS", "SFFFS", "SSSSS"]
        );
        // A width that swallows the box strokes the whole shape, and a
        // stroke alone leaves the interior untouched.
        let (mut doc, id) = blank_5x5();
        doc.draw_rectangle(id, 0.0, 0.0, 5.0, 5.0, 0, None, Some((STROKE, 3)))
            .unwrap();
        assert_eq!(shape_grid(&doc, id), ["SSSSS"; 5]);
        let (mut doc, id) = blank_5x5();
        doc.draw_rectangle(id, 0.0, 0.0, 5.0, 5.0, 0, None, Some((STROKE, 1)))
            .unwrap();
        assert_eq!(
            shape_grid(&doc, id),
            ["SSSSS", "S...S", "S...S", "S...S", "SSSSS"]
        );
    }

    #[test]
    fn rectangle_tool_rounds_the_corners() {
        let (mut doc, id) = blank_5x5();
        doc.draw_rectangle(id, 0.0, 0.0, 5.0, 5.0, 2, Some(FILL), None)
            .unwrap();
        assert_eq!(
            shape_grid(&doc, id),
            [".FFF.", "FFFFF", "FFFFF", "FFFFF", ".FFF."]
        );
        let (mut doc, id) = blank_5x5();
        doc.draw_rectangle(id, 0.0, 0.0, 5.0, 5.0, 2, Some(FILL), Some((STROKE, 1)))
            .unwrap();
        assert_eq!(
            shape_grid(&doc, id),
            [".SSS.", "SFFFS", "SFFFS", "SFFFS", ".SSS."]
        );
    }

    #[test]
    fn rectangle_tool_respects_the_selection_and_clips_to_the_canvas() {
        let mut doc = Document::new(3, 3).unwrap();
        let id = doc
            .add_layer("l", &solid(3, 3, [0, 0, 0, 0]), 3, 3)
            .unwrap();
        doc.select_rectangle(0.0, 0.0, 1.0, 3.0).unwrap();
        let dirty = doc
            .draw_rectangle(id, -1.0, -1.0, 2.0, 2.0, 0, Some(FILL), None)
            .unwrap();
        assert_eq!(
            dirty,
            Some(Rect {
                x0: 0,
                y0: 0,
                x1: 2,
                y1: 2
            })
        );
        assert_eq!(shape_grid(&doc, id), ["F..", "F..", "..."]);
    }

    #[test]
    fn rectangle_tool_rejects_bad_input() {
        let (mut doc, id) = blank_5x5();
        assert!(doc
            .draw_rectangle(id, 0.0, 0.0, 5.0, 5.0, 0, None, None)
            .is_err());
        assert!(doc
            .draw_rectangle(id, 0.0, 0.0, 5.0, 5.0, 0, Some(FILL), Some((STROKE, 0)))
            .is_err());
        assert!(doc
            .draw_rectangle(id, f32::NAN, 0.0, 5.0, 5.0, 0, Some(FILL), None)
            .is_err());
        assert_eq!(
            doc.draw_rectangle(id, 1.0, 1.0, 1.0, 3.0, 0, Some(FILL), None)
                .unwrap(),
            None
        );
        assert!(doc
            .draw_rectangle(id + 1, 0.0, 0.0, 5.0, 5.0, 0, Some(FILL), None)
            .is_err());
        doc.set_locked(id, true).unwrap();
        assert!(doc
            .draw_rectangle(id, 0.0, 0.0, 5.0, 5.0, 0, Some(FILL), None)
            .is_err());
        assert_eq!(shape_grid(&doc, id), ["....."; 5]);
    }

    #[test]
