        // 94.0, 50 * 0.94 = 47.0 -- all four exact.
        let idx = |x: usize, y: usize| (y * 4 + x) * 4;
        let (mut doc, id) = ink_outlines_cliff_fixture();
        doc.underpainting(id, 8, 0).unwrap();
