        let mut doc = Document::new(1, 1).unwrap();
        let id = doc.add_layer("layer", &[128, 128, 128, 77], 1, 1).unwrap();
        doc.gradient_map(id, [0, 0, 255], [255, 255, 0]).unwrap();
        assert_eq!(pixel(&doc, id, 0, 0)[3], 77);
