    #[test]
    fn iris_blur_keeps_the_centre_sharp_and_blurs_outward() {
        // ramped_3x3's own R-only ramp. Centre (1.0, 1.0) (the grid's
        // own middle pixel), radius 0.0, blur radius 2. The centre
        // pixel (1, 1) sits at distance 0, so blend = 0 and it's left
        // byte-for-byte at its own original 50. Pixel (1, 0) sits a
        // Euclidean distance of 1.0 away, giving blend = 1.0/2 = 0.5,
        // blending its own original 20 halfway with its own radius-2
        // box-blur average, 38, for a real 29. Pixel (0, 0), a diagonal
        // distance of sqrt(2) = 1.41421 away, gives blend = 0.70711,
        // blending its own original 10 with its own average 34 for a
        // real 27; pixel (2, 2), the opposite diagonal corner, blends
        // its own original 90 with its own average 66 for a real 73.
        // All four values hand-computed and cross-checked in Python.
        let idx = |x: usize, y: usize| (y * 3 + x) * 4;
        let (mut doc, id) = ramped_3x3();
        doc.iris_blur(id, 1.0, 1.0, 0.0, 2).unwrap();
        let p = &doc.layers()[0].pixels;
        assert_eq!(p[idx(1, 1)], 50);
        assert_eq!(p[idx(1, 0)], 29);
        assert_eq!(p[idx(0, 0)], 27);
        assert_eq!(p[idx(2, 2)], 73);
    }

    #[test]
    fn iris_blur_radius_widens_the_sharp_zone() {
        // Same centre and blur radius, but radius 2.0 now covers every
        // pixel in the 3x3 grid (the farthest corner sits only sqrt(2)
        // = 1.41421 away, under 2.0), leaving the entire image
        // untouched -- a real, hand-computed difference from the
        // radius-0 test's own blended pixels.
        let (mut doc, id) = ramped_3x3();
        let before = doc.layers()[0].pixels.clone();
        doc.iris_blur(id, 1.0, 1.0, 2.0, 2).unwrap();
        assert_eq!(doc.layers()[0].pixels, before);
    }

    #[test]
    fn iris_blur_is_confined_to_the_selection() {
        let idx = |x: usize, y: usize| (y * 3 + x) * 4;
        let (mut doc, id) = ramped_3x3();
        let before = doc.layers()[0].pixels.clone();
        doc.select_rectangle(0.0, 0.0, 1.0, 1.0).unwrap();
        let dirty = doc.iris_blur(id, 1.0, 1.0, 0.0, 2).unwrap();
        let after = &doc.layers()[0].pixels;
        assert_eq!(after[idx(0, 0)], 27);
        assert_eq!(after[idx(0, 0) + 4..], before[idx(0, 0) + 4..]); // unselected, untouched
        assert_eq!(
            dirty,
            Some(Rect {
                x0: 0,
                y0: 0,
                x1: 1,
                y1: 1
            })
        );
    }

    #[test]
    fn iris_blur_propagates_errors() {
        let (mut doc, id) = doc_with_one_layer();
        assert!(doc.iris_blur(id, 1.0, 1.0, 0.0, 0).is_err());
        assert!(doc.iris_blur(id, f32::NAN, 1.0, 0.0, 2).is_err());
        assert!(doc.iris_blur(id, 1.0, 1.0, -1.0, 2).is_err());
        doc.set_locked(id, true).unwrap();
        assert!(doc.iris_blur(id, 1.0, 1.0, 0.0, 2).is_err());
        assert_eq!(doc.layers()[0].pixels, solid(2, 2, [10, 20, 30, 255]));
        let mut empty = Document::new(2, 2).unwrap();
        assert!(empty.iris_blur(999, 1.0, 1.0, 0.0, 2).is_err());
    }

    #[test]
    fn field_blur_interpolates_radius_by_inverse_distance() {
        // ramped_3x3's own R-only ramp. Pin 1 at (0.0, 0.0) with radius
        // 0 (no blur at all); pin 2 at (2.0, 2.0) with radius 4. Pixel
        // (1, 0) sits distance 1.0 from pin 1 and sqrt(5) = 2.23607
        // from pin 2; weight1 = 1.0, weight2 = 0.44721, interpolated
        // radius = (1.0*0 + 0.44721*4) / 1.44721 = 1.23607, rounding to
        // 1. Its own radius-1 box-blur average is 30. Pixel (2, 1)
        // sits distance 1.0 from pin 2 and sqrt(5) from pin 1;
        // interpolated radius rounds to 3, its own radius-3 average is
        // 52. Pixel (0, 0), exactly at pin 1's own position, uses
        // radius 0 outright (the short-circuit, not the IDW formula),
        // leaving it byte-for-byte at its own original 10. Pixel (2, 2),
        // exactly at pin 2's own position, uses radius 4 outright,
        // giving 58. All four hand-computed and cross-checked in
        // Python.
        let idx = |x: usize, y: usize| (y * 3 + x) * 4;
        let (mut doc, id) = ramped_3x3();
        doc.field_blur(id, 0.0, 0.0, 0, 2.0, 2.0, 4).unwrap();
        let p = &doc.layers()[0].pixels;
        assert_eq!(p[idx(1, 0)], 30);
        assert_eq!(p[idx(2, 1)], 52);
        assert_eq!(p[idx(0, 0)], 10);
        assert_eq!(p[idx(2, 2)], 58);
    }

    #[test]
    fn field_blur_swapping_pin_radii_changes_the_interpolation() {
        // Same two pin positions, but their own radii swapped: pin 1
        // now radius 4, pin 2 now radius 0. Pixel (1, 0), closer to pin
        // 1, now interpolates to radius 3 (not 1), giving a real 41 --
        // and pixel (2, 1), closer to pin 2, now interpolates to radius
        // 1 (not 3), giving a real 56 -- both genuine, hand-computed
        // changes from the first test's own 30 and 52, not a
        // coincidental match.
        let idx = |x: usize, y: usize| (y * 3 + x) * 4;
        let (mut doc, id) = ramped_3x3();
        doc.field_blur(id, 0.0, 0.0, 4, 2.0, 2.0, 0).unwrap();
        let p = &doc.layers()[0].pixels;
        assert_eq!(p[idx(1, 0)], 41);
        assert_eq!(p[idx(2, 1)], 56);
    }

    #[test]
    fn field_blur_is_confined_to_the_selection() {
        let idx = |x: usize, y: usize| (y * 3 + x) * 4;
        let (mut doc, id) = ramped_3x3();
        let before = doc.layers()[0].pixels.clone();
        doc.select_rectangle(1.0, 0.0, 2.0, 1.0).unwrap();
        let dirty = doc.field_blur(id, 0.0, 0.0, 0, 2.0, 2.0, 4).unwrap();
        let after = &doc.layers()[0].pixels;
        assert_eq!(after[idx(1, 0)], 30);
        assert_eq!(after[..idx(1, 0)], before[..idx(1, 0)]); // unselected, untouched
        assert_eq!(after[idx(1, 0) + 4..], before[idx(1, 0) + 4..]); // unselected, untouched
        assert_eq!(
            dirty,
            Some(Rect {
                x0: 1,
                y0: 0,
                x1: 2,
                y1: 1
            })
        );
    }

    #[test]
    fn field_blur_propagates_errors() {
        let (mut doc, id) = doc_with_one_layer();
        assert!(doc.field_blur(id, f32::NAN, 0.0, 0, 2.0, 2.0, 4).is_err());
        doc.set_locked(id, true).unwrap();
        assert!(doc.field_blur(id, 0.0, 0.0, 0, 2.0, 2.0, 4).is_err());
        assert_eq!(doc.layers()[0].pixels, solid(2, 2, [10, 20, 30, 255]));
        let mut empty = Document::new(2, 2).unwrap();
        assert!(empty.field_blur(999, 0.0, 0.0, 0, 2.0, 2.0, 4).is_err());
    }

    #[test]
    fn spin_blur_rotates_each_sample_around_the_centre() {
        // ramped_3x3's own R-only ramp. Centre (1.0, 1.0), angle 90
        // (half-angle 45 either way). Pixel (row 0, col 2): its own
        // offset from centre is (1, -1). Rotating by -45 degrees lands
        // the sample at (1, 0) (value 20); by 0 degrees at the pixel's
        // own position, (2, 0) (value 30, itself); by +45 degrees at
        // (2, 1) (value 60). Average (20+30+60)/3 = 36.67, rounds to
        // 37 -- a real, hand-computed change from the pixel's own
        // original 30.
        let idx = |x: usize, y: usize| (y * 3 + x) * 4;
        let (mut doc, id) = ramped_3x3();
        doc.spin_blur(id, 1.0, 1.0, 90.0).unwrap();
        let p = &doc.layers()[0].pixels;
        assert_eq!(p[idx(2, 0)], 37);
    }

    #[test]
    fn spin_blur_angle_scales_the_rotation() {
        // Same pixel and centre, but angle 180 (half-angle 90) rotates
        // further: a real, hand-computed 43 -- a genuine change from
        // the angle-90 test's own 37, not a coincidental match.
        let idx = |x: usize, y: usize| (y * 3 + x) * 4;
        let (mut doc, id) = ramped_3x3();
        doc.spin_blur(id, 1.0, 1.0, 180.0).unwrap();
        let p = &doc.layers()[0].pixels;
        assert_eq!(p[idx(2, 0)], 43);
    }

    #[test]
    fn spin_blur_angle_zero_is_the_identity() {
        let (mut doc, id) = ramped_3x3();
        let before = doc.layers()[0].pixels.clone();
        doc.spin_blur(id, 1.0, 1.0, 0.0).unwrap();
        assert_eq!(doc.layers()[0].pixels, before);
    }

    #[test]
    fn spin_blur_leaves_the_centre_pixel_untouched() {
        // The centre pixel's own zero-length offset from itself stays
        // zero under any rotation, so it's left completely unchanged
        // regardless of angle.
        let idx = |x: usize, y: usize| (y * 3 + x) * 4;
        let (mut doc, id) = ramped_3x3();
        doc.spin_blur(id, 1.0, 1.0, 180.0).unwrap();
        let p = &doc.layers()[0].pixels;
        assert_eq!(p[idx(1, 1)], 50);
    }

    #[test]
    fn spin_blur_is_confined_to_the_selection() {
        let idx = |x: usize, y: usize| (y * 3 + x) * 4;
        let (mut doc, id) = ramped_3x3();
        let before = doc.layers()[0].pixels.clone();
        doc.select_rectangle(2.0, 0.0, 3.0, 1.0).unwrap();
        let dirty = doc.spin_blur(id, 1.0, 1.0, 90.0).unwrap();
        let after = &doc.layers()[0].pixels;
        assert_eq!(after[idx(2, 0)], 37);
        assert_eq!(after[..idx(2, 0)], before[..idx(2, 0)]); // unselected, untouched
        assert_eq!(
            dirty,
            Some(Rect {
                x0: 2,
                y0: 0,
                x1: 3,
                y1: 1
            })
        );
    }

    #[test]
    fn spin_blur_propagates_errors() {
        let (mut doc, id) = doc_with_one_layer();
        assert!(doc.spin_blur(id, f32::NAN, 1.0, 90.0).is_err());
        assert!(doc.spin_blur(id, 1.0, 1.0, -1.0).is_err());
        assert!(doc.spin_blur(id, 1.0, 1.0, 361.0).is_err());
        doc.set_locked(id, true).unwrap();
        assert!(doc.spin_blur(id, 1.0, 1.0, 90.0).is_err());
        assert_eq!(doc.layers()[0].pixels, solid(2, 2, [10, 20, 30, 255]));
        let mut empty = Document::new(2, 2).unwrap();
        assert!(empty.spin_blur(999, 1.0, 1.0, 90.0).is_err());
    }

    /// `ramped_3x3`'s own R-only ramp, but with alpha standing in for a
    /// depth map: column 0 fully near (`0`), column 1 halfway (`128`),
    /// column 2 fully far (`255`).
    fn depth_ramped_3x3() -> (Document, LayerId) {
        let mut doc = Document::new(3, 3).unwrap();
        #[rustfmt::skip]
        let pixels = [
            10, 0, 0, 0,  20, 0, 0, 128,  30, 0, 0, 255,
            40, 0, 0, 0,  50, 0, 0, 128,  60, 0, 0, 255,
            70, 0, 0, 0,  80, 0, 0, 128,  90, 0, 0, 255,
        ];
        let id = doc.add_layer("base", &pixels, 3, 3).unwrap();
        (doc, id)
    }

    #[test]
    fn lens_blur_scales_each_pixels_radius_by_its_own_alpha() {
        // Pixel (col 2, row 1), alpha 255, max radius 4: depth 255/255 * 4
        // rounds to radius 4, whose edge-clamped 9x9 window over this 3x3
        // grid averages (truncating) to 52 -- a real change from its own
        // original 60.
        let idx = |x: usize, y: usize| (y * 3 + x) * 4;
        let (mut doc, id) = depth_ramped_3x3();
        doc.lens_blur(id, 4, false).unwrap();
        let p = &doc.layers()[0].pixels;
        assert_eq!(p[idx(2, 1)], 52);
        // Alpha is the depth map: it must survive byte-for-byte.
        assert_eq!(p[idx(2, 1) + 3], 255);
        assert_eq!(p[idx(1, 1) + 3], 128);
        assert_eq!(p[idx(0, 1) + 3], 0);
    }

    #[test]
    fn lens_blur_max_radius_scales_the_per_pixel_radius() {
        // Pixel (col 1, row 0), alpha 128. Max radius 1: 128/255 * 1 =
        // 0.50196 rounds to radius 1, whose window averages to 30. Max
        // radius 4: 128/255 * 4 = 2.0078 rounds to radius 2, whose window
        // averages to 38 -- two distinct, hand-computed values from the
        // same original 20, so the radius genuinely depends on max_radius.
        let idx = |x: usize, y: usize| (y * 3 + x) * 4;
        let (mut doc, id) = depth_ramped_3x3();
        doc.lens_blur(id, 1, false).unwrap();
        assert_eq!(doc.layers()[0].pixels[idx(1, 0)], 30);
        let (mut doc, id) = depth_ramped_3x3();
        doc.lens_blur(id, 4, false).unwrap();
        assert_eq!(doc.layers()[0].pixels[idx(1, 0)], 38);
    }

    #[test]
    fn lens_blur_leaves_fully_near_pixels_untouched() {
        // Alpha 0 is depth 0, radius 0 at any max radius: the identity.
        let idx = |x: usize, y: usize| (y * 3 + x) * 4;
        let (mut doc, id) = depth_ramped_3x3();
        doc.lens_blur(id, 4, false).unwrap();
        let p = &doc.layers()[0].pixels;
        assert_eq!(p[idx(0, 0)], 10);
        assert_eq!(p[idx(0, 1)], 40);
        assert_eq!(p[idx(0, 2)], 70);
    }

    #[test]
    fn lens_blur_invert_swaps_which_depth_is_sharp() {
        // Inverted, alpha 0 becomes depth 255 (radius 4): pixel (col 0,
        // row 1) now blurs from 40 to a hand-computed 47, while alpha 255
        // becomes depth 0 (radius 0): pixel (col 2, row 1) stays exactly 60.
        let idx = |x: usize, y: usize| (y * 3 + x) * 4;
        let (mut doc, id) = depth_ramped_3x3();
        doc.lens_blur(id, 4, true).unwrap();
        let p = &doc.layers()[0].pixels;
        assert_eq!(p[idx(0, 1)], 47);
        assert_eq!(p[idx(2, 1)], 60);
    }

    #[test]
    fn lens_blur_is_confined_to_the_selection() {
        let idx = |x: usize, y: usize| (y * 3 + x) * 4;
        let (mut doc, id) = depth_ramped_3x3();
        let before = doc.layers()[0].pixels.clone();
        doc.select_rectangle(2.0, 1.0, 3.0, 2.0).unwrap();
        let dirty = doc.lens_blur(id, 4, false).unwrap();
        let after = &doc.layers()[0].pixels;
        assert_eq!(after[idx(2, 1)], 52);
        assert_eq!(after[..idx(2, 1)], before[..idx(2, 1)]); // unselected, untouched
        assert_eq!(after[idx(2, 1) + 4..], before[idx(2, 1) + 4..]);
        assert_eq!(
            dirty,
            Some(Rect {
                x0: 2,
                y0: 1,
                x1: 3,
                y1: 2
            })
        );
    }

