        let (doc, id) = depth_ramped_3x3();
        assert_eq!(doc.layer_pixel(id, 0, 1).unwrap(), [40, 0, 0, 0]);
        assert_eq!(doc.layer_pixel(id, 1, 1).unwrap(), [50, 0, 0, 128]);
