    #[test]
    fn similar_compares_alpha_like_the_magic_wand() {
        // depth_ramped_3x3's centre is (50, alpha 128); its row neighbours
        // 40 and 60 sit at alpha 0 and 255, far outside 118..=138.
        let (mut doc, id) = depth_ramped_3x3();
        doc.select_rectangle(1.0, 1.0, 2.0, 2.0).unwrap();
        doc.select_similar(id, 10).unwrap();
        assert_eq!(
            selected_grid(&doc),
            vec![
                vec![false, false, false],
                vec![false, true, false],
                vec![false, false, false]
            ]
        );
    }

    #[test]
    fn similar_requires_a_selection_and_a_known_layer() {
        let (mut doc, id) = ramped_3x3();
        let err = doc.select_similar(id, 10).unwrap_err();
        assert!(err.contains("Nothing is selected"), "{err}");
        doc.select_rectangle(1.0, 1.0, 2.0, 2.0).unwrap();
        assert!(doc.select_similar(999, 10).is_err());
        assert_eq!(doc.selection().unwrap().shape, SelectionShape::Rectangle);
    }

    fn alpha_grid(doc: &Document, id: LayerId) -> Vec<Vec<u8>> {
        (0..3)
            .map(|y| (0..3).map(|x| pixel(doc, id, x, y)[3]).collect())
            .collect()
    }

    #[test]
    fn magic_eraser_clears_the_wands_region() {
        // The same region the wand selects from (0, 0) at tolerance 15 --
        // (0, 0) and (1, 0) -- goes fully transparent; colour bytes stay.
        let (mut doc, id) = ramped_3x3();
        let rect = doc.magic_erase(id, 0, 0, 15, true, 255).unwrap();
        assert_eq!(
            rect,
            Some(Rect {
                x0: 0,
                y0: 0,
                x1: 2,
                y1: 1
            })
        );
        assert_eq!(
            alpha_grid(&doc, id),
            vec![vec![0, 0, 255], vec![255, 255, 255], vec![255, 255, 255]]
        );
        assert_eq!(pixel(&doc, id, 0, 0), [10, 0, 0, 0]);
        assert_eq!(pixel(&doc, id, 1, 0), [20, 0, 0, 0]);
    }

    #[test]
    fn magic_eraser_opacity_scales_alpha_toward_zero() {
        // 255 * (1 - 128/255) = 127.0 exactly in f32, and 128 * (1 - 64/255)
        // = 95.87 -> 96, the same multiply the Eraser stroke applies.
        let (mut doc, id) = ramped_3x3();
        doc.magic_erase(id, 1, 1, 0, true, 128).unwrap();
        assert_eq!(pixel(&doc, id, 1, 1)[3], 127);
        let (mut doc, id) = depth_ramped_3x3();
        doc.magic_erase(id, 1, 1, 0, true, 64).unwrap();
        assert_eq!(pixel(&doc, id, 1, 1)[3], 96);
    }

    #[test]
    fn magic_eraser_non_contiguous_reaches_across_the_layer() {
        let row = [10, 0, 0, 255, 50, 0, 0, 255, 10, 0, 0, 255];
        let mut doc = Document::new(3, 1).unwrap();
        let id = doc.add_layer("row", &row, 3, 1).unwrap();
        doc.magic_erase(id, 0, 0, 0, true, 255).unwrap();
        assert_eq!(doc.layers()[0].pixels[3], 0);
        assert_eq!(doc.layers()[0].pixels[11], 255);
        let mut doc = Document::new(3, 1).unwrap();
        let id = doc.add_layer("row", &row, 3, 1).unwrap();
        let rect = doc.magic_erase(id, 0, 0, 0, false, 255).unwrap();
        let p = &doc.layers()[0].pixels;
        assert_eq!([p[3], p[7], p[11]], [0, 255, 0]);
        assert_eq!(
            rect,
            Some(Rect {
                x0: 0,
                y0: 0,
                x1: 3,
                y1: 1
            })
        );
    }

    #[test]
    fn magic_eraser_is_confined_to_the_selection() {
        // Tolerance 25 from (0, 0) reaches the whole top row, but only the
        // selected (0, 0) and (1, 0) are erased; a click on the unselected
        // (2, 0) erases nothing and reports None.
        let (mut doc, id) = ramped_3x3();
        doc.select_rectangle(0.0, 0.0, 2.0, 1.0).unwrap();
        let rect = doc.magic_erase(id, 0, 0, 25, true, 255).unwrap();
        assert_eq!(
            rect,
            Some(Rect {
                x0: 0,
                y0: 0,
                x1: 2,
                y1: 1
            })
        );
        assert_eq!(alpha_grid(&doc, id)[0], vec![0, 0, 255]);
        assert_eq!(doc.magic_erase(id, 2, 0, 25, true, 255).unwrap(), None);
        assert_eq!(alpha_grid(&doc, id)[0], vec![0, 0, 255]);
    }

    #[test]
    fn magic_eraser_rejects_locked_unknown_and_off_canvas() {
        let (mut doc, id) = ramped_3x3();
        assert!(doc.magic_erase(id, 3, 0, 0, true, 255).is_err());
        assert!(doc.magic_erase(999, 0, 0, 0, true, 255).is_err());
        doc.set_locked(id, true).unwrap();
        let err = doc.magic_erase(id, 0, 0, 0, true, 255).unwrap_err();
        assert!(err.contains("locked"), "{err}");
        assert_eq!(pixel(&doc, id, 0, 0)[3], 255);
    }

    /// A 3x3 "eye": a plus of red-eye pixels (200, 40, 40) on skin
    /// (220, 180, 160), whose red exceeds its green by only 40.
    fn red_eye_3x3() -> (Document, LayerId) {
        let skin = [220, 180, 160, 255];
        let eye = [200, 40, 40, 255];
        let mut pixels = Vec::new();
        for (x, y) in (0..3).flat_map(|y| (0..3).map(move |x| (x, y))) {
            pixels.extend(if x == 1 || y == 1 { eye } else { skin });
        }
        let mut doc = Document::new(3, 3).unwrap();
        let id = doc.add_layer("eye", &pixels, 3, 3).unwrap();
        (doc, id)
    }

    #[test]
    fn red_eye_neutralises_the_red_dominant_region() {
        // Red becomes the mean of green and blue (40), then everything is
        // darkened by half: (20, 20, 20). Skin is left alone.
        let (mut doc, id) = red_eye_3x3();
        let rect = doc.red_eye(id, 1, 1, 50).unwrap();
        assert_eq!(
            rect,
            Some(Rect {
                x0: 0,
                y0: 0,
                x1: 3,
                y1: 3
            })
        );
        for (x, y) in [(1, 0), (0, 1), (1, 1), (2, 1), (1, 2)] {
            assert_eq!(pixel(&doc, id, x, y), [20, 20, 20, 255], "({x}, {y})");
        }
        for (x, y) in [(0, 0), (2, 0), (0, 2), (2, 2)] {
            assert_eq!(pixel(&doc, id, x, y), [220, 180, 160, 255], "({x}, {y})");
        }
    }

    #[test]
    fn red_eye_darken_amount_scales_the_result() {
        let (mut doc, id) = red_eye_3x3();
        doc.red_eye(id, 1, 1, 0).unwrap();
        assert_eq!(pixel(&doc, id, 1, 1), [40, 40, 40, 255]);
        let (mut doc, id) = red_eye_3x3();
        doc.red_eye(id, 1, 1, 100).unwrap();
        assert_eq!(pixel(&doc, id, 1, 1), [0, 0, 0, 255]);
        // An uneven pupil (180, 20, 60): grey 40, then halved -> (20, 10, 30).
        let mut doc = Document::new(1, 1).unwrap();
        let id = doc.add_layer("px", &[180, 20, 60, 128], 1, 1).unwrap();
        doc.red_eye(id, 0, 0, 50).unwrap();
        assert_eq!(pixel(&doc, id, 0, 0), [20, 10, 30, 128]);
    }

    #[test]
    fn red_eye_reaches_only_the_contiguous_region() {
        // Only the centre and the corner are red; they share no edge, so a
        // click on the centre leaves the corner alone.
        let mut pixels = solid(3, 3, [220, 180, 160, 255]);
        pixels[..4].copy_from_slice(&[200, 40, 40, 255]);
        pixels[16..20].copy_from_slice(&[200, 40, 40, 255]);
        let mut doc = Document::new(3, 3).unwrap();
        let id = doc.add_layer("eye", &pixels, 3, 3).unwrap();
        let rect = doc.red_eye(id, 1, 1, 50).unwrap();
        assert_eq!(
            rect,
            Some(Rect {
                x0: 1,
                y0: 1,
                x1: 2,
                y1: 2
            })
        );
        assert_eq!(pixel(&doc, id, 0, 0), [200, 40, 40, 255]);
        assert_eq!(pixel(&doc, id, 1, 1), [20, 20, 20, 255]);
    }

    #[test]
    fn red_eye_rejects_a_click_that_is_not_red_and_respects_the_selection() {
        let (mut doc, id) = red_eye_3x3();
        let err = doc.red_eye(id, 0, 0, 50).unwrap_err();
        assert!(err.contains("red"), "{err}");
        doc.select_rectangle(0.0, 0.0, 3.0, 2.0).unwrap();
        let rect = doc.red_eye(id, 1, 1, 50).unwrap();
        assert_eq!(
            rect,
            Some(Rect {
                x0: 0,
                y0: 0,
                x1: 3,
                y1: 2
            })
        );
        assert_eq!(pixel(&doc, id, 1, 1), [20, 20, 20, 255]);
        assert_eq!(pixel(&doc, id, 1, 2), [200, 40, 40, 255]);
        doc.select_rectangle(0.0, 0.0, 1.0, 1.0).unwrap();
        assert_eq!(doc.red_eye(id, 1, 2, 50).unwrap(), None);
        assert_eq!(pixel(&doc, id, 1, 2), [200, 40, 40, 255]);
    }

    #[test]
    fn red_eye_rejects_bad_input() {
        let (mut doc, id) = red_eye_3x3();
        assert!(doc.red_eye(id, 3, 1, 50).is_err());
        assert!(doc.red_eye(999, 1, 1, 50).is_err());
        assert!(doc.red_eye(id, 1, 1, 101).is_err());
        doc.set_locked(id, true).unwrap();
        assert!(doc.red_eye(id, 1, 1, 50).is_err());
        assert_eq!(pixel(&doc, id, 1, 1), [200, 40, 40, 255]);
    }

    fn assert_measurement(m: Measurement, width: f32, height: f32, distance: f32, angle: f32) {
        assert_eq!((m.width, m.height), (width, height));
        assert!(
            (m.distance - distance).abs() < 1e-4,
            "distance {}",
            m.distance
        );
        assert!((m.angle - angle).abs() < 1e-3, "angle {}", m.angle);
    }

    #[test]
    fn ruler_measures_a_3_4_5_triangle() {
        // Down and to the right on screen is a negative angle.
        assert_measurement(
            measure(0.0, 0.0, 3.0, 4.0).unwrap(),
            3.0,
            4.0,
            5.0,
            -53.1301,
        );
    }

    #[test]
    fn ruler_angle_follows_the_drag_direction() {
        // The same segment dragged the other way points up and left.
        assert_measurement(
            measure(3.0, 4.0, 0.0, 0.0).unwrap(),
            3.0,
            4.0,
            5.0,
            126.8699,
        );
        assert_measurement(
            measure(0.0, 0.0, -1.0, 1.0).unwrap(),
            1.0,
            1.0,
            std::f32::consts::SQRT_2,
            -135.0,
        );
    }

    #[test]
    fn ruler_axis_aligned_drags_read_0_90_and_180() {
        assert_measurement(measure(0.0, 0.0, 5.0, 0.0).unwrap(), 5.0, 0.0, 5.0, 0.0);
        assert_measurement(measure(0.0, 0.0, 0.0, -2.0).unwrap(), 0.0, 2.0, 2.0, 90.0);
        assert_measurement(measure(3.0, 0.0, 0.0, 0.0).unwrap(), 3.0, 0.0, 3.0, 180.0);
    }

    #[test]
    fn ruler_zero_length_drag_reads_zero() {
        assert_measurement(measure(1.5, 1.5, 1.5, 1.5).unwrap(), 0.0, 0.0, 0.0, 0.0);
    }

    #[test]
    fn ruler_rejects_non_finite_points() {
        assert!(measure(f32::NAN, 0.0, 1.0, 1.0).is_err());
        assert!(measure(0.0, 0.0, f32::INFINITY, 1.0).is_err());
    }

    #[test]
    fn color_samplers_read_the_composite_in_order() {
        // The opaque 200 overlay covers the base's 10 at (0, 0); (1, 1)
        // shows the base's 50 through the overlay's transparency.
        let (doc, _) = ramped_3x3_with_overlay([200, 0, 0, 255]);
        let samples = doc.sample_points(&[(1, 1), (0, 0), (2, 2)]).unwrap();
        assert_eq!(
            samples,
            vec![[50, 0, 0, 255], [200, 0, 0, 255], [90, 0, 0, 255]]
        );
        assert!(doc.sample_points(&[]).unwrap().is_empty());
    }

    #[test]
    fn color_samplers_see_opacity_and_visibility() {
        // 50% red over the base's 10 is 133, the value Copy Merged's test
        // established; hiding the overlay reads the base's 10.
        let (mut doc, over) = ramped_3x3_with_overlay([255, 0, 0, 255]);
        doc.set_opacity(over, 0.5).unwrap();
        assert_eq!(
            doc.sample_points(&[(0, 0)]).unwrap(),
            vec![[133, 0, 0, 255]]
        );
        doc.set_visible(over, false).unwrap();
        assert_eq!(doc.sample_points(&[(0, 0)]).unwrap(), vec![[10, 0, 0, 255]]);
    }

    #[test]
    fn color_samplers_read_transparency_as_zero() {
        let (doc, _) = depth_ramped_3x3();
        let samples = doc.sample_points(&[(0, 1), (1, 1)]).unwrap();
        assert_eq!(samples, vec![[0, 0, 0, 0], [50, 0, 0, 128]]);
    }

    #[test]
    fn color_samplers_match_the_flattened_image() {
        let (doc, _) = ramped_3x3_with_overlay([200, 0, 0, 128]);
        let flat = crate::composite::flatten(&doc).pixels;
        let points: Vec<(u32, u32)> = (0..3).flat_map(|y| (0..3).map(move |x| (x, y))).collect();
        let sampled: Vec<u8> = doc
            .sample_points(&points)
            .unwrap()
            .into_iter()
            .flatten()
            .collect();
        assert_eq!(sampled, flat);
    }

    #[test]
    fn color_samplers_reject_off_canvas_points_and_more_than_ten() {
        let (doc, _) = ramped_3x3();
        assert!(doc.sample_points(&[(0, 0), (3, 0)]).is_err());
        let eleven = vec![(0, 0); 11];
        let err = doc.sample_points(&eleven).unwrap_err();
        assert!(err.contains("ten"), "{err}");
        assert!(doc.sample_points(&eleven[..10]).is_ok());
    }

    #[test]
    fn count_marks_number_in_placement_order() {
        let (mut doc, _) = ramped_3x3();
        assert_eq!(doc.add_count_mark(2, 0).unwrap(), 1);
        assert_eq!(doc.add_count_mark(0, 2).unwrap(), 2);
        assert_eq!(doc.add_count_mark(2, 0).unwrap(), 3);
        assert_eq!(doc.count_marks(), &[(2, 0), (0, 2), (2, 0)]);
        assert_eq!(doc.view().count_marks, vec![(2, 0), (0, 2), (2, 0)]);
    }

    #[test]
    fn count_marks_clear() {
        let (mut doc, _) = ramped_3x3();
        doc.add_count_mark(1, 1).unwrap();
        doc.clear_count_marks();
        assert!(doc.count_marks().is_empty());
        assert!(doc.view().count_marks.is_empty());
        assert_eq!(doc.add_count_mark(1, 1).unwrap(), 1);
    }

    #[test]
    fn count_marks_reject_off_canvas_points() {
        let (mut doc, _) = ramped_3x3();
        assert!(doc.add_count_mark(3, 0).is_err());
        assert!(doc.add_count_mark(0, 3).is_err());
        assert!(doc.count_marks().is_empty());
        assert_eq!(doc.add_count_mark(2, 2).unwrap(), 1);
    }

    #[test]
    fn count_marks_survive_pixel_edits_but_not_a_canvas_resize() {
        let (mut doc, id) = ramped_3x3();
        doc.add_count_mark(1, 1).unwrap();
        doc.invert_colors(id).unwrap();
        doc.select_rectangle(0.0, 0.0, 1.0, 1.0).unwrap();
        assert_eq!(doc.count_marks().len(), 1);
        doc.rotate_document_90(true);
        assert!(doc.count_marks().is_empty());
        doc.add_count_mark(0, 0).unwrap();
        doc.crop(Rect {
            x0: 0,
            y0: 0,
            x1: 2,
            y1: 2,
        })
        .unwrap();
        assert!(doc.count_marks().is_empty());
    }

    #[test]
    fn a_new_document_has_no_count_marks() {
        let doc = Document::new(2, 2).unwrap();
        assert!(doc.count_marks().is_empty());
        assert!(doc.view().count_marks.is_empty());
    }

    fn note(x: u32, y: u32, text: &str) -> Note {
        Note {
            x,
            y,
            text: text.to_string(),
        }
    }

    #[test]
    fn notes_are_pinned_in_placement_order_with_trimmed_text() {
        let (mut doc, _) = ramped_3x3();
        assert_eq!(doc.add_note(2, 0, "  first ").unwrap(), 0);
        assert_eq!(doc.add_note(0, 2, "second").unwrap(), 1);
        assert_eq!(doc.notes(), &[note(2, 0, "first"), note(0, 2, "second")]);
        assert_eq!(doc.view().notes, doc.notes().to_vec());
    }

    #[test]
    fn notes_can_be_rewritten_and_removed() {
        let (mut doc, _) = ramped_3x3();
        doc.add_note(0, 0, "a").unwrap();
        doc.add_note(1, 1, "b").unwrap();
        doc.add_note(2, 2, "c").unwrap();
        doc.set_note_text(1, " bee ").unwrap();
        assert_eq!(doc.notes()[1], note(1, 1, "bee"));
        doc.remove_note(0).unwrap();
        assert_eq!(doc.notes(), &[note(1, 1, "bee"), note(2, 2, "c")]);
        doc.clear_notes();
        assert!(doc.notes().is_empty());
    }

    #[test]
    fn notes_reject_blank_text() {
        let (mut doc, _) = ramped_3x3();
        let err = doc.add_note(0, 0, "   ").unwrap_err();
        assert!(err.contains("text"), "{err}");
        assert!(doc.notes().is_empty());
        doc.add_note(0, 0, "kept").unwrap();
        assert!(doc.set_note_text(0, "").is_err());
        assert_eq!(doc.notes()[0].text, "kept");
    }

    #[test]
    fn notes_reject_off_canvas_points_and_unknown_indices() {
        let (mut doc, _) = ramped_3x3();
        assert!(doc.add_note(3, 0, "x").is_err());
        assert!(doc.add_note(0, 3, "x").is_err());
        let err = doc.set_note_text(0, "x").unwrap_err();
        assert!(err.contains("#1"), "{err}");
        assert!(doc.remove_note(0).is_err());
        assert!(doc.notes().is_empty());
    }

    #[test]
    fn notes_survive_pixel_edits_but_not_a_canvas_resize() {
        let (mut doc, id) = ramped_3x3();
        doc.add_note(1, 1, "keep").unwrap();
        doc.invert_colors(id).unwrap();
        assert_eq!(doc.notes().len(), 1);
        doc.rotate_document_90(true);
        assert!(doc.notes().is_empty());
        doc.add_note(0, 0, "again").unwrap();
        doc.crop(Rect {
            x0: 0,
            y0: 0,
            x1: 2,
            y1: 2,
        })
        .unwrap();
        assert!(doc.view().notes.is_empty());
    }

    #[test]
    fn a_layer_comp_restores_visibility_opacity_and_blend_mode() {
        let (mut doc, over) = ramped_3x3_with_overlay([200, 0, 0, 255]);
        let base = doc.layers()[0].id;
        doc.save_layer_comp("day").unwrap();
        assert_eq!(doc.view().layer_comps, vec!["day".to_string()]);
        doc.set_visible(over, false).unwrap();
        doc.set_opacity(over, 0.5).unwrap();
        doc.set_blend_mode(over, BlendMode::Multiply).unwrap();
        doc.apply_layer_comp("day").unwrap();
        let layer = doc.layer(over).unwrap();
        assert!(layer.visible);
        assert_eq!(layer.opacity, 1.0);
        assert_eq!(layer.blend_mode, BlendMode::Normal);
        let base_layer = doc.layer(base).unwrap();
        assert!(base_layer.visible && base_layer.opacity == 1.0);
    }

    #[test]
    fn saving_a_layer_comp_under_an_existing_name_replaces_it_in_place() {
        let (mut doc, over) = ramped_3x3_with_overlay([200, 0, 0, 255]);
        doc.save_layer_comp("a").unwrap();
        doc.save_layer_comp("b").unwrap();
        doc.set_visible(over, false).unwrap();
        doc.save_layer_comp(" a ").unwrap();
        assert_eq!(doc.layer_comp_names(), vec!["a", "b"]);
        doc.set_visible(over, true).unwrap();
        doc.apply_layer_comp("a").unwrap();
        assert!(!doc.layer(over).unwrap().visible);
        doc.delete_layer_comp("a").unwrap();
        assert_eq!(doc.layer_comp_names(), vec!["b"]);
    }

    #[test]
    fn a_layer_comp_skips_deleted_layers_and_leaves_new_ones_alone() {
        let (mut doc, over) = ramped_3x3_with_overlay([200, 0, 0, 255]);
        let base = doc.layers()[0].id;
        doc.save_layer_comp("both").unwrap();
        doc.remove_layer(over).unwrap();
        let added = doc
            .add_layer("new", &solid(3, 3, [0, 0, 0, 0]), 3, 3)
            .unwrap();
        doc.set_visible(added, false).unwrap();
        doc.set_visible(base, false).unwrap();
        doc.apply_layer_comp("both").unwrap();
        assert!(doc.layer(base).unwrap().visible);
        assert!(!doc.layer(added).unwrap().visible);
    }

    #[test]
    fn layer_comps_reject_blank_and_unknown_names() {
        let (mut doc, _) = ramped_3x3();
        let err = doc.save_layer_comp("  ").unwrap_err();
        assert!(err.contains("name"), "{err}");
        let err = doc.apply_layer_comp("missing").unwrap_err();
        assert!(err.contains("missing"), "{err}");
        let err = doc.delete_layer_comp("missing").unwrap_err();
        assert!(err.contains("missing"), "{err}");
        assert!(doc.layer_comp_names().is_empty());
    }

    #[test]
    fn layer_comps_survive_a_canvas_resize() {
        let (mut doc, over) = ramped_3x3_with_overlay([200, 0, 0, 255]);
        doc.save_layer_comp("keep").unwrap();
        doc.set_visible(over, false).unwrap();
        doc.rotate_document_90(true);
        assert_eq!(doc.view().layer_comps, vec!["keep".to_string()]);
        doc.apply_layer_comp("keep").unwrap();
        assert!(doc.layer(over).unwrap().visible);
    }

    #[test]
    fn a_new_document_has_no_selection() {
        let doc = Document::new(4, 4).unwrap();
        assert_eq!(doc.selection(), None);
    }

    #[test]
    fn selecting_a_rectangle_clamps_to_the_document_and_sorts_corners() {
        let mut doc = Document::new(10, 10).unwrap();
        // Drag from bottom-right to top-left, past both edges.
        doc.select_rectangle(-5.0, -5.0, 6.0, 6.0).unwrap();
        assert_eq!(
            doc.selection(),
            Some(Selection {
                shape: SelectionShape::Rectangle,
                bounds: Rect {
                    x0: 0,
                    y0: 0,
                    x1: 6,
                    y1: 6
                },
                inverted: false,
                border: None,
                feather: 0,
                anti_alias: false,
                contrast: 0,
                shift_edge: 0,
                mask: None,
            })
        );
    }

    #[test]
    fn a_zero_area_selection_is_rejected() {
        let mut doc = Document::new(10, 10).unwrap();
        assert!(doc.select_rectangle(3.0, 3.0, 3.0, 3.0).is_err());
        assert!(doc.select_ellipse(3.0, 3.0, 3.0, 8.0).is_err()); // zero width
    }

