    #[test]
    fn apply_image_preview_matches_a_real_apply_and_does_not_mutate_the_document() {
        let (doc, base, target) = apply_image_fixture();
        let before = doc.view();
        let preview = doc
            .apply_image_preview(
                target,
                Some(base),
                ApplyChannel::Rgb,
                ApplyBlend::Mode {
                    mode: BlendMode::Multiply,
                },
                None,
                100,
                false,
                false,
            )
            .unwrap();
        // The document itself is untouched by the preview.
        assert_eq!(doc.view(), before);

        let mut applied = doc.clone();
        applied
            .apply_image_with(
                target,
                Some(base),
                ApplyChannel::Rgb,
                ApplyBlend::Mode {
                    mode: BlendMode::Multiply,
                },
                None,
                100,
                false,
                false,
            )
            .unwrap();
        assert_eq!(preview, applied.layer(target).unwrap().pixels);
    }

    #[test]
    fn apply_image_preview_propagates_errors_like_apply_image_with() {
        let (doc, base, target) = apply_image_fixture();
        let bad_opacity = doc
            .apply_image_preview(
                target,
                Some(base),
                ApplyChannel::Rgb,
                ApplyBlend::Mode {
                    mode: BlendMode::Normal,
                },
                None,
                101,
                false,
                false,
            )
            .unwrap_err();
        assert!(bad_opacity.contains("Opacity"), "{bad_opacity}");
        let bad_target = doc
            .apply_image_preview(
                999,
                Some(base),
                ApplyChannel::Rgb,
                ApplyBlend::Mode {
                    mode: BlendMode::Normal,
                },
                None,
                100,
                false,
                false,
            )
            .unwrap_err();
        assert!(
            bad_target.contains("layer") || bad_target.contains("Layer"),
            "{bad_target}"
        );
        let bad_source = doc
            .apply_image_preview(
                target,
                Some(999),
                ApplyChannel::Rgb,
                ApplyBlend::Mode {
                    mode: BlendMode::Normal,
                },
                None,
                100,
                false,
                false,
            )
            .unwrap_err();
        assert!(
            bad_source.contains("layer") || bad_source.contains("Layer"),
            "{bad_source}"
        );
    }

